// ================================================================
// TIMEOUT-PROTECTED POPEN: Prevents infinite hangs from bitcoin-cli
// Uses fork + waitpid with WNOHANG polling loop.
// ================================================================
static constexpr int POPEN_TIMEOUT_DEFAULT = 2;

struct PopenResult {
    std::string output;
    int exit_status;
    bool timed_out;
};

// Timeout dedup: suppress repeated warnings for same command target
static std::mutex g_timeout_dedup_mtx_;
static std::set<std::string> g_timeout_dedup_seen_;

static PopenResult popen_with_timeout(const std::string& cmd, int timeout_sec = POPEN_TIMEOUT_DEFAULT) {
    PopenResult pr;
    pr.exit_status = -1;
    pr.timed_out = false;

    int pipefd[2];
    if (pipe(pipefd) < 0) return pr;

    pid_t child = fork();
    if (child < 0) { close(pipefd[0]); close(pipefd[1]); return pr; }

    if (child == 0) {
        // Child: redirect stdout+stderr to pipe, exec shell
        close(pipefd[0]);
        dup2(pipefd[1], STDOUT_FILENO);
        dup2(pipefd[1], STDERR_FILENO);
        close(pipefd[1]);
        execl("/bin/sh", "sh", "-c", cmd.c_str(), (char*)nullptr);
        _exit(127);
    }

    // Parent: read from pipe with timeout
    close(pipefd[1]);

    // Set pipe to non-blocking
    int flags = fcntl(pipefd[0], F_GETFL, 0);
    fcntl(pipefd[0], F_SETFL, flags | O_NONBLOCK);

    auto start = std::chrono::steady_clock::now();
    char buf[4096];
    bool child_done = false;

    while (true) {
        auto elapsed = std::chrono::duration_cast<std::chrono::seconds>(
            std::chrono::steady_clock::now() - start).count();
        if (elapsed >= timeout_sec) {
            // Timeout: kill child immediately — no graceful stop, no waiting
            kill(child, SIGKILL);
            int wstatus;
            waitpid(child, &wstatus, 0);
            pr.timed_out = true;
            {
                std::lock_guard<std::mutex> _lk(g_timeout_dedup_mtx_);
                std::string _key = cmd.substr(0, std::min(cmd.size(), (size_t)80));
                if (g_timeout_dedup_seen_.insert(_key).second) {
                    fprintf(stderr, "[WARN] popen_timeout: Command timed out after %ds: %.120s\n",
                        timeout_sec, cmd.c_str());
                }
            }
            break;
        }

        // Try to read
        ssize_t n = read(pipefd[0], buf, sizeof(buf) - 1);
        if (n > 0) {
            buf[n] = 0;
            pr.output += buf;
        } else if (n == 0) {
            // EOF — child closed its end
            break;
        } else {
            // EAGAIN — no data yet
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // Check if child has exited
                int wstatus;
                pid_t w = waitpid(child, &wstatus, WNOHANG);
                if (w > 0) { child_done = true; pr.exit_status = WEXITSTATUS(wstatus); }
                // Small sleep to avoid busy-wait
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
                continue;
            }
            break;
        }
    }
    close(pipefd[0]);

    // Reap child if not already
    if (!child_done && !pr.timed_out) {
        int wstatus;
        waitpid(child, &wstatus, 0);
        pr.exit_status = WIFEXITED(wstatus) ? WEXITSTATUS(wstatus) : -1;
    }
    return pr;
}

// Fast cached vmmap availability check. Uses access() only — no popen, no recursion.
// On Linux vmmap does not exist; on macOS it may be blocked by SIP.
static bool vmmap_ok() {
    static int c = -1;
    if (c >= 0) return c == 1;
#ifdef __APPLE__
    c = (access("/usr/bin/vmmap", X_OK) == 0) ? 1 : 0;
#else
    c = 0;
#endif
    return c == 1;
}
static PopenResult vmmap_run(const std::string& cmd, int timeout_sec = 1) {
    if (!vmmap_ok()) { PopenResult r; r.timed_out = false; r.exit_status = 1; r.output = "0"; return r; }
    return popen_with_timeout(cmd, timeout_sec);
}



class WordBoundaryClassifier {
public:
    struct ClassificationResult {
        bool is_sensitive;
        std::string matched_pattern;
        double confidence;
        std::string classification_reason;
        bool is_known_non_sensitive;
    };

    static const std::vector<std::string>& sensitive_data_patterns_v31() {
        static const std::vector<std::string> patterns = {
            "CKey", "CPrivKey", "CKeyingMaterial", "CMasterKey", "CCrypter",
            "CExtKey", "CExtPubKey", "CHDChain", "CKeyMetadata",
            "vchSecret", "vchCryptedKey", "vMasterKey", "vchPrivKey",
            "passphrase", "strWalletPassphrase", "strNewWalletPassphrase",
            "strOldWalletPassphrase", "mKey", "kMasterKey",
            "pMasterKey", "mapKeys", "mapCryptedKeys",
            "setKeyPool", "vchPubKey", "secret", "privkey", "masterkey",
            "seed", "hdseed", "hdmaster", "keypool", "ckey",
            "wallet_passphrase", "rpcpassword", "rpcuser",
            "encryption_key", "decryption_key", "aes_key", "aes_iv",
            "nonce", "salt", "derived_key", "key_material",
            "signing_key", "verification_key", "session_key",
            "ephemeral_key", "shared_secret", "preimage"
        };
        return patterns;
    }

    static const std::set<std::string>& known_non_sensitive_tokens() {
        static const std::set<std::string> tokens = {
            "key_press", "key_event", "keyboard", "keynote",
            "key_count", "key_index", "key_name", "key_type",
            "keyframe", "keystroke", "key_binding", "key_code",
            "primary_key", "foreign_key", "hash_key", "map_key",
            "sort_key", "config_key", "cache_key", "lookup_key",
            "registry_key", "key_value", "key_pair_count",
            "password_policy", "password_length", "password_hash",
            "password_strength", "password_validator", "has_password",
            "needs_password", "password_required", "password_prompt",
            "secret_count", "secret_name", "secret_type", "secret_id",
            "secret_manager", "no_secret", "is_secret"
        };
        return tokens;
    }

    static bool word_boundary_match(const std::string& variable_name,
                                     const std::vector<std::string>& patterns) {
        for (const auto& pattern : patterns) {
            if (variable_name == pattern) return true;
            size_t pos = variable_name.find(pattern);
            while (pos != std::string::npos) {
                bool left_boundary = (pos == 0) ||
                    (!std::isalnum(variable_name[pos - 1]) && variable_name[pos - 1] != '_');
                bool right_boundary = (pos + pattern.size() >= variable_name.size()) ||
                    (!std::isalnum(variable_name[pos + pattern.size()]) &&
                     variable_name[pos + pattern.size()] != '_');
                // Allow camelCase boundaries
                if (!left_boundary && pos > 0 && std::islower(variable_name[pos - 1]) &&
                    std::isupper(pattern[0])) {
                    left_boundary = true;
                }
                if (left_boundary && right_boundary) return true;
                pos = variable_name.find(pattern, pos + 1);
            }
        }
        return false;
    }

    static bool is_known_non_sensitive_token(const std::string& name) {
        std::string lower_name = name;
        std::transform(lower_name.begin(), lower_name.end(), lower_name.begin(), ::tolower);
        return known_non_sensitive_tokens().count(lower_name) > 0;
    }

    static ClassificationResult classify(const std::string& variable_name) {
        ClassificationResult result;
        result.is_known_non_sensitive = is_known_non_sensitive_token(variable_name);
        if (result.is_known_non_sensitive) {
            result.is_sensitive = false;
            result.confidence = 0.95;
            result.classification_reason = "Known non-sensitive token: " + variable_name;
            return result;
        }
        result.is_sensitive = word_boundary_match(variable_name, sensitive_data_patterns_v31());
        if (result.is_sensitive) {
            for (const auto& pattern : sensitive_data_patterns_v31()) {
                if (variable_name.find(pattern) != std::string::npos) {
                    result.matched_pattern = pattern;
                    break;
                }
            }
            result.confidence = 0.85;
            result.classification_reason = "Matched sensitive pattern: " + result.matched_pattern;
        } else {
            result.confidence = 0.90;
            result.classification_reason = "No sensitive pattern match";
        }
        return result;
    }
};


// ============================================================================
// SECTION 42: PATCH 4 - TEMPLATE-AWARE TYPE EXTRACTION
// ============================================================================

class TemplateTypeExtractor {
public:
    struct TypeExtractionResult {
        std::string full_type;
        std::string base_type;
        std::vector<std::string> template_args;
        bool is_plain_byte_vector;
        bool uses_secure_allocator;
        bool is_sensitive_container;
    };

    static TypeExtractionResult extract_full_type(const std::vector<Token>& tokens, size_t start_pos) {
        TypeExtractionResult result;
        result.is_plain_byte_vector = false;
        result.uses_secure_allocator = false;
        result.is_sensitive_container = false;
        if (start_pos >= tokens.size()) return result;

        std::string type_str;
        int angle_depth = 0;
        size_t pos = start_pos;
        while (pos < tokens.size()) {
            const auto& tok = tokens[pos];
            if (tok.type == TokenType::Identifier || tok.type == TokenType::Keyword) {
                type_str += tok.text;
            } else if (tok.text == "<") { angle_depth++; type_str += "<"; }
            else if (tok.text == ">") { angle_depth--; type_str += ">"; if (angle_depth <= 0) { pos++; break; } }
            else if (tok.text == ",") { if (angle_depth > 0) type_str += ","; else break; }
            else if (tok.text == "*" || tok.text == "&" || tok.text == "::") { type_str += tok.text; }
            else if (angle_depth == 0) break;
            else type_str += tok.text;
            pos++;
        }
        result.full_type = type_str;
        size_t angle_pos = type_str.find('<');
        result.base_type = (angle_pos != std::string::npos) ? type_str.substr(0, angle_pos) : type_str;
        result.is_plain_byte_vector = is_plain_byte_vector(type_str);
        result.uses_secure_allocator = check_secure_allocator(type_str);
        if (result.uses_secure_allocator) result.is_sensitive_container = true;
        else if (result.is_plain_byte_vector) result.is_sensitive_container = false;

        if (angle_pos != std::string::npos) {
            std::string args_str = type_str.substr(angle_pos + 1);
            if (!args_str.empty() && args_str.back() == '>') args_str.pop_back();
            int depth = 0;
            std::string current_arg;
            for (char c : args_str) {
                if (c == '<') depth++;
                else if (c == '>') depth--;
                else if (c == ',' && depth == 0) {
                    if (!current_arg.empty()) result.template_args.push_back(current_arg);
                    current_arg.clear();
                    continue;
                }
                current_arg += c;
            }
            if (!current_arg.empty()) result.template_args.push_back(current_arg);
        }
        return result;
    }

    static bool is_plain_byte_vector(const std::string& type_str) {
        if (type_str.find("vector") == std::string::npos) return false;
        if (type_str.find("unsigned char") == std::string::npos &&
            type_str.find("uint8_t") == std::string::npos &&
            type_str.find("byte") == std::string::npos) return false;
        if (type_str.find("secure_allocator") != std::string::npos) return false;
        return true;
    }

    static bool check_secure_allocator(const std::string& type_str) {
        return type_str.find("secure_allocator") != std::string::npos ||
               type_str.find("LockedPool") != std::string::npos ||
               type_str.find("CKeyingMaterial") != std::string::npos;
    }
};

// ============================================================================
// SECTION 43: PATCH 5 - DATA FLOW TRANSFER DETECTION
// ============================================================================

class DataTransferDetector {
public:
    struct TransferEdge {
        std::string source_var;
        std::string dest_var;
        std::string transfer_type;
        SourceLocation location;
        bool preserves_sensitivity;
    };

    static std::vector<TransferEdge> detect_transfers(const std::vector<Token>& tokens, const std::string& file_path) {
        std::vector<TransferEdge> edges;
        for (size_t i = 0; i + 4 < tokens.size(); i++) {
            // std::move detection
            if (tokens[i].text == "std" && tokens[i+1].text == "::" && tokens[i+2].text == "move") {
                TransferEdge edge;
                edge.transfer_type = "move";
                edge.location = tokens[i].location;
                edge.preserves_sensitivity = true;
                if (i + 3 < tokens.size() && tokens[i+3].text == "(") {
                    size_t paren_depth = 1;
                    size_t j = i + 4;
                    std::string arg;
                    while (j < tokens.size() && paren_depth > 0) {
                        if (tokens[j].text == "(") paren_depth++;
                        else if (tokens[j].text == ")") { paren_depth--; if (paren_depth == 0) break; }
                        if (tokens[j].type == TokenType::Identifier) arg = tokens[j].text;
                        j++;
                    }
                    edge.source_var = arg;
                    for (int k = static_cast<int>(i) - 1; k >= 0 && k >= static_cast<int>(i) - 5; k--) {
                        if (tokens[k].text == "=" || tokens[k].text == "(") {
                            for (int m = k - 1; m >= 0; m--) {
                                if (tokens[m].type == TokenType::Identifier) { edge.dest_var = tokens[m].text; break; }
                            }
                            break;
                        }
                    }
                    if (!edge.source_var.empty()) edges.push_back(edge);
                }
            }
            // std::swap detection
            if (tokens[i].text == "std" && tokens[i+1].text == "::" && tokens[i+2].text == "swap") {
                TransferEdge edge;
                edge.transfer_type = "swap";
                edge.location = tokens[i].location;
                edge.preserves_sensitivity = true;
                if (i + 3 < tokens.size() && tokens[i+3].text == "(") {
                    size_t j = i + 4;
                    std::vector<std::string> args;
                    std::string current;
                    int depth = 1;
                    while (j < tokens.size() && depth > 0) {
                        if (tokens[j].text == "(") depth++;
                        else if (tokens[j].text == ")") { depth--; if (depth == 0) break; }
                        else if (tokens[j].text == "," && depth == 1) {
                            if (!current.empty()) args.push_back(current);
                            current.clear(); j++; continue;
                        }
                        if (tokens[j].type == TokenType::Identifier) current = tokens[j].text;
                        j++;
                    }
                    if (!current.empty()) args.push_back(current);
                    if (args.size() >= 2) {
                        edge.source_var = args[0]; edge.dest_var = args[1];
                        edges.push_back(edge);
                        TransferEdge reverse = edge;
                        std::swap(reverse.source_var, reverse.dest_var);
                        edges.push_back(reverse);
                    }
                }
            }
            // emplace_back detection
            if (tokens[i].text == "emplace_back" || tokens[i].text == "emplace") {
                TransferEdge edge;
                edge.transfer_type = tokens[i].text;
                edge.location = tokens[i].location;
                edge.preserves_sensitivity = true;
                for (int k = static_cast<int>(i) - 1; k >= 0; k--) {
                    if (tokens[k].text == "." || tokens[k].text == "->") {
                        if (k > 0 && tokens[k-1].type == TokenType::Identifier) edge.dest_var = tokens[k-1].text;
                        break;
                    }
                }
                if (i + 1 < tokens.size() && tokens[i+1].text == "(") {
                    size_t j = i + 2;
                    while (j < tokens.size() && tokens[j].text != ")") {
                        if (tokens[j].type == TokenType::Identifier) { edge.source_var = tokens[j].text; break; }
                        j++;
                    }
                }
                if (!edge.source_var.empty() && !edge.dest_var.empty()) edges.push_back(edge);
            }
        }
        return edges;
    }
};


// ============================================================================
// SECTION 44: PATCH 6 - RAII CLEANUP RECOGNITION
// ============================================================================

class RAIICleanupVerifier {
public:
    struct CleanupVerification {
        std::string type_name;
        bool has_raii_cleanup;
        bool has_destructor_cleanup;
        bool has_scope_guard;
        double verification_confidence;
        std::string cleanup_mechanism;
    };

    static const std::set<std::string>& known_raii_cleanup_types() {
        static const std::set<std::string> types = {
            "CKey", "CPrivKey", "CKeyingMaterial", "SecureString", "secure_string",
            "CCrypter", "std::unique_ptr", "std::shared_ptr",
            "LOCK", "LOCK2", "TRY_LOCK", "cs_wallet", "cs_KeyStore", "cs_main",
            "unique_lock", "lock_guard", "shared_lock", "scoped_lock",
            "CWalletDBWrapper", "ArgsManager", "CConnman",
            "CDBBatch", "CDBIterator", "CDBWrapper",
            "CAutoFile", "CBufferedFile", "CSizeComputer",
            "CHashWriter", "CDataStream"
        };
        return types;
    }

    static CleanupVerification verify_raii_cleanup(const std::string& type_name,
                                                     const std::string& variable_scope_body) {
        CleanupVerification result;
        result.type_name = type_name;
        result.has_raii_cleanup = false;
        result.has_destructor_cleanup = false;
        result.has_scope_guard = false;
        result.verification_confidence = 0.0;

        for (const auto& raii_type : known_raii_cleanup_types()) {
            if (type_name.find(raii_type) != std::string::npos) {
                result.has_raii_cleanup = true;
                result.cleanup_mechanism = "Known RAII type: " + raii_type;
                result.verification_confidence = 0.92;
                break;
            }
        }

        if (variable_scope_body.find("memory_cleanse") != std::string::npos ||
            variable_scope_body.find("OPENSSL_cleanse") != std::string::npos ||
            variable_scope_body.find("SecureErase") != std::string::npos ||
            variable_scope_body.find("cleanse") != std::string::npos) {
            result.has_destructor_cleanup = true;
            result.cleanup_mechanism += " + explicit cleanse call";
            result.verification_confidence = std::max(result.verification_confidence, 0.95);
        }

        if (variable_scope_body.find("ScopeGuard") != std::string::npos ||
            variable_scope_body.find("scope_exit") != std::string::npos ||
            variable_scope_body.find("AT_SCOPE_EXIT") != std::string::npos) {
            result.has_scope_guard = true;
            result.cleanup_mechanism += " + scope guard";
            result.verification_confidence = std::max(result.verification_confidence, 0.90);
        }

        if (type_name.find("CKeyingMaterial") != std::string::npos) {
            result.has_raii_cleanup = true;
            result.has_destructor_cleanup = true;
            result.cleanup_mechanism = "CKeyingMaterial uses secure_allocator with automatic cleanup";
            result.verification_confidence = 0.98;
        }
        return result;
    }
};

// ============================================================================
// SECTION 45: PATCH 7 - LOCK GUARD AWARENESS
// ============================================================================

class LockGuardAwareness {
public:
    struct LockScopeInfo {
        std::string lock_name;
        std::string mutex_name;
        SourceLocation lock_location;
        SourceLocation scope_start;
        SourceLocation scope_end;
        bool is_unconditional_scope;
    };

    static bool is_inside_lock_guard(const std::vector<Token>& tokens,
                                      const SourceLocation& cleanup_location) {
        for (size_t i = 0; i < tokens.size(); i++) {
            if (tokens[i].location.line > cleanup_location.line) break;
            if (tokens[i].text == "LOCK" || tokens[i].text == "LOCK2" ||
                tokens[i].text == "TRY_LOCK" || tokens[i].text == "lock_guard" ||
                tokens[i].text == "unique_lock" || tokens[i].text == "scoped_lock" ||
                tokens[i].text == "shared_lock") {
                int brace_depth = 0;
                bool in_scope = false;
                for (size_t j = i; j < tokens.size(); j++) {
                    if (tokens[j].text == "{") { brace_depth++; in_scope = true; }
                    else if (tokens[j].text == "}") {
                        brace_depth--;
                        if (in_scope && brace_depth <= 0) {
                            if (cleanup_location.line >= tokens[i].location.line &&
                                cleanup_location.line <= tokens[j].location.line) return true;
                            break;
                        }
                    }
                }
            }
        }
        return false;
    }

    static bool is_genuinely_conditional_cleanup(const std::vector<Token>& tokens,
                                                   const SourceLocation& cleanup_location) {
        for (size_t i = 0; i < tokens.size(); i++) {
            if (tokens[i].location.line > cleanup_location.line) break;
            if (tokens[i].text == "if" || tokens[i].text == "else" ||
                tokens[i].text == "for" || tokens[i].text == "while") {
                bool preceded_by_lock = false;
                if (i > 0) {
                    for (size_t k = (i > 5 ? i - 5 : 0); k < i; k++) {
                        if (tokens[k].text == "LOCK" || tokens[k].text == "LOCK2") {
                            preceded_by_lock = true; break;
                        }
                    }
                }
                if (!preceded_by_lock) {
                    int depth = 0;
                    for (size_t j = i + 1; j < tokens.size(); j++) {
                        if (tokens[j].text == "{") depth++;
                        else if (tokens[j].text == "}") {
                            depth--;
                            if (depth <= 0) {
                                if (cleanup_location.line >= tokens[i].location.line &&
                                    cleanup_location.line <= tokens[j].location.line) return true;
                                break;
                            }
                        }
                    }
                }
            }
        }
        return false;
    }
};

