        // KL-DEAD-STORE: Check for dead stores of secret material
        {
            int emaj_dse = effective_major(ver);
            // Scan binary for known secret-handling patterns
            auto nm_check = popen_with_timeout(
                "nm -g '" + inst.binary_path + "' 2>/dev/null | grep -ci 'cleanse\\|memwipe\\|zero_mem\\|secure_erase' || echo '0'", 3);
            std::string nm_out = nm_check.output;
            while (!nm_out.empty() && !isdigit(nm_out.back())) nm_out.pop_back();
            int cleanse_syms = 0;
            try { cleanse_syms = std::stoi(nm_out); } catch(...) {}
            results.push_back(make_finding(ver, "key_leakage",
                cleanse_syms > 0 ? "KL-DEAD-STORE-CLEANSE-PRESENT" : "KL-DEAD-STORE-CLEANSE-MISSING",
                "Dead store analysis: v" + std::to_string(emaj_dse) +
                " cleanse/wipe symbols=" + std::to_string(cleanse_syms) +
                (cleanse_syms == 0 ? " — no explicit memory cleanse detected in binary" :
                                     " — memory cleansing functions present"),
                "syms=" + std::to_string(cleanse_syms), cleanse_syms == 0 ? 5 : 1));
        }

        // KL-ZEROIZATION-VERIFY: Verify key material is zeroed after lock
        {
            int emaj_zv = effective_major(ver);
            // Unlock, generate key, lock, then check if dumpprivkey still works
            rpc_fast(inst, "walletpassphrase",
                "[\"" + wallet_encryption_passphrase_ + "\", 2]");
            std::string test_addr_zv = rpc_safe(inst, "getnewaddress");
            rpc_fast(inst, "walletlock", "[]");
            std::this_thread::sleep_for(std::chrono::milliseconds(500));
            // After lock, dumpprivkey should fail
            auto dpk_locked = rpc(inst, "dumpprivkey", "\"" + test_addr_zv + "\"");
            bool properly_locked = dpk_locked.is_error();
            // Try multiple times to catch race conditions
            int lock_failures = 0;
            for (int lf = 0; lf < 3; lf++) {
                rpc_fast(inst, "walletpassphrase",
                    "[\"" + wallet_encryption_passphrase_ + "\", 1]");
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
                rpc_fast(inst, "walletlock", "[]");
                auto dpk_race = rpc(inst, "dumpprivkey", "\"" + test_addr_zv + "\"");
                if (!dpk_race.is_error()) lock_failures++;
            }
            results.push_back(make_finding(ver, "key_leakage",
                (properly_locked && lock_failures == 0) ?
                    "KL-ZEROIZATION-VERIFY-PASS" : "KL-ZEROIZATION-VERIFY-FAIL",
                "Zeroization: v" + std::to_string(emaj_zv) +
                " locked_properly=" + (properly_locked?"Y":"N") +
                " race_failures=" + std::to_string(lock_failures) +
                (lock_failures > 0 ? " — CRITICAL: key accessible after lock via race" : " — clean"),
                "locked=" + std::string(properly_locked?"Y":"N") +
                " races=" + std::to_string(lock_failures),
                lock_failures > 0 ? 8 : 1));
        }

        // KL-KEYPOOL-LEAK: Check keypool behaviour after encryption
