    // ----------------------------------------------------------------
    // INFRASTRUCTURE: Discovery Trace Logger
    // ----------------------------------------------------------------
    struct DiscoveryTrace {
        std::string finding_id;
        std::string engine;
        std::string version;
        std::string detection_trigger;
        std::vector<std::string> rpc_transcript;
        std::map<std::string, std::string> backtest_matrix;
        std::string environment;
        std::string final_determination;
        double detection_time_ms = 0;

        std::string to_json() const {
            std::ostringstream j;
            j << "{\n  \"finding_id\": \"" << finding_id << "\",\n"
              << "  \"engine\": \"" << engine << "\",\n"
              << "  \"version\": \"" << version << "\",\n"
              << "  \"detection_trigger\": \"" << detection_trigger << "\",\n"
              << "  \"detection_time_ms\": " << detection_time_ms << ",\n"
              << "  \"rpc_transcript\": [\n";
            for (size_t i = 0; i < rpc_transcript.size(); i++) {
                j << "    \"";
                for (char c : rpc_transcript[i]) {
                    if (c == '"') j << "\\\"";
                    else if (c == '\\') j << "\\\\";
                    else if (c == '\n') j << "\\n";
                    else j << c;
                }
                j << "\"";
                if (i + 1 < rpc_transcript.size()) j << ",";
                j << "\n";
            }
            j << "  ],\n  \"backtest_matrix\": {\n";
            size_t bi = 0;
            for (const auto& kv : backtest_matrix) {
                j << "    \"" << kv.first << "\": \"" << kv.second << "\"";
                if (++bi < backtest_matrix.size()) j << ",";
                j << "\n";
            }
            j << "  },\n  \"environment\": \"" << environment << "\",\n"
              << "  \"final_determination\": \"" << final_determination << "\"\n}";
            return j.str();
        }
    };

    void write_discovery_trace(const DiscoveryTrace& trace, const std::string& base_dir) {
        std::string dir = base_dir + "/discovery_traces";
        std::filesystem::create_directories(dir);
        std::string safe = trace.finding_id;
        for (auto& c : safe) if (!std::isalnum(c) && c != '-' && c != '_') c = '_';
        std::string path = dir + "/" + safe + ".json";
        std::ofstream ofs(path);
        if (ofs.is_open()) { ofs << trace.to_json(); ofs.close(); }
    }

    // ----------------------------------------------------------------
    // INFRASTRUCTURE: Thermal Probe Fix (non-privileged, cached)
    // ----------------------------------------------------------------
    struct ThermalReading {
        double cpu_temp_c = -1.0;
        double cpu_speed_limit = -1.0;
        bool available = false;
        std::chrono::steady_clock::time_point timestamp;
    };
    ThermalReading cached_thermal_;
    std::mutex thermal_mutex_;

    ThermalReading get_thermal_reading_safe() {
        std::lock_guard<std::mutex> lock(thermal_mutex_);
        auto now = std::chrono::steady_clock::now();
        if (cached_thermal_.available &&
            std::chrono::duration_cast<std::chrono::seconds>(now - cached_thermal_.timestamp).count() < 10)
            return cached_thermal_;
        ThermalReading tr; tr.timestamp = now;
        // macOS: sysctl (no sudo)
        FILE* fp = popen("timeout 1 sysctl -n machdep.xcpm.cpu_thermal_level 2>/dev/null", "r");
        if (fp) { char buf[64]={}; if(fgets(buf,sizeof(buf),fp)) { try{tr.cpu_temp_c=std::stod(buf);tr.available=true;}catch(...){} } pclose(fp); }
        if (!tr.available) {
            fp = popen("timeout 1 pmset -g therm 2>/dev/null | grep -i cpu_speed_limit | awk '{print $2}'", "r");
            if (fp) { char buf[64]={}; if(fgets(buf,sizeof(buf),fp)) { try{tr.cpu_speed_limit=std::stod(buf);tr.available=true;}catch(...){} } pclose(fp); }
        }
        // Linux fallback
        if (!tr.available) {
            std::ifstream tf("/sys/class/thermal/thermal_zone0/temp");
            if (tf.is_open()) { int mt; tf>>mt; tr.cpu_temp_c=mt/1000.0; tr.available=true; tf.close(); }
        }
        cached_thermal_ = tr;
        return tr;
    }

    // ----------------------------------------------------------------
    // INFRASTRUCTURE: Timing helper
    // ----------------------------------------------------------------
    struct TimingMeasurement {
        double elapsed_ms; std::string response; bool success; int error_code;
    };

    TimingMeasurement timed_rpc(const VersionInstance& inst, const std::string& method,
                                 const std::string& params = "[]") {
        TimingMeasurement tm;
        auto t0 = std::chrono::high_resolution_clock::now();
        auto r = rpc_fast(inst, method, params);
        auto t1 = std::chrono::high_resolution_clock::now();
        tm.elapsed_ms = std::chrono::duration<double, std::milli>(t1-t0).count();
        tm.response = r.output; tm.success = r.success; tm.error_code = 0;
        std::string cs = jx(r.output, "code");
        if (!cs.empty()) try { tm.error_code = std::stoi(cs); } catch (...) {}
        return tm;
    }

    // ----------------------------------------------------------------
    // INFRASTRUCTURE: Verification Script Generator v2
    // ----------------------------------------------------------------
    void generate_verification_script(const DynamicFinding& finding,
                                       const VersionInstance& inst,
                                       const std::string& output_dir) {
        if (finding.severity < 7) return;
        std::string safe_id = finding.finding_id;
        for (auto& c : safe_id) if (!std::isalnum(c) && c!='-' && c!='_' && c!='.') c='_';
        std::string sp = output_dir + "/VERIFY_" + safe_id + ".py";
        std::ostringstream py;
        py << "#!/usr/bin/env python3\n"
           << "\"\"\"Auto-generated verification: " << finding.finding_id << "\n"
           << "Version: " << finding.version << " | Severity: " << finding.severity << "/10\n"
           << finding.description.substr(0, 200) << "\n\"\"\"\n"
           << "import sys,json,subprocess,time,os,struct,hashlib\n\n"
           << "PORT=int(sys.argv[1]) if len(sys.argv)>1 else " << inst.rpc_port << "\n"
           << "USER=sys.argv[2] if len(sys.argv)>2 else '" << inst.rpc_user << "'\n"
           << "PASS=sys.argv[3] if len(sys.argv)>3 else '" << inst.rpc_password << "'\n"
           << "CLI=os.environ.get('BITCOIN_CLI','bitcoin-cli')\n\n"
           << "def rpc(m,*a):\n"
           << "  cmd=[CLI,'-regtest',f'-rpcport={PORT}',f'-rpcuser={USER}',f'-rpcpassword={PASS}',m]+[str(x) for x in a]\n"
           << "  try: r=subprocess.run(cmd,capture_output=True,text=True,timeout=15); return r.stdout.strip(),r.returncode\n"
           << "  except: return 'ERR',-1\n\n"
           << "def main():\n"
           << "  print(f'=== Verify: " << finding.finding_id << " ===')\n"
           << "  o,rc=rpc('getblockchaininfo')\n"
           << "  if rc!=0: print('SKIP: node unreachable'); sys.exit(2)\n";
        if (finding.category.find("wal_lock") != std::string::npos) {
            py << "  rpc('encryptwallet','tp'); time.sleep(3)\n"
               << "  for _ in range(10):\n"
               << "    if rpc('getblockcount')[1]==0: break\n"
               << "    time.sleep(1)\n"
               << "  rpc('walletlock'); f=0\n"
               << "  for m in ['sendtoaddress','dumpprivkey','signmessage','keypoolrefill']:\n"
               << "    o,r=rpc(m,'test')\n"
               << "    if r==0 and 'error' not in o.lower(): f+=1; print(f'  FAIL: {m}')\n"
               << "    else: print(f'  PASS: {m}')\n"
               << "  print(f'RESULT: {\"FAIL\" if f else \"PASS\"}'); sys.exit(1 if f else 0)\n";
        } else if (finding.category.find("kl_kr") != std::string::npos) {
            py << "  wp=f'/tmp/v_{PORT}.dat'; rpc('backupwallet',wp)\n"
               << "  try:\n"
               << "    with open(wp,'rb') as f: d=f.read()\n"
               << "    n=sum(1 for i in range(len(d)-5) if d[i]==0x30 and d[i+1] in (0x81,0x82) and d[i+3]==2 and d[i+4]==1 and d[i+5]==1)\n"
               << "    print(f'Patterns: {n}'); print(f'RESULT: {\"FAIL\" if n>10 else \"PASS\"}'); sys.exit(1 if n>10 else 0)\n"
               << "  except Exception as e: print(f'SKIP: {e}'); sys.exit(2)\n"
               << "  finally:\n    try: os.unlink(wp)\n    except: pass\n";
        } else if (finding.category.find("bf_") != std::string::npos or finding.category.find("kl_pad") != std::string::npos) {
            py << "  rpc('encryptwallet','tp'); time.sleep(3)\n"
               << "  for _ in range(10):\n"
               << "    if rpc('getblockcount')[1]==0: break\n"
               << "    time.sleep(1)\n"
               << "  rpc('walletlock'); errs,ts=set(),[]\n"
               << "  for p in ['x','y'*64,'z'*256,'ab','A'*32]:\n"
               << "    t0=time.monotonic(); o,_=rpc('walletpassphrase',p,'1')\n"
               << "    ts.append(time.monotonic()-t0); errs.add(o[:80])\n"
               << "  leak=len(errs)>1 or max(ts)-min(ts)>0.5\n"
               << "  print(f'Errors:{len(errs)} Range:{max(ts)-min(ts):.4f}s')\n"
               << "  print(f'RESULT: {\"FAIL\" if leak else \"PASS\"}'); sys.exit(1 if leak else 0)\n";
        } else if (finding.category.find("cs_") != std::string::npos) {
            py << "  o,r=rpc('sendrawtransaction','deadbeef00000000')\n"
               << "  rej=r!=0 or 'error' in o.lower()\n"
               << "  print(f'RESULT: {\"PASS\" if rej else \"FAIL\"}'); sys.exit(0 if rej else 1)\n";
        } else if (finding.category.find("rpc_auth") != std::string::npos) {
            py << "  import socket; s=socket.socket(); s.settimeout(3)\n"
               << "  try:\n"
               << "    s.connect(('127.0.0.1',PORT))\n"
               << "    s.send(b'POST / HTTP/1.1\\r\\nHost: x\\r\\nContent-Length: 2\\r\\n\\r\\n{}')\n"
               << "    r=s.recv(1024).decode(errors='replace')\n"
               << "    rej='401' in r or '403' in r\n"
               << "    print(f'RESULT: {\"PASS\" if rej else \"FAIL\"}'); sys.exit(0 if rej else 1)\n"
               << "  except: print('SKIP'); sys.exit(2)\n  finally: s.close()\n";
        } else {
            py << "  print('Manual review required for: " << finding.category << "')\n"
               << "  print('RESULT: MANUAL'); sys.exit(0)\n";
        }
        py << "\nif __name__=='__main__': main()\n";
        std::ofstream ofs(sp);
        if (ofs.is_open()) { ofs << py.str(); ofs.close(); chmod(sp.c_str(), 0755); }
    }

    void generate_all_verification_scripts(const std::vector<DynamicFinding>& findings,
                                            const VersionInstance& inst,
                                            const std::string& output_dir) {
        std::string dir = output_dir + "/verify_scripts/" + inst.version_string;
        std::filesystem::create_directories(dir);
        int gen = 0;
        for (const auto& f : findings) {
            if (f.severity >= 7) { generate_verification_script(f, inst, dir); gen++; }
        }
        if (gen > 0)
            EnhancedStructuredLogger::instance()->log(LogLevel::INFO, "verify_scripts",
                inst.version_string + ": Generated " + std::to_string(gen) + " verification scripts");
    }

    // ================================================================
    // ENGINE A: WAL-RPC-LOCK-GATE (enhanced with unlock-relock + trace)
    // ================================================================
    std::vector<DynamicFinding> engine_wal_lock_gate(VersionInstance& inst, const ChainParams& p) {
        ScopedProfile prof("WAL-LOCK", "wal_lock_gate_" + inst.version_string);
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        int em = effective_major(ver);
        if (!p.wallet_available) {
            results.push_back(make_finding(ver, "wal_lock_gate", "WAL-LOCK-GATE-SKIP", "SKIP: No wallet", "", 0));
            return results;
        }
        DiscoveryTrace trace;
        trace.engine = "WAL-RPC-LOCK-GATE"; trace.version = ver;
        trace.detection_trigger = "Testing 6 sensitive RPCs after unlock-relock cycle";
        auto t0 = std::chrono::high_resolution_clock::now();
        if (!p.wallet_encrypted) {
            auto enc = rpc(inst, "encryptwallet", "\"" + wallet_encryption_passphrase_ + "\"");
            trace.rpc_transcript.push_back("encryptwallet -> " + enc.output.substr(0, 100));
            if (!enc.success || enc.is_error()) {
                if (em >= 23) {
                    results.push_back(make_finding(ver, "wal_lock_gate", "WAL-LOCK-DESC-NOENC",
                        "INFO: Descriptor wallet does not support encryptwallet in v" + ver, "", 3));
                    return results;
                }
                results.push_back(make_finding(ver, "wal_lock_gate", "WAL-LOCK-ENC-FAIL", "SKIP: encryptwallet failed", "", 0));
                return results;
            }
            std::this_thread::sleep_for(std::chrono::seconds(3));
            for (int _r = 0; _r < 10; _r++) { auto bc = rpc_fast(inst, "getblockcount"); if (bc.success && !bc.is_error()) break; std::this_thread::sleep_for(std::chrono::seconds(1)); }
        }
        // Unlock-relock cycle (tests state after master key was in memory)
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 2");
        trace.rpc_transcript.push_back("walletpassphrase (unlock 2s)");
        std::this_thread::sleep_for(std::chrono::seconds(3));
        rpc(inst, "walletlock");
        trace.rpc_transcript.push_back("walletlock (relock)");
        std::this_thread::sleep_for(std::chrono::milliseconds(500));
        std::string test_addr;
        if (!p.test_addresses.empty()) test_addr = p.test_addresses[0];
        if (test_addr.empty()) test_addr = "bcrt1qw508d6qejxtdg4y5r3zarvary0c5xw7kygt080";
        struct LockTest { std::string method; std::string params; std::string suffix; };
        std::vector<LockTest> tests;
        tests.push_back({"sendtoaddress", "\"" + test_addr + "\" 0.001", "SENDTOADDRESS"});
        if (em < 23) tests.push_back({"dumpprivkey", "\"" + test_addr + "\"", "DUMPPRIVKEY"});
        tests.push_back({"signmessage", "\"" + test_addr + "\" \"test\"", "SIGNMESSAGE"});
        if (em < 23) tests.push_back({"importprivkey", "\"cVpF924EFkHEqR3JDiXTqGXudiVzGeLqfFj6SPZqMRdwaukEsekj\"", "IMPORTPRIVKEY"});
        if (em >= 17 && em < 23) tests.push_back({"sethdseed", "true", "SETHDSEED"});
        tests.push_back({"keypoolrefill", "10", "KEYPOOLREFILL"});
        int bypasses = 0, total = 0;
        std::vector<std::string> bypassed;
        for (const auto& t : tests) {
            auto r2 = rpc(inst, t.method, t.params);
            trace.rpc_transcript.push_back(t.method + " -> " + r2.output.substr(0, 100));
            bool rejected = !r2.success || r2.is_error() ||
                r2.output.find("walletpassphrase") != std::string::npos ||
                r2.output.find("locked") != std::string::npos ||
                r2.output.find("encrypted") != std::string::npos;
            total++;
            if (!rejected) { bypasses++; bypassed.push_back(t.method);
                results.push_back(make_finding(ver, "wal_lock_gate", "WAL-LOCK-" + t.suffix + "-BYPASS",
                    "CRITICAL: " + t.method + " accepted while LOCKED", "resp=" + r2.output.substr(0, 200), 9));
            } else {
                results.push_back(make_finding(ver, "wal_lock_gate", "WAL-LOCK-" + t.suffix + "-OK",
                    "PASS: " + t.method + " rejected while locked", "resp=" + r2.output.substr(0, 100), 0));
            }
        }
        trace.finding_id = "WAL-LOCK-GATE-" + ver;
        trace.detection_time_ms = std::chrono::duration<double,std::milli>(std::chrono::high_resolution_clock::now()-t0).count();
        if (bypasses == 0) { trace.final_determination = "PASS";
            results.push_back(make_finding(ver, "wal_lock_gate", "WAL-LOCK-GATE-PASS",
                "PASS: All " + std::to_string(total) + " RPCs rejected", "", 0));
        } else if (bypasses == total) { trace.final_determination = "CRITICAL-TOTAL";
            results.push_back(make_finding(ver, "wal_lock_gate", "WAL-LOCK-GATE-TOTAL",
                "CRITICAL: ALL " + std::to_string(total) + " RPCs accepted (Phase 2)", "", 10));
        } else {
            std::string bl; for (auto& b : bypassed) { if(!bl.empty()) bl+=","; bl+=b; }
            trace.final_determination = "PARTIAL: " + bl;
            results.push_back(make_finding(ver, "wal_lock_gate", "WAL-LOCK-GATE-PARTIAL",
                "HIGH: " + std::to_string(bypasses) + "/" + std::to_string(total) + " bypassed", "rpcs=" + bl, 8));
        }
        write_discovery_trace(trace, "audit_evidence");
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        return results;
    }

    // ================================================================
    // ENGINE B: OFFLINE KEY-MATERIAL DETECTION (KL-KR FAMILY - 6 engines)
    // ================================================================

    // B.1: KL-KR-BDB-SLACK-PLAINTEXT
    std::vector<DynamicFinding> engine_kl_kr_bdb_slack(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "kl_kr", "KL-KR-BDB-SKIP", "SKIP", "", 0)); return results; }
        ScopedProfile _sp("KR_BDB", "kr_bdb_" + inst.version_string);
        DiscoveryTrace trace; trace.engine = "KL-KR-BDB-SLACK"; trace.version = ver;
        auto _t0_64302 = std::chrono::high_resolution_clock::now();
        trace.detection_trigger = "Scanning BDB free pages for DER EC private key patterns";
        std::string bp = "/tmp/audit_bdb_" + ver + "_" + std::to_string(inst.rpc_port) + ".dat";
        auto bk = rpc(inst, "backupwallet", "\"" + bp + "\"");
        trace.rpc_transcript.push_back("backupwallet -> " + bk.output.substr(0, 80));
        if (!bk.success || bk.is_error()) { results.push_back(make_finding(ver, "kl_kr", "KL-KR-BDB-BKFAIL", "SKIP: Backup failed", "", 0)); return results; }
        std::ifstream wf(bp, std::ios::binary);
        if (!wf.is_open()) { results.push_back(make_finding(ver, "kl_kr", "KL-KR-BDB-RDFAIL", "SKIP", "", 0)); return results; }
        std::vector<uint8_t> wd((std::istreambuf_iterator<char>(wf)), std::istreambuf_iterator<char>()); wf.close();
        size_t page_size = 4096;
        if (wd.size() >= 24) {
            uint32_t ps = (uint32_t(wd[20])<<24)|(uint32_t(wd[21])<<16)|(uint32_t(wd[22])<<8)|uint32_t(wd[23]);
            if (ps >= 512 && ps <= 65536 && (ps & (ps-1)) == 0) page_size = ps;
        }
        size_t num_pages = wd.size() / page_size;
        int free_pages = 0, residual_free = 0, residual_active = 0;
        std::vector<size_t> key_offsets;
        for (size_t pg = 0; pg < num_pages; pg++) {
            size_t base = pg * page_size;
            uint8_t ptype = (base + 25 < wd.size()) ? wd[base + 25] : 0;
            bool is_free = (ptype == 0x00); // BDB: type 0 = free page, type 5 = btree leaf (active)
            if (is_free) free_pages++;
            for (size_t i = base + 26; i + 6 < base + page_size && i + 6 < wd.size(); i++) {
                if (wd[i]==0x30 && (wd[i+1]==0x81||wd[i+1]==0x82) && wd[i+3]==0x02 && wd[i+4]==0x01 && wd[i+5]==0x01) {
                    if (is_free) { residual_free++; if (key_offsets.size() < 5) key_offsets.push_back(i); }
                    else residual_active++;
                }
                if (i+33 < wd.size() && wd[i]==0x20) {
                    bool nz = false; for (size_t j=i+1;j<i+33;j++) if(wd[j]){nz=true;break;}
                    if (nz && (wd[i+33]==0x02||wd[i+33]==0x03) && is_free) residual_free++;
                }
            }
        }
        bool uses_sqlite = (effective_major(ver) >= 23);
        std::string db = uses_sqlite ? "SQLite" : "BDB";
        trace.finding_id = "KL-KR-BDB-" + ver;
        if (residual_free > 0) {
            std::string offs; for (auto o : key_offsets) { if(!offs.empty()) offs+=","; char h[32]; snprintf(h,sizeof(h),"0x%lx",(unsigned long)o); offs+=h; }
            trace.final_determination = "FOUND: " + std::to_string(residual_free);
            results.push_back(make_finding(ver, "kl_kr", "KL-KR-BDB-SLACK-FOUND",
                "HIGH: " + std::to_string(residual_free) + " residual key patterns in " + db + " free pages",
                "offsets=" + offs + " free=" + std::to_string(free_pages), 8));
        } else {
            trace.final_determination = "CLEAN";
            results.push_back(make_finding(ver, "kl_kr", "KL-KR-BDB-SLACK-CLEAN",
                "PASS: No residual patterns in " + db + " free pages (" + std::to_string(free_pages) + ")", "", 0));
        }
        if (residual_active > 0)
            results.push_back(make_finding(ver, "kl_kr", "KL-KR-BDB-ACTIVE", "INFO: " + std::to_string(residual_active) + " in active pages", "", 1));
        trace.detection_time_ms = std::chrono::duration<double,std::milli>(std::chrono::high_resolution_clock::now()-_t0_64302).count();
        write_discovery_trace(trace, "audit_evidence");
        std::remove(bp.c_str());
        return results;
    }

    // B.2: KL-KR-FILESYSTEM-JOURNAL-RESIDUE
    std::vector<DynamicFinding> engine_kl_kr_fs_journal(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "kl_kr", "KL-KR-FS-SKIP", "SKIP", "", 0)); return results; }
        ScopedProfile _sp("KR_FSJ", "kr_fsj_" + inst.version_string);
        DiscoveryTrace trace; trace.engine = "KL-KR-FS-JOURNAL"; trace.version = ver;
        auto _t0_64361 = std::chrono::high_resolution_clock::now();
        trace.detection_trigger = "Scanning BDB logs and SQLite WAL/SHM for residual keys";
        std::string rd = inst.data_directory + "/regtest";
        std::vector<std::string> journals;
        if (std::filesystem::exists(rd)) {
            try { for (const auto& e : std::filesystem::directory_iterator(rd)) {
                std::string fn = e.path().filename().string();
                if (fn.find("log.") == 0 && fn.size() > 4) journals.push_back(e.path().string());
            }} catch (...) {}
        }
        for (auto& wp : {rd+"/wallets/wallet.dat-wal", rd+"/wallets/wallet.dat-shm", rd+"/wallet.dat-wal", rd+"/wallet.dat-shm"})
            if (std::filesystem::exists(wp)) journals.push_back(wp);
        int with_keys = 0, total_j = (int)journals.size();
        for (const auto& jp : journals) {
            std::ifstream jf(jp, std::ios::binary); if (!jf.is_open()) continue;
            std::vector<uint8_t> jd(2*1024*1024);
            jf.read(reinterpret_cast<char*>(jd.data()), jd.size());
            size_t br = (size_t)jf.gcount(); jd.resize(br); jf.close();
            for (size_t i = 0; i+6 < jd.size(); i++) {
                if (jd[i]==0x30 && (jd[i+1]==0x81||jd[i+1]==0x82) && jd[i+3]==0x02 && jd[i+4]==0x01 && jd[i+5]==0x01)
                    { with_keys++; trace.rpc_transcript.push_back("key_at:" + jp); break; }
            }
        }
        trace.finding_id = "KL-KR-FS-" + ver;
        if (with_keys > 0) {
            trace.final_determination = "FOUND";
            results.push_back(make_finding(ver, "kl_kr", "KL-KR-FS-JOURNAL-FOUND",
                "HIGH: " + std::to_string(with_keys) + "/" + std::to_string(total_j) + " journals have key patterns", "", 7));
        } else if (total_j > 0) {
            trace.final_determination = "CLEAN";
            results.push_back(make_finding(ver, "kl_kr", "KL-KR-FS-JOURNAL-CLEAN",
                "PASS: " + std::to_string(total_j) + " journals clean", "", 0));
        } else {
            trace.final_determination = "NONE";
            results.push_back(make_finding(ver, "kl_kr", "KL-KR-FS-JOURNAL-NONE", "INFO: No journals found", "", 1));
        }
        trace.detection_time_ms = std::chrono::duration<double,std::milli>(std::chrono::high_resolution_clock::now()-_t0_64361).count();
        write_discovery_trace(trace, "audit_evidence");
        return results;
    }

    // B.3: KL-KR-METADATA-TIMELINE-CORRELATION
    std::vector<DynamicFinding> engine_kl_kr_metadata_timeline(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "kl_kr", "KL-KR-META-SKIP", "SKIP", "", 0)); return results; }
        std::string rd = inst.data_directory + "/regtest";
        std::vector<std::string> candidates = {rd+"/wallet.dat", rd+"/wallets/wallet.dat", rd+"/wallets/"+inst.wallet_name+"/wallet.dat"};
        std::string wp; struct stat ws{};
        for (auto& c : candidates) { if (stat(c.c_str(), &ws) == 0) { wp = c; break; } }
        if (wp.empty()) { results.push_back(make_finding(ver, "kl_kr", "KL-KR-META-NOFILE", "SKIP", "", 0)); return results; }
        int64_t gap = ws.st_mtime - ws.st_ctime;
        results.push_back(make_finding(ver, "kl_kr", gap > 300 ? "KL-KR-META-GAP" : "KL-KR-META-OK",
            (gap > 300 ? "MEDIUM: " + std::to_string(gap) + "s creation-modification gap" : "PASS: Gap " + std::to_string(gap) + "s"),
            "size=" + std::to_string(ws.st_size), gap > 300 ? 5 : 0));
        std::ifstream wf2(wp, std::ios::binary);
        if (wf2.is_open()) {
            uint8_t hdr[8]; wf2.read(reinterpret_cast<char*>(hdr), 8); wf2.close();
            uint32_t lsn = (uint32_t(hdr[0])<<24)|(uint32_t(hdr[1])<<16)|(uint32_t(hdr[2])<<8)|uint32_t(hdr[3]);
            if (lsn > 0) results.push_back(make_finding(ver, "kl_kr", "KL-KR-META-LSN", "INFO: BDB LSN present", "", 2));
        }
        return results;
    }

    // B.4: KL-KR-BDB-RECORD-ORDER-INFERENCE
    std::vector<DynamicFinding> engine_kl_kr_record_order(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "kl_kr", "KL-KR-REC-SKIP", "SKIP", "", 0)); return results; }
        std::string bp = "/tmp/audit_rec_" + ver + "_" + std::to_string(inst.rpc_port) + ".dat";
        auto bk = rpc(inst, "backupwallet", "\"" + bp + "\"");
        if (!bk.success || bk.is_error()) { results.push_back(make_finding(ver, "kl_kr", "KL-KR-REC-BKFAIL", "SKIP", "", 0)); return results; }
        std::ifstream wf(bp, std::ios::binary);
        if (!wf.is_open()) { results.push_back(make_finding(ver, "kl_kr", "KL-KR-REC-RDFAIL", "SKIP", "", 0)); return results; }
        std::vector<uint8_t> wd((std::istreambuf_iterator<char>(wf)), std::istreambuf_iterator<char>()); wf.close();
        int ckey_count = 0, key_count = 0;
        std::vector<size_t> ckey_offs, key_offs;
        for (size_t i = 0; i+4 < wd.size(); i++) {
            if (wd[i]=='c' && wd[i+1]=='k' && wd[i+2]=='e' && wd[i+3]=='y') { ckey_count++; if(ckey_offs.size()<10) ckey_offs.push_back(i); }
            if (wd[i]==0x03 && wd[i+1]=='k' && wd[i+2]=='e' && wd[i+3]=='y' && (i==0||wd[i-1]!='c')) { key_count++; if(key_offs.size()<10) key_offs.push_back(i); }
        }
        bool ordering_leak = false;
        if (!ckey_offs.empty() && !key_offs.empty()) { size_t lc = ckey_offs.back(); for (auto ko : key_offs) if (ko > lc) { ordering_leak = true; break; } }
        if (key_count > 0 && p.wallet_encrypted) {
            results.push_back(make_finding(ver, "kl_kr", "KL-KR-REC-PLAINTEXT",
                "MEDIUM: " + std::to_string(key_count) + " plaintext 'key' records in encrypted wallet" +
                (ordering_leak ? " (after ckey — insecure migration)" : ""), "ckeys=" + std::to_string(ckey_count), ordering_leak ? 6 : 4));
        } else {
            results.push_back(make_finding(ver, "kl_kr", "KL-KR-REC-OK",
                "PASS: " + std::to_string(ckey_count) + " ckey, " + std::to_string(key_count) + " key records", "", 0));
        }
        std::remove(bp.c_str());
        return results;
    }

    // B.5: KL-KR-COMPRESSION-ORACLE-KEY-DETECTION
    std::vector<DynamicFinding> engine_kl_kr_compression_oracle(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "kl_kr", "KL-KR-COMP-SKIP", "SKIP", "", 0)); return results; }
        std::string bp = "/tmp/audit_comp_" + ver + "_" + std::to_string(inst.rpc_port) + ".dat";
        auto bk = rpc(inst, "backupwallet", "\"" + bp + "\"");
        if (!bk.success || bk.is_error()) { results.push_back(make_finding(ver, "kl_kr", "KL-KR-COMP-BKFAIL", "SKIP", "", 0)); return results; }
        std::ifstream wf(bp, std::ios::binary);
        if (!wf.is_open()) { results.push_back(make_finding(ver, "kl_kr", "KL-KR-COMP-RDFAIL", "SKIP", "", 0)); return results; }
        std::vector<uint8_t> wd((std::istreambuf_iterator<char>(wf)), std::istreambuf_iterator<char>()); wf.close();
        size_t blk = 256; int low_ent = 0, total_b = 0;
        std::vector<size_t> low_offs;
        for (size_t i = 0; i+blk <= wd.size(); i += blk) {
            total_b++;
            int freq[256] = {};
            for (size_t j = i; j < i+blk; j++) freq[wd[j]]++;
            double ent = 0;
            for (int f : freq) { if (f==0) continue; double pr=(double)f/blk; ent -= pr*std::log2(pr); }
            bool near_ckey = false;
            for (size_t k = (i>20?i-20:0); k < std::min(i+blk+20, wd.size()-4); k++)
                if (wd[k]=='c' && wd[k+1]=='k' && wd[k+2]=='e' && wd[k+3]=='y') { near_ckey = true; break; }
            if (near_ckey && ent < 5.0) { low_ent++; if(low_offs.size()<5) low_offs.push_back(i); }
        }
        if (low_ent > 2) {
            std::string offs; for(auto o:low_offs){if(!offs.empty())offs+=",";char h[32];snprintf(h,sizeof(h),"0x%lx",(unsigned long)o);offs+=h;}
            results.push_back(make_finding(ver, "kl_kr", "KL-KR-COMP-LOW-ENTROPY",
                "MEDIUM: " + std::to_string(low_ent) + " low-entropy blocks near ckey records", "offsets=" + offs, 5));
        } else {
            results.push_back(make_finding(ver, "kl_kr", "KL-KR-COMP-OK", "PASS: Entropy uniform near ckey records", "", 0));
        }
        std::remove(bp.c_str());
        return results;
    }

    // B.6: KL-KR-MEMORY-REMNANT-SCAN
    std::vector<DynamicFinding> engine_kl_kr_memory_remnant(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "kl_kr", "KL-KR-MEM-SKIP", "SKIP", "", 0)); return results; }
        auto mi = rpc(inst, "getmemoryinfo", "\"stats\"");
        if (!mi.success || mi.is_error()) mi = rpc(inst, "getmemoryinfo");
        std::string used = jx(mi.output, "used"), free_m = jx(mi.output, "free"), locked_m = jx(mi.output, "locked");
        int64_t uv = 0, fv = 0, lv = 0;
        try{uv=std::stoll(used);}catch(...){}  try{fv=std::stoll(free_m);}catch(...){}  try{lv=std::stoll(locked_m);}catch(...){}
        if (lv == 0 && p.wallet_encrypted && uv > 0) {
            results.push_back(make_finding(ver, "kl_kr", "KL-KR-MEM-NO-MLOCK",
                "MEDIUM: Wallet encrypted but locked_memory=0 (keys swappable)", "used=" + std::to_string(uv), 5));
        } else if (uv > 0) {
            results.push_back(make_finding(ver, "kl_kr", "KL-KR-MEM-MLOCK-OK",
                "PASS: Locked memory=" + std::to_string(lv) + " bytes", "", 0));
        } else {
            results.push_back(make_finding(ver, "kl_kr", "KL-KR-MEM-UNAVAIL", "INFO: getmemoryinfo unavailable", "", 1));
        }
        auto dbg = rpc(inst, "getmemoryinfo", "\"mallocinfo\"");
        if (dbg.success && !dbg.is_error() && dbg.output.size() > 100)
            results.push_back(make_finding(ver, "kl_kr", "KL-KR-MEM-MALLOC-EXPOSED",
                "INFO: mallocinfo exposes heap internals via RPC", "sz=" + std::to_string(dbg.output.size()), 2));
        return results;
    }

    // B: Combined KL-KR dispatcher
    std::vector<DynamicFinding> engine_kl_kr_family(VersionInstance& inst, const ChainParams& p) {
        ScopedProfile prof("KL-KR", "kl_kr_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto b1=engine_kl_kr_bdb_slack(inst,p);      r.insert(r.end(),b1.begin(),b1.end());
        auto b2=engine_kl_kr_fs_journal(inst,p);      r.insert(r.end(),b2.begin(),b2.end());
        auto b3=engine_kl_kr_metadata_timeline(inst,p);r.insert(r.end(),b3.begin(),b3.end());
        auto b4=engine_kl_kr_record_order(inst,p);    r.insert(r.end(),b4.begin(),b4.end());
        auto b5=engine_kl_kr_compression_oracle(inst,p);r.insert(r.end(),b5.begin(),b5.end());
        auto b6=engine_kl_kr_memory_remnant(inst,p);   r.insert(r.end(),b6.begin(),b6.end());
        return r;
    }


    // ================================================================
    // ENGINE C: NODE-INTERACTIVE KEY-MATERIAL DETECTION (WAL-INTERACT, 10 engines)
    // ================================================================

    // C.1: WAL-HD-PUBLIC-RECONSTRUCTION
    std::vector<DynamicFinding> engine_wal_hd_public_recon(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (!p.wallet_available) { results.push_back(make_finding(ver, "wal_interact", "WAL-HD-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(300));
        int hd_exposed = 0, total_checked = 0; bool has_xpub = false; std::set<std::string> hdpaths;
        ScopedProfile _sp("WAL_HD", "wal_hd_" + inst.version_string);
        DiscoveryTrace trace; trace.engine = "WAL-HD-RECON"; trace.version = ver;
        auto _t0_64541 = std::chrono::high_resolution_clock::now();
        trace.detection_trigger = "Extracting HD paths from getaddressinfo while locked";
        for (const auto& addr : p.test_addresses) {
            auto ai = rpc(inst, "getaddressinfo", "\"" + addr + "\"");
            trace.rpc_transcript.push_back("getaddressinfo -> " + ai.output.substr(0, 80));
            total_checked++;
            std::string path = jx(ai.output, "hdkeypath");
            if (!path.empty()) { hd_exposed++; hdpaths.insert(path); }
            if (ai.has("\"pubkey\"")) has_xpub = true;
        }
        if (em >= 23) {
            auto ld = rpc(inst, "listdescriptors");
            trace.rpc_transcript.push_back("listdescriptors -> " + ld.output.substr(0, 100));
            if (ld.success && !ld.is_error() && ld.output.find("xpub") != std::string::npos) {
                has_xpub = true;
                results.push_back(make_finding(ver, "wal_interact", "WAL-HD-XPUB-LOCKED",
                    "MEDIUM: listdescriptors exposes xpub while locked", "", 5));
            }
        }
        if (hd_exposed > 0) {
            bool has_nh = false;
            for (auto& hp : hdpaths) if (hp.find("'") == std::string::npos && hp.find("h") == std::string::npos && hp.size()>2) has_nh = true;
            std::string ps; int n2=0; for (auto& hp:hdpaths) { if(n2++)ps+=","; ps+=hp; if(n2>=5)break; }
            results.push_back(make_finding(ver, "wal_interact", "WAL-HD-PATHS-EXPOSED",
                (has_nh?"MEDIUM: ":"LOW: ") + std::to_string(hd_exposed) + "/" + std::to_string(total_checked) +
                " addresses expose HD paths" + (has_nh?" (non-hardened)":""), "paths=" + ps, has_nh?6:3));
        } else {
            results.push_back(make_finding(ver, "wal_interact", "WAL-HD-RECON-OK",
                "PASS: No HD path exposure while locked", "", 0));
        }
        trace.finding_id = "WAL-HD-" + ver; trace.final_determination = hd_exposed>0?"EXPOSED":"CLEAN";
        trace.detection_time_ms = std::chrono::duration<double,std::milli>(std::chrono::high_resolution_clock::now()-_t0_64541).count();
        write_discovery_trace(trace, "audit_evidence");
        return results;
    }

    // C.2: WAL-PSBT-ERROR-FINGERPRINT
    std::vector<DynamicFinding> engine_wal_psbt_error(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em < 17 || !p.wallet_available || p.utxos.empty()) {
            results.push_back(make_finding(ver, "wal_interact", "WAL-PSBT-SKIP", "SKIP", "", 0)); return results;
        }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(300));
        auto& best = p.utxos[0]; std::string addr = p.test_addresses.empty() ? "bcrt1qtest" : p.test_addresses[0];
        double amt = (best.amount_sat - 1000) / 1e8;
        if (amt < 0.00001) { results.push_back(make_finding(ver, "wal_interact", "WAL-PSBT-LOWFUNDS", "SKIP", "", 0)); return results; }
        std::string inp = "'[{\"txid\":\"" + best.txid + "\",\"vout\":" + std::to_string(best.vout) + "}]'";
        auto raw = rpc(inst, "createrawtransaction", inp + " '{\"" + addr + "\":" + std::to_string(amt) + "}'");
        if (!raw.success || raw.is_error()) { results.push_back(make_finding(ver, "wal_interact", "WAL-PSBT-CFAIL", "SKIP", "", 0)); return results; }
        auto psbt = rpc(inst, "converttopsbt", raw.result());
        if (!psbt.success || psbt.is_error()) { results.push_back(make_finding(ver, "wal_interact", "WAL-PSBT-CVFAIL", "SKIP", "", 0)); return results; }
        auto tm = timed_rpc(inst, "walletprocesspsbt", "[\"" + psbt.result() + "\"]");
        bool accepted = tm.success && tm.response.find("\"complete\"") != std::string::npos;
        char tb[32]; snprintf(tb, sizeof(tb), "%.2f", tm.elapsed_ms);
        if (accepted) {
            results.push_back(make_finding(ver, "wal_interact", "WAL-PSBT-ACCEPTED-LOCKED",
                "HIGH: walletprocesspsbt succeeded while locked", "t=" + std::string(tb) + "ms", 8));
        } else {
            results.push_back(make_finding(ver, "wal_interact", "WAL-PSBT-REJECTED",
                "PASS: walletprocesspsbt rejected (" + std::string(tb) + "ms)", "", 0));
        }
        return results;
    }

    // C.3: WAL-COIN-SELECTION-LEAK
    std::vector<DynamicFinding> engine_wal_coin_selection(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available || p.utxos.empty()) { results.push_back(make_finding(ver, "wal_interact", "WAL-COINSEL-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(300));
        std::string addr = p.test_addresses.empty() ? "bcrt1qtest" : p.test_addresses[0];
        auto raw = rpc(inst, "createrawtransaction", "'[]' '{\"" + addr + "\":0.001}'");
        if (!raw.success||raw.is_error()) { results.push_back(make_finding(ver, "wal_interact", "WAL-COINSEL-CFAIL", "SKIP", "", 0)); return results; }
        auto fr = rpc(inst, "fundrawtransaction", raw.result());
        bool accepted = fr.success && !fr.is_error() && fr.has("\"hex\"");
        if (accepted)
            results.push_back(make_finding(ver, "wal_interact", "WAL-COINSEL-EXPOSED",
                "MEDIUM: fundrawtransaction reveals coin selection while locked", "", 5));
        else
            results.push_back(make_finding(ver, "wal_interact", "WAL-COINSEL-BLOCKED",
                "PASS: fundrawtransaction rejected while locked", "", 0));
        return results;
    }

    // C.4: WAL-KEYPOOL-EXPANSION-ORACLE
    std::vector<DynamicFinding> engine_wal_keypool_oracle(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "wal_interact", "WAL-KP-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(300));
        auto wb = rpc(inst, "getwalletinfo"); std::string kpb = jx(wb.output, "keypoolsize");
        int kb = 0; try{kb=std::stoi(kpb);}catch(...){}
        auto kp = rpc(inst, "keypoolrefill", "10");
        bool accepted = kp.success && !kp.is_error();
        auto wa = rpc(inst, "getwalletinfo"); std::string kpa = jx(wa.output, "keypoolsize");
        int ka = 0; try{ka=std::stoi(kpa);}catch(...){}
        if (accepted && ka > kb)
            results.push_back(make_finding(ver, "wal_interact", "WAL-KP-EXPAND-LOCKED",
                "MEDIUM: keypoolrefill expanded " + std::to_string(kb) + " -> " + std::to_string(ka) + " while locked", "", 5));
        else
            results.push_back(make_finding(ver, "wal_interact", "WAL-KP-BLOCKED",
                "PASS: keypoolrefill rejected or no change", "", 0));
        return results;
    }

    // C.5: WAL-DESCRIPTOR-XPUB-EXTRACTION
    std::vector<DynamicFinding> engine_wal_desc_xpub(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em < 21 || !p.wallet_available) { results.push_back(make_finding(ver, "wal_interact", "WAL-DXPUB-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(300));
        auto ld = rpc(inst, "listdescriptors");
        if (!ld.success||ld.is_error()) { results.push_back(make_finding(ver, "wal_interact", "WAL-DXPUB-UNAVAIL", "PASS: listdescriptors unavailable", "", 0)); return results; }
        int xc = 0; size_t pos = 0;
        while ((pos = ld.output.find("xpub", pos)) != std::string::npos) { xc++; pos += 4; }
        if (xc > 0)
            results.push_back(make_finding(ver, "wal_interact", "WAL-DXPUB-EXPOSED",
                "MEDIUM: " + std::to_string(xc) + " xpub keys exposed while locked", "", 5));
        else
            results.push_back(make_finding(ver, "wal_interact", "WAL-DXPUB-HIDDEN", "PASS: No xpub exposure", "", 0));
        return results;
    }

    // C.6: WAL-SIGNRAW-TIMING-DIFFERENTIAL
    std::vector<DynamicFinding> engine_wal_signraw_timing(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available || p.utxos.size() < 2) { results.push_back(make_finding(ver, "wal_interact", "WAL-SRT-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(300));
        std::string addr = p.test_addresses.empty() ? "bcrt1qtest" : p.test_addresses[0];
        std::vector<double> timings;
        for (size_t ui = 0; ui < std::min(p.utxos.size(), (size_t)5); ui++) {
            auto& u = p.utxos[ui]; double amt = (u.amount_sat - 500) / 1e8;
            if (amt < 0.00001) continue;
            auto raw = rpc(inst, "createrawtransaction", "'[{\"txid\":\"" + u.txid + "\",\"vout\":" + std::to_string(u.vout) + "}]' '{\"" + addr + "\":" + std::to_string(amt) + "}'");
            if (!raw.success||raw.is_error()) continue;
            auto tm = timed_rpc(inst, sign_rpc(ver), "[\"" + raw.result() + "\"]");
            timings.push_back(tm.elapsed_ms);
        }
        if (timings.size() >= 2) {
            double mn=*std::min_element(timings.begin(),timings.end()), mx=*std::max_element(timings.begin(),timings.end());
            double range = mx-mn; char rb[32]; snprintf(rb,sizeof(rb),"%.2f",range);
            results.push_back(make_finding(ver, "wal_interact", range>50?"WAL-SRT-VAR":"WAL-SRT-OK",
                (range>50?"LOW: ":"PASS: ") + std::string(rb) + "ms timing range across UTXOs", "", range>50?3:0));
        } else {
            results.push_back(make_finding(ver, "wal_interact", "WAL-SRT-INSUF", "SKIP: <2 UTXOs", "", 0));
        }
        return results;
    }

    // C.7: WAL-BATCH-STATE-MACHINE
    std::vector<DynamicFinding> engine_wal_batch_state(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available || !p.wallet_encrypted) { results.push_back(make_finding(ver, "wal_interact", "WAL-BSM-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(300));
        auto pre = rpc(inst, "getwalletinfo"); std::string pl = jx(pre.output, "unlocked_until");
        rpc(inst, "walletpassphrase", "\"definitely_wrong_12345\" 1");
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        auto post = rpc(inst, "getwalletinfo"); std::string ptl = jx(post.output, "unlocked_until");
        bool state_leaked = (pl != ptl);
        std::string addr = p.test_addresses.empty() ? "bcrt1qtest" : p.test_addresses[0];
        auto dpk = rpc(inst, "dumpprivkey", "\"" + addr + "\"");
        bool key_leaked = dpk.success && !dpk.is_error() && dpk.output.size() > 20 && dpk.output.find("error") == std::string::npos;
        if (key_leaked)
            results.push_back(make_finding(ver, "wal_interact", "WAL-BSM-KEY-LEAKED",
                "CRITICAL: dumpprivkey succeeded after failed walletpassphrase", "", 10));
        else if (state_leaked)
            results.push_back(make_finding(ver, "wal_interact", "WAL-BSM-STATE-CHANGE",
                "LOW: Wallet state changed after failed attempt", "pre=" + pl + " post=" + ptl, 3));
        else
            results.push_back(make_finding(ver, "wal_interact", "WAL-BSM-OK", "PASS: No state leakage", "", 0));
        return results;
    }

    // C.8: WAL-LABEL-ADDRESS-MAPPING
    std::vector<DynamicFinding> engine_wal_label_mapping(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "wal_interact", "WAL-LAB-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(300));
        auto labels = rpc(inst, "listlabels");
        int lc = 0; if (labels.success) { size_t p2=0; while((p2=labels.output.find('"',p2))!=std::string::npos){lc++;p2++;} lc/=2; }
        int addrs = 0;
        if (lc > 0) { auto abl = rpc(inst, "getaddressesbylabel", "\"\""); if(abl.success&&!abl.is_error()){size_t p3=0;while((p3=abl.output.find("\"bcrt1",p3))!=std::string::npos){addrs++;p3+=5;}} }
        if (addrs > 0 || lc > 3)
            results.push_back(make_finding(ver, "wal_interact", "WAL-LAB-EXPOSED",
                "LOW: " + std::to_string(lc) + " labels, " + std::to_string(addrs) + " addresses while locked", "", 2));
        else
            results.push_back(make_finding(ver, "wal_interact", "WAL-LAB-OK", "PASS: Limited label exposure", "", 0));
        return results;
    }

    // C.9: WAL-LISTSINCEBLOCK-GRAPH-LEAK
    std::vector<DynamicFinding> engine_wal_lsb_leak(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "wal_interact", "WAL-LSB-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(300));
        auto lsb = rpc(inst, "listsinceblock");
        if (!lsb.success||lsb.is_error()) { results.push_back(make_finding(ver, "wal_interact", "WAL-LSB-BLOCKED", "PASS: blocked", "", 0)); return results; }
        int txc = 0; size_t p2=0; while((p2=lsb.output.find("\"txid\"",p2))!=std::string::npos){txc++;p2+=6;}
        bool ha = lsb.has("\"address\""), hm = lsb.has("\"amount\"");
        if (txc > 0 && (ha || hm))
            results.push_back(make_finding(ver, "wal_interact", "WAL-LSB-TXGRAPH",
                "MEDIUM: " + std::to_string(txc) + " txs exposed while locked (addr=" + std::string(ha?"Y":"N") + " amt=" + std::string(hm?"Y":"N") + ")", "", 4));
        else
            results.push_back(make_finding(ver, "wal_interact", "WAL-LSB-OK", "PASS: Minimal data while locked", "", 0));
        return results;
    }

    // C.10: WAL-BACKUP-SNAPSHOT-DIFF
    std::vector<DynamicFinding> engine_wal_backup_diff(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "wal_interact", "WAL-BKDIFF-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(300));
        std::string bp1="/tmp/d1_"+ver+"_"+std::to_string(inst.rpc_port)+".dat", bp2="/tmp/d2_"+ver+"_"+std::to_string(inst.rpc_port)+".dat";
        auto bk1 = rpc(inst, "backupwallet", "\"" + bp1 + "\"");
        if (!bk1.success||bk1.is_error()) { results.push_back(make_finding(ver, "wal_interact", "WAL-BKDIFF-BLOCKED", "PASS: blocked", "", 0)); return results; }
        rpc(inst, "getnewaddress"); std::this_thread::sleep_for(std::chrono::milliseconds(500));
        auto bk2 = rpc(inst, "backupwallet", "\"" + bp2 + "\"");
        struct stat s1{}, s2{}; stat(bp1.c_str(), &s1); stat(bp2.c_str(), &s2);
        int64_t delta = s2.st_size - s1.st_size;
        if (delta > 0)
            results.push_back(make_finding(ver, "wal_interact", "WAL-BKDIFF-GROWTH",
                "INFO: Wallet grew " + std::to_string(delta) + " bytes between locked backups", "", 2));
        else
            results.push_back(make_finding(ver, "wal_interact", "WAL-BKDIFF-STABLE", "PASS: Stable", "", 0));
        std::remove(bp1.c_str()); std::remove(bp2.c_str());
        return results;
    }

    // C: Combined WAL-INTERACT dispatcher
    std::vector<DynamicFinding> engine_wal_interact_family(VersionInstance& inst, const ChainParams& p) {
        ScopedProfile prof("WAL-INT", "wal_interact_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto c1=engine_wal_hd_public_recon(inst,p); r.insert(r.end(),c1.begin(),c1.end());
        auto c2=engine_wal_psbt_error(inst,p);       r.insert(r.end(),c2.begin(),c2.end());
        auto c3=engine_wal_coin_selection(inst,p);   r.insert(r.end(),c3.begin(),c3.end());
        auto c4=engine_wal_keypool_oracle(inst,p);   r.insert(r.end(),c4.begin(),c4.end());
        auto c5=engine_wal_desc_xpub(inst,p);        r.insert(r.end(),c5.begin(),c5.end());
        auto c6=engine_wal_signraw_timing(inst,p);   r.insert(r.end(),c6.begin(),c6.end());
        auto c7=engine_wal_batch_state(inst,p);      r.insert(r.end(),c7.begin(),c7.end());
        auto c8=engine_wal_label_mapping(inst,p);    r.insert(r.end(),c8.begin(),c8.end());
        auto c9=engine_wal_lsb_leak(inst,p);         r.insert(r.end(),c9.begin(),c9.end());
        auto c10=engine_wal_backup_diff(inst,p);     r.insert(r.end(),c10.begin(),c10.end());
        return r;
    }


    // ================================================================
    // ENGINE D: BITFLIP-BASED KEY LEAKAGE (4 engines)
    // ================================================================

    // D.1: BF-CHAINING-DIFFERENTIAL-ANALYZER
    std::vector<DynamicFinding> engine_bf_chaining(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_encrypted) { results.push_back(make_finding(ver, "bf_leak", "BF-CHAIN-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        std::vector<std::string> passes = {"wrong1","wrong2_longer","x",std::string(64,'A'),std::string(256,'B'),"!@#$","",std::string(1,'Z'),std::string(128,'Q')};
        std::set<std::string> msgs; std::set<int> codes; std::vector<double> timings;
        ScopedProfile _sp("BF_CHAIN", "bf_chain_" + inst.version_string);
        DiscoveryTrace trace; trace.engine="BF-CHAIN"; trace.version=ver;
        auto _t0_64804 = std::chrono::high_resolution_clock::now();
        trace.detection_trigger="Error uniformity across " + std::to_string(passes.size()) + " wrong passwords";
        for (const auto& pass : passes) {
            std::string ep; for (char c:pass){if(c=='"')ep+="\\\"";else if(c=='\\')ep+="\\\\";else if(c<0x20){char b[8];snprintf(b,sizeof(b),"\\u%04x",(unsigned char)c);ep+=b;}else ep+=c;}
            auto tm = timed_rpc(inst, "walletpassphrase", "[\"" + ep + "\",1]");
            timings.push_back(tm.elapsed_ms);
            msgs.insert(jx(tm.response, "message")); codes.insert(tm.error_code);
            trace.rpc_transcript.push_back("wp('" + pass.substr(0,10) + "') -> c=" + std::to_string(tm.error_code) + " t=" + std::to_string((int)tm.elapsed_ms) + "ms");
        }
        trace.finding_id="BF-CHAIN-"+ver;
        if (msgs.size() > 1) {
            std::string ml; int n=0; for(auto& m:msgs){if(n++)ml+=" | ";ml+=m.substr(0,50);}
            trace.final_determination="DIVERGE:" + std::to_string(msgs.size());
            results.push_back(make_finding(ver, "bf_leak", "BF-CHAIN-MSG-DIVERGE",
                "MEDIUM: " + std::to_string(msgs.size()) + " distinct error messages", "msgs=" + ml, 5));
        } else { trace.final_determination="UNIFORM";
            results.push_back(make_finding(ver, "bf_leak", "BF-CHAIN-MSG-UNIFORM", "PASS: Uniform errors", "", 0));
        }
        codes.erase(0);
        if (codes.size() > 1)
            results.push_back(make_finding(ver, "bf_leak", "BF-CHAIN-CODE-DIVERGE",
                "MEDIUM: " + std::to_string(codes.size()) + " distinct codes", "", 4));
        trace.detection_time_ms = std::chrono::duration<double,std::milli>(std::chrono::high_resolution_clock::now()-_t0_64804).count();
        write_discovery_trace(trace, "audit_evidence");
        return results;
    }

    // D.2: BF-LENGTH-EXTENSION-OBSERVER
    std::vector<DynamicFinding> engine_bf_length_ext(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_encrypted) { results.push_back(make_finding(ver, "bf_leak", "BF-LENEXT-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        std::vector<int> lens={1,2,4,8,15,16,17,31,32,33,48,64,128,255};
        std::vector<double> timings; std::set<std::string> errs;
        for (int len : lens) {
            auto tm = timed_rpc(inst, "walletpassphrase", "[\"" + std::string(len,'A') + "\",1]");
            timings.push_back(tm.elapsed_ms); errs.insert(jx(tm.response, "message"));
        }
        int n=(int)lens.size(); double sx=0,sy=0,sxy=0,sx2=0,sy2=0;
        for(int i=0;i<n;i++){double x=lens[i],y=timings[i];sx+=x;sy+=y;sxy+=x*y;sx2+=x*x;sy2+=y*y;}
        double denom=std::sqrt((n*sx2-sx*sx)*(n*sy2-sy*sy));
        double corr=(denom>1e-10)?(n*sxy-sx*sy)/denom:0.0;
        double mn=*std::min_element(timings.begin(),timings.end()),mx=*std::max_element(timings.begin(),timings.end());
        double range=mx-mn; char cb[32]; snprintf(cb,sizeof(cb),"%.4f",corr);
        if (std::abs(corr)>0.7 && range>10.0)
            results.push_back(make_finding(ver, "bf_leak", "BF-LENEXT-TIMING-CORR",
                "HIGH: r=" + std::string(cb) + " range=" + std::to_string((int)range) + "ms", "", 7));
        else
            results.push_back(make_finding(ver, "bf_leak", "BF-LENEXT-TIMING-OK",
                "PASS: r=" + std::string(cb) + " range=" + std::to_string((int)range) + "ms", "", 0));
        if (errs.size()>1)
            results.push_back(make_finding(ver, "bf_leak", "BF-LENEXT-MSG-VARY",
                "MEDIUM: " + std::to_string(errs.size()) + " msgs across lengths", "", 4));
        return results;
    }

    // D.3: BF-STRUCTURED-MUTATION-TIMING-ANALYZER
    std::vector<DynamicFinding> engine_bf_structured_mut(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_encrypted) { results.push_back(make_finding(ver, "bf_leak", "BF-STRMUT-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        std::string base = "test_passphrase_base";
        std::vector<std::string> muts;
        for (int b=0;b<8;b++){std::string m=base;m[0]^=(1<<b);muts.push_back(m);}
        for (size_t p2=0;p2<base.size()&&p2<10;p2++){std::string m=base;m[p2]=(m[p2]=='z'?'a':'z');muts.push_back(m);}
        for (int l:{1,5,10,15,19}) muts.push_back(base.substr(0,l));
        muts.push_back(base+base); muts.push_back(base.substr(0,5)+base.substr(0,5));
        std::vector<double> timings;
        for (const auto& m : muts) { auto tm = timed_rpc(inst, "walletpassphrase", "[\"" + m + "\",1]"); timings.push_back(tm.elapsed_ms); }
        double sum=0; for(auto t:timings) sum+=t; double mean=sum/timings.size();
        double var=0; for(auto t:timings){double d=t-mean;var+=d*d;} var/=timings.size(); double sd=std::sqrt(var);
        int outliers=0; for(auto t:timings) if(sd>0.1&&std::abs(t-mean)>3*sd) outliers++;
        char mb[32],sb[32]; snprintf(mb,sizeof(mb),"%.2f",mean); snprintf(sb,sizeof(sb),"%.2f",sd);
        if (outliers>0&&sd>5.0)
            results.push_back(make_finding(ver, "bf_leak", "BF-STRMUT-OUTLIER",
                "MEDIUM: " + std::to_string(outliers) + " outliers (sd=" + std::string(sb) + "ms)", "", 5));
        else
            results.push_back(make_finding(ver, "bf_leak", "BF-STRMUT-UNIFORM",
                "PASS: Uniform (" + std::to_string(muts.size()) + " mutations, sd=" + std::string(sb) + "ms)", "", 0));
        return results;
    }

    // D.4: BF-CROSS-VERSION-ERROR-MAP-COMPARATOR
    std::vector<DynamicFinding> engine_bf_cross_version(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_encrypted) { results.push_back(make_finding(ver, "bf_leak", "BF-XVER-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        std::vector<std::string> probes={"x",std::string(32,'A'),std::string(64,'B'),"probe123"};
        std::set<int> pcodes; std::set<std::string> pmsgs;
        for (auto& pr : probes) {
            auto tm = timed_rpc(inst, "walletpassphrase", "[\"" + pr + "\",1]");
            pcodes.insert(tm.error_code); pmsgs.insert(jx(tm.response, "message"));
        }
        int em = effective_major(ver);
        results.push_back(make_finding(ver, "bf_leak", "BF-XVER-PROFILE",
            "INFO: v" + ver + " profile: codes=" + std::to_string(pcodes.size()) + " msgs=" + std::to_string(pmsgs.size()),
            "", pmsgs.size()>1?3:1));
        if (em<18) {
            auto fm = *pmsgs.begin();
            if (fm.find("passphrase")==std::string::npos && fm.find("password")==std::string::npos)
                results.push_back(make_finding(ver, "bf_leak", "BF-XVER-OLDMSG", "LOW: Non-standard error msg", "", 3));
        }
        return results;
    }

    // D: Combined BITFLIP dispatcher
    std::vector<DynamicFinding> engine_bf_family(VersionInstance& inst, const ChainParams& p) {
        ScopedProfile prof("BF-FAM", "bf_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto d1=engine_bf_chaining(inst,p);      r.insert(r.end(),d1.begin(),d1.end());
        auto d2=engine_bf_length_ext(inst,p);    r.insert(r.end(),d2.begin(),d2.end());
        auto d3=engine_bf_structured_mut(inst,p);r.insert(r.end(),d3.begin(),d3.end());
        auto d4=engine_bf_cross_version(inst,p); r.insert(r.end(),d4.begin(),d4.end());
        return r;
    }

    // ================================================================
    // ENGINE E: PADDING ORACLE & SIDE-CHANNEL (KL-PAD, 5 engines)
    // ================================================================

    // E.1: KL-PAD-CIPHERTEXT-SELF-INTERFERENCE
    std::vector<DynamicFinding> engine_kl_pad_selfint(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_encrypted) { results.push_back(make_finding(ver, "kl_pad", "KL-PAD-SELFINT-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        auto baseline = timed_rpc(inst, "walletpassphrase", "[\"selfint_test\",1]");
        std::string base_msg = jx(baseline.response, "message");
        std::vector<std::future<TimingMeasurement>> futs;
        for (int i=0;i<4;i++) futs.push_back(std::async(std::launch::async,[&,i](){return timed_rpc(inst,"walletpassphrase","[\"si_"+std::to_string(i)+"\",1]");}));
        std::vector<TimingMeasurement> conc;
        for (auto& f:futs) if(f.wait_for(std::chrono::seconds(10))==std::future_status::ready) conc.push_back(f.get());
        bool diverge = false;
        for (auto& c:conc) { std::string m=jx(c.response,"message"); if(m!=base_msg&&!m.empty()&&!base_msg.empty()) diverge=true; }
        double cmean=0; for(auto& c:conc) cmean+=c.elapsed_ms; if(!conc.empty()) cmean/=conc.size();
        double ratio=(baseline.elapsed_ms>0.1)?cmean/baseline.elapsed_ms:1.0;
        char rb[32]; snprintf(rb,sizeof(rb),"%.2f",ratio);
        if (diverge)
            results.push_back(make_finding(ver, "kl_pad", "KL-PAD-SELFINT-DIVERGE", "MEDIUM: Concurrent errors diverge", "", 5));
        else
            results.push_back(make_finding(ver, "kl_pad", "KL-PAD-SELFINT-UNIFORM", "PASS: Uniform (ratio=" + std::string(rb) + "x)", "", 0));
        if (ratio>10.0&&cmean>50.0)
            results.push_back(make_finding(ver, "kl_pad", "KL-PAD-SELFINT-AMP",
                "MEDIUM: " + std::string(rb) + "x amp", "base=" + std::to_string((int)baseline.elapsed_ms) + "ms", 5));
        return results;
    }

    // E.2: KL-PAD-NULL-PADDING-INJECTION
    std::vector<DynamicFinding> engine_kl_pad_null(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_encrypted) { results.push_back(make_finding(ver, "kl_pad", "KL-PAD-NULL-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        std::vector<std::pair<std::string,std::string>> tests={{"normal","no_null"},{"n\\u0000e","mid"},{"\\u0000l","start"},{"t\\u0000","end"},{"\\u0000\\u0000\\u0000","all"}};
        std::vector<double> ts; std::set<std::string> msgs;
        for (auto& [pass,lbl]:tests) { auto tm=timed_rpc(inst,"walletpassphrase","[\""+pass+"\",1]"); ts.push_back(tm.elapsed_ms); msgs.insert(jx(tm.response,"message")); }
        double range=*std::max_element(ts.begin(),ts.end())-*std::min_element(ts.begin(),ts.end());
        if (msgs.size()>1||range>50.0)
            results.push_back(make_finding(ver, "kl_pad", "KL-PAD-NULL-DIVERGE",
                "LOW: " + std::to_string(msgs.size()) + " responses, range=" + std::to_string((int)range) + "ms", "", 3));
        else
            results.push_back(make_finding(ver, "kl_pad", "KL-PAD-NULL-UNIFORM", "PASS: Uniform", "", 0));
        return results;
    }

    // E.3: KL-PAD-KEY-SCHEDULE-CORRELATION
    std::vector<DynamicFinding> engine_kl_pad_keysched(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_encrypted) { results.push_back(make_finding(ver, "kl_pad", "KL-PAD-KS-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        std::vector<double> base_t;
        for (int i=0;i<5;i++) { auto tm=timed_rpc(inst,"walletpassphrase","[\"ks_probe\",1]"); base_t.push_back(tm.elapsed_ms); }
        std::atomic<bool> stop{false};
        std::vector<std::thread> lth;
        for (int i=0;i<4;i++) lth.emplace_back([&stop](){volatile double x=1.0;while(!stop.load(std::memory_order_relaxed)){for(int j=0;j<1000;j++)x=std::sin(x)*std::cos(x)+1.0;}});
        std::vector<double> load_t;
        for (int i=0;i<5;i++) { auto tm=timed_rpc(inst,"walletpassphrase","[\"ks_probe\",1]"); load_t.push_back(tm.elapsed_ms); }
        stop.store(true); for(auto& t:lth) t.join();
        double bm=0,lm=0; for(auto t:base_t)bm+=t; bm/=base_t.size(); for(auto t:load_t)lm+=t; lm/=load_t.size();
        double amp=(bm>0.1)?lm/bm:1.0; char ab[32]; snprintf(ab,sizeof(ab),"%.1f",amp);
        if (amp>5.0)
            results.push_back(make_finding(ver, "kl_pad", "KL-PAD-KS-AMP",
                "MEDIUM: " + std::string(ab) + "x under load", "base=" + std::to_string((int)bm) + "ms", 5));
        else
            results.push_back(make_finding(ver, "kl_pad", "KL-PAD-KS-STABLE", "PASS: " + std::string(ab) + "x", "", 0));
        return results;
    }

    // E.4: KL-PAD-MEMORY-ALLOCATION-PATTERN
    std::vector<DynamicFinding> engine_kl_pad_memalloc(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_encrypted) { results.push_back(make_finding(ver, "kl_pad", "KL-PAD-MEM-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        auto mb=rpc(inst,"getmemoryinfo"); std::string ub=jx(mb.output,"used");
        for (int i=0;i<10;i++) rpc_fast(inst,"walletpassphrase","[\"memtest_"+std::to_string(i)+"\",1]");
        auto ma=rpc(inst,"getmemoryinfo"); std::string ua=jx(ma.output,"used");
        int64_t before=0,after=0; try{before=std::stoll(ub);}catch(...){} try{after=std::stoll(ua);}catch(...){}
        int64_t delta=after-before;
        if (delta>1024*1024)
            results.push_back(make_finding(ver, "kl_pad", "KL-PAD-MEM-GROWTH",
                "LOW: " + std::to_string(delta/1024) + "KB growth", "", 3));
        else if (before>0)
            results.push_back(make_finding(ver, "kl_pad", "KL-PAD-MEM-STABLE", "PASS: delta=" + std::to_string(delta) + "B", "", 0));
        else
            results.push_back(make_finding(ver, "kl_pad", "KL-PAD-MEM-UNAVAIL", "INFO: unavailable", "", 1));
        return results;
    }

    // E.5: KL-PAD-BRANCH-PREDICTION-CONTENTION
    std::vector<DynamicFinding> engine_kl_pad_branch(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_encrypted) { results.push_back(make_finding(ver, "kl_pad", "KL-PAD-BR-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        std::vector<double> st,lt;
        for (int r2=0;r2<10;r2++) {
            st.push_back(timed_rpc(inst,"walletpassphrase","[\"a\",1]").elapsed_ms);
            lt.push_back(timed_rpc(inst,"walletpassphrase","[\""+std::string(64,'B')+"\",1]").elapsed_ms);
        }
        auto cv=[](const std::vector<double>&v)->double{if(v.empty())return 0;double s=0;for(auto x:v)s+=x;double m=s/v.size();if(m<0.1)return 0;double vr=0;for(auto x:v){double d=x-m;vr+=d*d;}return std::sqrt(vr/v.size())/m;};
        double cvs=cv(st),cvl=cv(lt),ms=0,ml=0;
        for(auto t:st)ms+=t; ms/=st.size(); for(auto t:lt)ml+=t; ml/=lt.size();
        double diff=std::abs(ml-ms); char cs2[32],cl2[32],db[32];
        snprintf(cs2,sizeof(cs2),"%.3f",cvs);snprintf(cl2,sizeof(cl2),"%.3f",cvl);snprintf(db,sizeof(db),"%.2f",diff);
        if (std::abs(cvs-cvl)>0.3&&diff>10.0)
            results.push_back(make_finding(ver, "kl_pad", "KL-PAD-BR-DIVERGE",
                "LOW: CVs=" + std::string(cs2) + " CVl=" + std::string(cl2), "", 3));
        else
            results.push_back(make_finding(ver, "kl_pad", "KL-PAD-BR-UNIFORM", "PASS: CV comparable", "", 0));
        return results;
    }

    // E: Combined KL-PAD dispatcher
    std::vector<DynamicFinding> engine_kl_pad_family(VersionInstance& inst, const ChainParams& p) {
        ScopedProfile prof("KL-PAD", "kl_pad_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto e1=engine_kl_pad_selfint(inst,p);  r.insert(r.end(),e1.begin(),e1.end());
        auto e2=engine_kl_pad_null(inst,p);     r.insert(r.end(),e2.begin(),e2.end());
        auto e3=engine_kl_pad_keysched(inst,p); r.insert(r.end(),e3.begin(),e3.end());
        auto e4=engine_kl_pad_memalloc(inst,p); r.insert(r.end(),e4.begin(),e4.end());
        auto e5=engine_kl_pad_branch(inst,p);   r.insert(r.end(),e5.begin(),e5.end());
        return r;
    }


    // ================================================================
    // ENGINE F: ADDITIONAL NOVEL ENGINES (10 engines)
