    // SECTION 83: MAINNET-CAPABLE NOVEL KEY-LEAKAGE, ENCRYPTION
    // BYPASS, AND CONSENSUS VERIFICATION ENGINES v1.0
    // 3000+ lines of novel detection logic
    // ================================================================

    // ----------------------------------------------------------------
    // 83.0: Mainnet configuration helper
    // ----------------------------------------------------------------
    struct MainnetConfig {
        bool mainnet_mode = false;
        bool isolated = true;  // connect=0, listen=0
        std::string wallet_path;
    };

    MainnetConfig mainnet_cfg_;

    void write_mainnet_conf(const std::string& datadir) {
        std::string conf = datadir + "/bitcoin.conf";
        std::ofstream ofs(conf);
        if (!ofs.is_open()) return;
        if (mainnet_cfg_.mainnet_mode) {
            ofs << "# Mainnet isolated mode\n"
                << "connect=0\nlisten=0\ndnsseed=0\n"
                << "fixedseeds=0\n"
                << "server=1\ndaemon=1\n"
                << "rpcthreads=4\nrpcworkqueue=32\n";
        }
        ofs.close();
    }

    // ----------------------------------------------------------------
    // 83.1: KL-KR-NOVEL — Offline Key-Material Detection (9 engines)
    // ----------------------------------------------------------------

    // Helper: scan binary data for DER EC private key patterns
    struct KeyScanResult {
        int der_keys = 0;
        int raw_scalars = 0;
        int wif_candidates = 0;
        int xprv_strings = 0;
        std::vector<size_t> offsets;
    };

    KeyScanResult scan_for_key_material(const std::vector<uint8_t>& data, size_t max_offsets = 10) {
        KeyScanResult ks;
        for (size_t i = 0; i + 6 < data.size(); i++) {
            // DER EC private key: 0x30 <len> ... 0x02 0x01 0x01
            if (data[i]==0x30 && (data[i+1]==0x81||data[i+1]==0x82) &&
                data[i+3]==0x02 && data[i+4]==0x01 && data[i+5]==0x01) {
                ks.der_keys++;
                if (ks.offsets.size() < max_offsets) ks.offsets.push_back(i);
            }
            // Raw 32-byte scalar (high entropy, non-zero)
            if (i + 33 < data.size() && data[i]==0x20) {
                bool nz = false, hi_ent = true;
                int zeros = 0;
                for (size_t j = i+1; j < i+33; j++) {
                    if (data[j]) nz = true;
                    if (data[j] == 0) zeros++;
                }
                if (nz && zeros < 8) ks.raw_scalars++;
            }
            // WIF format (starts with 5, K, L, or c for testnet/regtest)
            if ((data[i]=='5'||data[i]=='K'||data[i]=='L'||data[i]=='c') &&
                i + 52 <= data.size()) {
                bool all_b58 = true;
                for (size_t j = i; j < i+52; j++) {
                    char c = data[j];
                    if (!((c>='1'&&c<='9')||(c>='A'&&c<='H')||(c>='J'&&c<='N')||
                          (c>='P'&&c<='Z')||(c>='a'&&c<='k')||(c>='m'&&c<='z')))
                        { all_b58 = false; break; }
                }
                if (all_b58) ks.wif_candidates++;
            }
            // xprv string
            if (i + 4 < data.size() && data[i]=='x' && data[i+1]=='p' &&
                data[i+2]=='r' && data[i+3]=='v') {
                ks.xprv_strings++;
                if (ks.offsets.size() < max_offsets) ks.offsets.push_back(i);
            }
        }
        return ks;
    }

    // Helper: read wallet backup into memory
    std::vector<uint8_t> read_wallet_backup(VersionInstance& inst, const std::string& suffix = "") {
        // Method 1: backupwallet RPC (preferred — consistent snapshot)
        std::string bp = "/tmp/audit_s88_" + inst.version_string + "_" +
            std::to_string(inst.rpc_port) + suffix + ".dat";
        auto bk = rpc(inst, "backupwallet", "\"" + bp + "\"");
        if (bk.success && !bk.is_error()) {
            std::ifstream wf(bp, std::ios::binary);
            if (wf.is_open()) {
                std::vector<uint8_t> wd((std::istreambuf_iterator<char>(wf)),
                    std::istreambuf_iterator<char>()); wf.close();
                std::remove(bp.c_str());
                if (!wd.empty()) return wd;
            }
            std::remove(bp.c_str());
        }
        // Method 2: Direct read from data directory (fallback when RPC fails)
        // Try standard wallet locations in order of likelihood
        std::vector<std::string> wallet_paths;
        std::string dd = inst.data_directory;
        std::string rd = dd + (inst.is_regtest ? "/regtest" : "");
        // For 0.17+ with named wallets
        if (!inst.wallet_name.empty()) {
            wallet_paths.push_back(rd + "/wallets/" + inst.wallet_name + "/wallet.dat");
            wallet_paths.push_back(rd + "/" + inst.wallet_name + "/wallet.dat");
        }
        wallet_paths.push_back(rd + "/wallets/wallet.dat");
        wallet_paths.push_back(rd + "/wallet.dat");
        wallet_paths.push_back(dd + "/wallet.dat");
        // Also try the audit-named wallet
        wallet_paths.push_back(rd + "/wallets/audit_" + inst.version_string + "/wallet.dat");
        for (const auto& wp : wallet_paths) {
            std::ifstream wf(wp, std::ios::binary);
            if (!wf.is_open()) continue;
            std::vector<uint8_t> wd((std::istreambuf_iterator<char>(wf)),
                std::istreambuf_iterator<char>()); wf.close();
            if (wd.size() >= 512) return wd;
        }
        return {};
    }

    // KL-KR-NOVEL-1: BDB Slack Plaintext Deep Scanner
    std::vector<DynamicFinding> engine_klkr_novel_bdb_slack(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-BDB-SKIP", "SKIP", "", 0)); return results; }
        ScopedProfile _sp("KR_NOVEL", "kr_novel_" + inst.version_string);
        DiscoveryTrace trace; trace.engine = "KL-KR-NOVEL-BDB-SLACK"; trace.version = ver;
        auto _t0_66827 = std::chrono::high_resolution_clock::now();
        trace.detection_trigger = "Deep BDB free-page scan for DER keys, raw scalars, WIF, and xprv";
        auto wd = read_wallet_backup(inst, "_bdb");
        if (wd.empty()) { results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-BDB-NOBK", "SKIP: backup failed", "", 0)); return results; }
        // Determine BDB page size from header
        size_t page_size = 4096;
        if (wd.size() >= 24) {
            uint32_t ps = (uint32_t(wd[20])<<24)|(uint32_t(wd[21])<<16)|(uint32_t(wd[22])<<8)|uint32_t(wd[23]);
            if (ps >= 512 && ps <= 65536 && (ps & (ps-1)) == 0) page_size = ps;
        }
        size_t num_pages = wd.size() / page_size;
        KeyScanResult total_free, total_active;
        for (size_t pg = 0; pg < num_pages; pg++) {
            size_t base = pg * page_size;
            uint8_t ptype = (base + 25 < wd.size()) ? wd[base + 25] : 0;
            bool is_free = (ptype == 0x00); // BDB: type 0 = free page, type 5 = btree leaf (active)
            // Scan page content (skip BDB header area)
            std::vector<uint8_t> page_data(wd.begin() + base + 26,
                wd.begin() + std::min(base + page_size, wd.size()));
            auto ks = scan_for_key_material(page_data);
            if (is_free) {
                total_free.der_keys += ks.der_keys;
                total_free.raw_scalars += ks.raw_scalars;
                total_free.wif_candidates += ks.wif_candidates;
                total_free.xprv_strings += ks.xprv_strings;
                for (auto o : ks.offsets) if (total_free.offsets.size() < 10) total_free.offsets.push_back(base + 26 + o);
            } else {
                total_active.der_keys += ks.der_keys;
                total_active.raw_scalars += ks.raw_scalars;
            }
        }
        trace.finding_id = "KLKR-N-BDB-" + ver;
        int total_residual = total_free.der_keys + total_free.wif_candidates + total_free.xprv_strings;
        if (total_residual > 0) {
            std::string offs; for (auto o : total_free.offsets) { if(!offs.empty()) offs+=","; char h[32]; snprintf(h,sizeof(h),"0x%lx",(unsigned long)o); offs+=h; }
            trace.final_determination = "FOUND: " + std::to_string(total_residual) + " key patterns";
            results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-BDB-SLACK-FOUND",
                "HIGH: " + std::to_string(total_residual) + " residual key patterns in free pages (DER=" +
                std::to_string(total_free.der_keys) + " WIF=" + std::to_string(total_free.wif_candidates) +
                " xprv=" + std::to_string(total_free.xprv_strings) + ")",
                "offsets=" + offs + " pages=" + std::to_string(num_pages), total_residual > 5 ? 8 : 7));
        } else {
            trace.final_determination = "CLEAN";
            results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-BDB-SLACK-CLEAN",
                "PASS: No residual key patterns in " + std::to_string(num_pages) + " free pages", "", 0));
        }
        if (total_free.raw_scalars > 5)
            results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-BDB-RAW-SCALARS",
                "MEDIUM: " + std::to_string(total_free.raw_scalars) + " potential raw scalars in free pages", "", 5));
        trace.detection_time_ms = std::chrono::duration<double,std::milli>(std::chrono::high_resolution_clock::now()-_t0_66827).count();
        write_discovery_trace_s83(trace, "audit_evidence");
        return results;
    }

    // KL-KR-NOVEL-2: Filesystem Journal Residue
    std::vector<DynamicFinding> engine_klkr_novel_fs_journal(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-FSJ-SKIP", "SKIP", "", 0)); return results; }
        std::string rd = inst.data_directory + "/regtest";
        std::vector<std::string> journal_files;
        try {
            for (const auto& wp : {rd, rd+"/wallets", rd+"/wallets/"+inst.wallet_name}) {
                if (!std::filesystem::exists(wp)) continue;
                for (const auto& e : std::filesystem::directory_iterator(wp)) {
                    std::string fn = e.path().filename().string();
                    if (fn.find("log.") == 0 || fn.find("-wal") != std::string::npos ||
                        fn.find("-shm") != std::string::npos || fn.find("-journal") != std::string::npos)
                        journal_files.push_back(e.path().string());
                }
            }
        } catch (...) {}
        int files_with_keys = 0;
        for (const auto& jp : journal_files) {
            std::ifstream jf(jp, std::ios::binary); if (!jf.is_open()) continue;
            std::vector<uint8_t> jd(4*1024*1024);
            jf.read(reinterpret_cast<char*>(jd.data()), jd.size());
            jd.resize((size_t)jf.gcount()); jf.close();
            auto ks = scan_for_key_material(jd);
            if (ks.der_keys > 0 || ks.xprv_strings > 0 || ks.wif_candidates > 0) files_with_keys++;
        }
        if (files_with_keys > 0) {
            results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-FSJ-FOUND",
                "HIGH: " + std::to_string(files_with_keys) + "/" + std::to_string(journal_files.size()) +
                " journal files contain key material residue",
                "total_journals=" + std::to_string(journal_files.size()), 7));
        } else {
            results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-FSJ-CLEAN",
                "PASS: " + std::to_string(journal_files.size()) + " journal files clean", "", 0));
        }
        return results;
    }

    // KL-KR-NOVEL-3: Metadata Timeline Correlation
    std::vector<DynamicFinding> engine_klkr_novel_metadata_timeline(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-META-SKIP", "SKIP", "", 0)); return results; }
        std::string rd = inst.data_directory + "/regtest";
        std::vector<std::string> candidates = {rd+"/wallet.dat", rd+"/wallets/wallet.dat",
            rd+"/wallets/"+inst.wallet_name+"/wallet.dat",
            rd+"/wallets/"+inst.wallet_name+"/wallet.sqlite"};
        for (auto& c : candidates) {
            struct stat ws{};
            if (stat(c.c_str(), &ws) != 0) continue;
            int64_t gap = ws.st_mtime - ws.st_ctime;
            int64_t size = ws.st_size;
            // Large gap + large file = pre-encryption plaintext window
            if (gap > 300 && size > 100000) {
                results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-META-WINDOW",
                    "MEDIUM: " + std::to_string(gap) + "s creation-modification gap on " + std::to_string(size/1024) + "KB wallet",
                    "path=" + c, 5));
            } else {
                results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-META-OK",
                    "PASS: Gap=" + std::to_string(gap) + "s size=" + std::to_string(size), "", 0));
            }
            break;
        }
        return results;
    }

    // KL-KR-NOVEL-4: BDB Record Order Inference
    std::vector<DynamicFinding> engine_klkr_novel_record_order(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-REC-SKIP", "SKIP", "", 0)); return results; }
        auto wd = read_wallet_backup(inst, "_rec");
        if (wd.empty()) { results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-REC-NOBK", "SKIP", "", 0)); return results; }
        // Count ckey vs key records and check ordering
        int ckey_count = 0, key_count = 0, mkey_count = 0;
        std::vector<size_t> ckey_offs, key_offs;
        for (size_t i = 0; i+5 < wd.size(); i++) {
            if (wd[i]=='c'&&wd[i+1]=='k'&&wd[i+2]=='e'&&wd[i+3]=='y') { ckey_count++; if(ckey_offs.size()<20) ckey_offs.push_back(i); }
            if (wd[i]==0x03&&wd[i+1]=='k'&&wd[i+2]=='e'&&wd[i+3]=='y'&&(i==0||wd[i-1]!='c')) { key_count++; if(key_offs.size()<20) key_offs.push_back(i); }
            if (wd[i]=='m'&&wd[i+1]=='k'&&wd[i+2]=='e'&&wd[i+3]=='y') mkey_count++;
        }
        // Detect post-encryption plaintext keys (key records after ckey records)
        bool ordering_leak = false;
        if (!ckey_offs.empty() && !key_offs.empty()) {
            size_t last_ckey = ckey_offs.back();
            for (auto ko : key_offs) if (ko > last_ckey) { ordering_leak = true; break; }
        }
        if (key_count > 0 && p.wallet_encrypted && ordering_leak) {
            results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-REC-ORDER-LEAK",
                "MEDIUM: " + std::to_string(key_count) + " plaintext key records after ckey records (insecure migration)",
                "ckeys=" + std::to_string(ckey_count) + " mkeys=" + std::to_string(mkey_count), 6));
        } else {
            results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-REC-ORDER-OK",
                "PASS: " + std::to_string(ckey_count) + " ckey, " + std::to_string(key_count) + " key, " +
                std::to_string(mkey_count) + " mkey records", "", 0));
        }
        return results;
    }

    // KL-KR-NOVEL-5: Compression Oracle Detection
    std::vector<DynamicFinding> engine_klkr_novel_compression_oracle(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-COMP-SKIP", "SKIP", "", 0)); return results; }
        auto wd = read_wallet_backup(inst, "_comp");
        if (wd.empty()) { results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-COMP-NOBK", "SKIP", "", 0)); return results; }
        // Measure entropy near ckey records
        int low_entropy_blocks = 0;
        size_t blk = 256;
        for (size_t i = 0; i + blk <= wd.size(); i += blk) {
            bool near_ckey = false;
            for (size_t k = (i>32?i-32:0); k < std::min(i+blk+32, wd.size()-4); k++)
                if (wd[k]=='c'&&wd[k+1]=='k'&&wd[k+2]=='e'&&wd[k+3]=='y') { near_ckey = true; break; }
            if (!near_ckey) continue;
            int freq[256] = {};
            for (size_t j = i; j < i+blk; j++) freq[wd[j]]++;
            double ent = 0;
            for (int f : freq) { if (f==0) continue; double pr=(double)f/blk; ent -= pr*std::log2(pr); }
            if (ent < 4.5) low_entropy_blocks++;
        }
        if (low_entropy_blocks > 3) {
            results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-COMP-LOW-ENT",
                "MEDIUM: " + std::to_string(low_entropy_blocks) + " low-entropy blocks near ckey records",
                "threshold=4.5bits", 5));
        } else {
            results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-COMP-OK",
                "PASS: Entropy uniform near ckey records", "", 0));
        }
        return results;
    }

    // KL-KR-NOVEL-6: Memory Remnant Scan
    std::vector<DynamicFinding> engine_klkr_novel_memory_remnant(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-MEM-SKIP", "SKIP", "", 0)); return results; }
        auto mi = rpc(inst, "getmemoryinfo", "\"stats\"");
        if (!mi.success || mi.is_error()) mi = rpc(inst, "getmemoryinfo");
        std::string locked = jx(mi.output, "locked");
        std::string used = jx(mi.output, "used");
        int64_t lv = 0, uv = 0;
        try { lv = std::stoll(locked); } catch (...) {}
        try { uv = std::stoll(used); } catch (...) {}
        if (lv == 0 && p.wallet_encrypted && uv > 0) {
            results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-MEM-NO-MLOCK",
                "MEDIUM: Encrypted wallet but locked_memory=0 — keys swappable to disk",
                "used=" + std::to_string(uv), 5));
        } else if (lv > 0) {
            results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-MEM-MLOCK-OK",
                "PASS: Locked memory=" + std::to_string(lv) + " bytes", "", 0));
        } else {
            results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-MEM-UNAVAIL",
                "INFO: getmemoryinfo unavailable", "", 1));
        }
        // Check mallocinfo exposure
        auto dbg = rpc(inst, "getmemoryinfo", "\"mallocinfo\"");
        if (dbg.success && !dbg.is_error() && dbg.output.size() > 200) {
            results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-MEM-MALLOC-EXPOSED",
                "LOW: mallocinfo exposes " + std::to_string(dbg.output.size()) + " bytes of heap metadata via RPC", "", 3));
        }
        return results;
    }

    // KL-KR-NOVEL-7: Crash Log Plaintext Leak Scanner
    std::vector<DynamicFinding> engine_klkr_novel_crashlog(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        // Scan macOS crash logs for this bitcoind's PID
        std::string cmd = "find ~/Library/Logs/DiagnosticReports /Library/Logs/DiagnosticReports "
            "-name '*.crash' -newer /tmp -maxdepth 2 2>/dev/null | head -5";
        auto cr = popen_with_timeout(cmd, 1);
        if (cr.timed_out || cr.output.empty()) {
            results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-CRASH-NONE",
                "PASS: No recent crash logs found", "", 0));
            return results;
        }
        // Check if any crash log contains hex key patterns
        int logs_with_keys = 0;
        std::istringstream iss(cr.output);
        std::string line;
        while (std::getline(iss, line)) {
            if (line.empty()) continue;
            std::ifstream cf(line); if (!cf.is_open()) continue;
            std::string content((std::istreambuf_iterator<char>(cf)), std::istreambuf_iterator<char>());
            cf.close();
            // Look for hex-encoded private key patterns (64 hex chars = 32 bytes)
            for (size_t i = 0; i + 64 <= content.size(); i++) {
                bool all_hex = true;
                for (size_t j = i; j < i+64; j++) {
                    char c = content[j];
                    if (!((c>='0'&&c<='9')||(c>='a'&&c<='f')||(c>='A'&&c<='F'))) { all_hex = false; break; }
                }
                if (all_hex) { logs_with_keys++; break; }
            }
        }
        if (logs_with_keys > 0) {
            results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-CRASH-HEXDUMP",
                "MEDIUM: " + std::to_string(logs_with_keys) + " crash logs contain 32-byte hex patterns",
                "Note: Manual review needed to confirm key material", 5));
        } else {
            results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-CRASH-CLEAN",
                "PASS: Crash logs do not contain obvious key patterns", "", 0));
        }
        return results;
    }

    // KL-KR-NOVEL-8: Swap File Key Extraction
    std::vector<DynamicFinding> engine_klkr_novel_swap_scan(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        // Check if swap is enabled and if mlock is insufficient
        auto mi = rpc(inst, "getmemoryinfo", "\"stats\"");
        std::string locked = jx(mi.output, "locked");
        int64_t lv = 0; try { lv = std::stoll(locked); } catch (...) {}
        // On macOS, check swap usage via sysctl
        auto sw = popen_with_timeout("sysctl -n vm.swapusage 2>/dev/null | awk '{print $6}' | tr -d 'M'", 1);
        std::string swap_used = sw.output;
        while (!swap_used.empty() && swap_used.back() == '\n') swap_used.pop_back();
        double swap_mb = 0; try { swap_mb = std::stod(swap_used); } catch (...) {}
        if (swap_mb > 100 && lv == 0) {
            results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-SWAP-RISK",
                "LOW: " + std::to_string((int)swap_mb) + "MB swap in use + no mlock — keys may be in swap",
                "locked=" + std::to_string(lv), 3));
        } else {
            results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-SWAP-OK",
                "PASS: Swap risk low (swap=" + std::to_string((int)swap_mb) + "MB mlock=" + std::to_string(lv) + ")",
                "", 0));
        }
        return results;
    }

    // KL-KR-NOVEL-9: BDB Page Mapping Attack
    std::vector<DynamicFinding> engine_klkr_novel_page_mapping(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        int em = effective_major(ver);
        if (em >= 23) {
            results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-PGMAP-NA",
                "INFO: SQLite wallet — BDB page mapping not applicable", "", 0));
            return results;
        }
        auto wd = read_wallet_backup(inst, "_pgmap");
        if (wd.empty()) { results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-PGMAP-NOBK", "SKIP", "", 0)); return results; }
        // Analyze page allocation patterns
        size_t page_size = 4096;
        if (wd.size() >= 24) {
            uint32_t ps = (uint32_t(wd[20])<<24)|(uint32_t(wd[21])<<16)|(uint32_t(wd[22])<<8)|uint32_t(wd[23]);
            if (ps >= 512 && ps <= 65536 && (ps & (ps-1)) == 0) page_size = ps;
        }
        size_t num_pages = wd.size() / page_size;
        int data_pages = 0, free_pages = 0, overflow_pages = 0;
        for (size_t pg = 0; pg < num_pages; pg++) {
            uint8_t ptype = (pg * page_size + 25 < wd.size()) ? wd[pg * page_size + 25] : 0;
            if (ptype == 0x00) free_pages++; // BDB: type 0 = free page only
            else if (ptype == 0x07) overflow_pages++;
            else data_pages++;
        }
        double free_ratio = num_pages > 0 ? (double)free_pages / num_pages : 0;
        if (free_ratio > 0.3 && p.wallet_encrypted) {
            results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-PGMAP-HIGH-FREE",
                "LOW: " + std::to_string((int)(free_ratio*100)) + "% free pages in encrypted wallet — " +
                "pre-encryption data may persist in " + std::to_string(free_pages) + " free pages",
                "data=" + std::to_string(data_pages) + " overflow=" + std::to_string(overflow_pages), 3));
        } else {
            results.push_back(make_finding(ver, "kl_kr_novel", "KLKR-N-PGMAP-OK",
                "PASS: " + std::to_string(data_pages) + " data, " + std::to_string(free_pages) +
                " free, " + std::to_string(overflow_pages) + " overflow pages", "", 0));
        }
        return results;
    }

    // KL-KR-NOVEL dispatcher
    std::vector<DynamicFinding> engine_klkr_novel_family(VersionInstance& inst, const ChainParams& p) {
        ScopedProfile prof("KLKR-N", "klkr_novel_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto a1=engine_klkr_novel_bdb_slack(inst,p);        r.insert(r.end(),a1.begin(),a1.end());
        auto a2=engine_klkr_novel_fs_journal(inst,p);        r.insert(r.end(),a2.begin(),a2.end());
        auto a3=engine_klkr_novel_metadata_timeline(inst,p); r.insert(r.end(),a3.begin(),a3.end());
        auto a4=engine_klkr_novel_record_order(inst,p);      r.insert(r.end(),a4.begin(),a4.end());
        auto a5=engine_klkr_novel_compression_oracle(inst,p);r.insert(r.end(),a5.begin(),a5.end());
        auto a6=engine_klkr_novel_memory_remnant(inst,p);    r.insert(r.end(),a6.begin(),a6.end());
        auto a7=engine_klkr_novel_crashlog(inst,p);          r.insert(r.end(),a7.begin(),a7.end());
        auto a8=engine_klkr_novel_swap_scan(inst,p);         r.insert(r.end(),a8.begin(),a8.end());
        auto a9=engine_klkr_novel_page_mapping(inst,p);      r.insert(r.end(),a9.begin(),a9.end());
        return r;
    }

    // ----------------------------------------------------------------
    // 83.2: WAL-INTERACT-NOVEL — Node-Interactive Key-Leakage (10 engines)
    // ----------------------------------------------------------------

    // WAL-INTERACT-NOVEL-1: HD Public Reconstruction via locked getaddressinfo
    std::vector<DynamicFinding> engine_wal_novel_hd_recon(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (!p.wallet_available) { results.push_back(make_finding(ver, "wal_interact_novel", "WIN-HD-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(300));
        int paths_exposed = 0, non_hardened = 0, pubkeys_exposed = 0;
        std::set<std::string> unique_paths;
        for (const auto& addr : p.test_addresses) {
            auto ai = rpc(inst, "getaddressinfo", "\"" + addr + "\"");
            std::string path = jx(ai.output, "hdkeypath");
            if (!path.empty()) { paths_exposed++; unique_paths.insert(path);
                if (path.find("'") == std::string::npos && path.find("h") == std::string::npos) non_hardened++;
            }
            if (ai.has("\"pubkey\"")) pubkeys_exposed++;
        }
        // Check listdescriptors for xpub exposure
        int xpub_count = 0;
        if (em >= 21) {
            auto ld = rpc(inst, "listdescriptors");
            if (ld.success && !ld.is_error()) {
                size_t pos = 0;
                while ((pos = ld.output.find("xpub", pos)) != std::string::npos) { xpub_count++; pos += 4; }
            }
        }
        int total_leak = paths_exposed + pubkeys_exposed + xpub_count;
        if (total_leak > 0) {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-HD-RECON",
                "MEDIUM: While locked: " + std::to_string(paths_exposed) + " HD paths (" +
                std::to_string(non_hardened) + " non-hardened), " + std::to_string(pubkeys_exposed) +
                " pubkeys, " + std::to_string(xpub_count) + " xpubs exposed",
                "unique_paths=" + std::to_string(unique_paths.size()), non_hardened > 0 ? 6 : 4));
        } else {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-HD-CLEAN", "PASS: No exposure while locked", "", 0));
        }
        return results;
    }

    // WAL-INTERACT-NOVEL-2: PSBT Error Fingerprinting
    std::vector<DynamicFinding> engine_wal_novel_psbt_fingerprint(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em < 17 || !p.wallet_available || p.utxos.empty()) {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-PSBT-SKIP", "SKIP", "", 0)); return results;
        }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(300));
        // Test multiple UTXOs for PSBT error differentiation
        std::set<std::string> error_classes;
        for (size_t ui = 0; ui < std::min(p.utxos.size(), (size_t)5); ui++) {
            auto& u = p.utxos[ui];
            std::string addr = p.test_addresses.empty() ? "bcrt1qtest" : p.test_addresses[0];
            double amt = std::max(0.00001, (u.amount_sat - 1000) / 1e8);
            auto raw = rpc(inst, "createrawtransaction",
                "'[{\"txid\":\"" + u.txid + "\",\"vout\":" + std::to_string(u.vout) + "}]' " +
                "'{\"" + addr + "\":" + std::to_string(amt) + "}'");
            if (!raw.success || raw.is_error()) continue;
            auto psbt = rpc(inst, "converttopsbt", raw.result());
            if (!psbt.success || psbt.is_error()) continue;
            auto wp = rpc(inst, "walletprocesspsbt", "[\"" + psbt.result() + "\"]");
            std::string err_msg = jx(wp.output, "message");
            std::string err_code = jx(wp.output, "code");
            error_classes.insert(err_code + ":" + err_msg.substr(0, 40));
        }
        if (error_classes.size() > 1) {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-PSBT-DIVERGE",
                "MEDIUM: " + std::to_string(error_classes.size()) + " distinct PSBT error classes while locked " +
                "— may fingerprint which ckey records exist", "", 5));
        } else {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-PSBT-UNIFORM",
                "PASS: Uniform PSBT errors while locked", "", 0));
        }
        return results;
    }

    // WAL-INTERACT-NOVEL-3: Coin Selection Leak via fundrawtransaction
    std::vector<DynamicFinding> engine_wal_novel_coinsel_leak(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "wal_interact_novel", "WIN-CSEL-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(300));
        std::string addr = p.test_addresses.empty() ? "bcrt1qtest" : p.test_addresses[0];
        auto raw = rpc(inst, "createrawtransaction", "'[]' '{\"" + addr + "\":0.001}'");
        if (!raw.success||raw.is_error()) { results.push_back(make_finding(ver, "wal_interact_novel", "WIN-CSEL-CFAIL", "SKIP", "", 0)); return results; }
        auto fr = rpc(inst, "fundrawtransaction", raw.result());
        bool exposed = fr.success && !fr.is_error() && fr.has("\"hex\"");
        if (exposed) {
            std::string fee = jx(fr.output, "fee");
            std::string changepos = jx(fr.output, "changepos");
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-CSEL-EXPOSED",
                "MEDIUM: fundrawtransaction reveals UTXO selection while locked (fee=" + fee + " changepos=" + changepos + ")", "", 5));
        } else {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-CSEL-BLOCKED", "PASS: Blocked while locked", "", 0));
        }
        return results;
    }

    // WAL-INTERACT-NOVEL-4: Keypool Expansion Oracle
    std::vector<DynamicFinding> engine_wal_novel_keypool_oracle(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "wal_interact_novel", "WIN-KP-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(300));
        auto wb = rpc(inst, "getwalletinfo");
        int kb = 0; try { kb = std::stoi(jx(wb.output, "keypoolsize")); } catch (...) {}
        auto kp = rpc(inst, "keypoolrefill", "10");
        bool accepted = kp.success && !kp.is_error();
        auto wa = rpc(inst, "getwalletinfo");
        int ka = 0; try { ka = std::stoi(jx(wa.output, "keypoolsize")); } catch (...) {}
        if (accepted && ka > kb) {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-KP-EXPANDED",
                "MEDIUM: keypoolrefill accepted while locked (" + std::to_string(kb) + " -> " + std::to_string(ka) + ")", "", 5));
        } else {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-KP-BLOCKED", "PASS: Blocked while locked", "", 0));
        }
        return results;
    }

    // WAL-INTERACT-NOVEL-5: Signraw Timing Differential
    std::vector<DynamicFinding> engine_wal_novel_signraw_timing(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available || p.utxos.size() < 2) {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-SRT-SKIP", "SKIP", "", 0)); return results;
        }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(300));
        std::string addr = p.test_addresses.empty() ? "bcrt1qtest" : p.test_addresses[0];
        std::vector<double> timings;
        for (size_t ui = 0; ui < std::min(p.utxos.size(), (size_t)5); ui++) {
            auto& u = p.utxos[ui];
            double amt = std::max(0.00001, (u.amount_sat - 500) / 1e8);
            auto raw = rpc(inst, "createrawtransaction",
                "'[{\"txid\":\"" + u.txid + "\",\"vout\":" + std::to_string(u.vout) + "}]' " +
                "'{\"" + addr + "\":" + std::to_string(amt) + "}'");
            if (!raw.success||raw.is_error()) continue;
            auto tm = timed_rpc(inst, sign_rpc(ver), "[\"" + raw.result() + "\"]");
            timings.push_back(tm.elapsed_ms);
        }
        if (timings.size() >= 2) {
            double mn = *std::min_element(timings.begin(),timings.end());
            double mx = *std::max_element(timings.begin(),timings.end());
            double range = mx - mn;
            char rb[32]; snprintf(rb,sizeof(rb),"%.2f",range);
            if (range > 50.0) {
                results.push_back(make_finding(ver, "wal_interact_novel", "WIN-SRT-TIMING-LEAK",
                    "LOW: " + std::string(rb) + "ms timing range across UTXOs — derivation depth may leak", "", 3));
            } else {
                results.push_back(make_finding(ver, "wal_interact_novel", "WIN-SRT-OK",
                    "PASS: Timing range " + std::string(rb) + "ms", "", 0));
            }
        }
        return results;
    }

    // WAL-INTERACT-NOVEL-6: Batch State Machine (wrong pass + dumpprivkey)
    std::vector<DynamicFinding> engine_wal_novel_batch_state(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available || !p.wallet_encrypted) {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-BSM-SKIP", "SKIP", "", 0)); return results;
        }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(300));
        // Send wrong password then immediately try dumpprivkey
        rpc(inst, "walletpassphrase", "\"definitely_wrong_pass_12345\" 1");
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
        std::string addr = p.test_addresses.empty() ? "bcrt1qtest" : p.test_addresses[0];
        auto dpk = rpc(inst, "dumpprivkey", "\"" + addr + "\"");
        bool key_leaked = dpk.success && !dpk.is_error() && dpk.output.size() > 20 &&
            dpk.output.find("error") == std::string::npos;
        if (key_leaked) {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-BSM-KEY-LEAKED",
                "CRITICAL: dumpprivkey succeeded after failed walletpassphrase (master key in memory)", "", 10));
        } else {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-BSM-OK", "PASS: No state leakage", "", 0));
        }
        return results;
    }

    // WAL-INTERACT-NOVEL-7: Label-Address Mapping Reconstruction
    std::vector<DynamicFinding> engine_wal_novel_label_map(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "wal_interact_novel", "WIN-LAB-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(300));
        auto labels = rpc(inst, "listlabels");
        int lc = 0; if (labels.success) { size_t ps = 0; while ((ps = labels.output.find('"', ps)) != std::string::npos) { lc++; ps++; } lc /= 2; }
        int addrs = 0;
        if (lc > 0) {
            auto abl = rpc(inst, "getaddressesbylabel", "\"\"");
            if (abl.success && !abl.is_error()) { size_t ps = 0; while ((ps = abl.output.find("\"bcrt1", ps)) != std::string::npos) { addrs++; ps += 5; } }
        }
        if (addrs > 3 || lc > 5) {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-LAB-EXPOSED",
                "LOW: " + std::to_string(lc) + " labels, " + std::to_string(addrs) + " addresses visible while locked", "", 2));
        } else {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-LAB-OK", "PASS: Minimal exposure", "", 0));
        }
        return results;
    }

    // WAL-INTERACT-NOVEL-8: Transaction Graph via listsinceblock
    std::vector<DynamicFinding> engine_wal_novel_txgraph(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "wal_interact_novel", "WIN-TXG-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(300));
        auto lsb = rpc(inst, "listsinceblock");
        if (!lsb.success || lsb.is_error()) {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-TXG-BLOCKED", "PASS: Blocked while locked", "", 0));
            return results;
        }
        int txc = 0; size_t ps = 0;
        while ((ps = lsb.output.find("\"txid\"", ps)) != std::string::npos) { txc++; ps += 6; }
        bool has_addr = lsb.has("\"address\""), has_amt = lsb.has("\"amount\"");
        if (txc > 0 && (has_addr || has_amt)) {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-TXG-EXPOSED",
                "MEDIUM: " + std::to_string(txc) + " txs exposed while locked (addr=" +
                std::string(has_addr?"Y":"N") + " amt=" + std::string(has_amt?"Y":"N") + ")", "", 4));
        } else {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-TXG-OK", "PASS: Minimal data", "", 0));
        }
        return results;
    }

    // WAL-INTERACT-NOVEL-9: Backup Snapshot Differential
    std::vector<DynamicFinding> engine_wal_novel_backup_diff(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "wal_interact_novel", "WIN-BKDIFF-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(300));
        auto wd1 = read_wallet_backup(inst, "_d1");
        rpc(inst, "getnewaddress"); std::this_thread::sleep_for(std::chrono::milliseconds(500));
        auto wd2 = read_wallet_backup(inst, "_d2");
        if (wd1.empty() || wd2.empty()) {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-BKDIFF-FAIL", "SKIP", "", 0));
            return results;
        }
        int64_t delta = (int64_t)wd2.size() - (int64_t)wd1.size();
        // Count differing bytes in overlapping region
        size_t min_sz = std::min(wd1.size(), wd2.size());
        int diff_bytes = 0;
        for (size_t i = 0; i < min_sz; i++) if (wd1[i] != wd2[i]) diff_bytes++;
        if (delta > 0 || diff_bytes > 100) {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-BKDIFF-CHANGED",
                "INFO: Wallet changed between locked backups: delta=" + std::to_string(delta) +
                "B diff_bytes=" + std::to_string(diff_bytes),
                "sz1=" + std::to_string(wd1.size()) + " sz2=" + std::to_string(wd2.size()), 2));
        } else {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-BKDIFF-STABLE", "PASS: Stable", "", 0));
        }
        return results;
    }

    // WAL-INTERACT-NOVEL-10: Descriptor xpub Extraction While Locked
    std::vector<DynamicFinding> engine_wal_novel_desc_xpub(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em < 21 || !p.wallet_available) {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-DXPUB-SKIP", "SKIP", "", 0)); return results;
        }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(300));
        auto ld = rpc(inst, "listdescriptors");
        if (!ld.success || ld.is_error()) {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-DXPUB-BLOCKED", "PASS: listdescriptors blocked while locked", "", 0));
            return results;
        }
        int xpub = 0, xprv = 0;
        size_t pos = 0; while ((pos = ld.output.find("xpub", pos)) != std::string::npos) { xpub++; pos += 4; }
        pos = 0; while ((pos = ld.output.find("xprv", pos)) != std::string::npos) { xprv++; pos += 4; }
        if (xprv > 0) {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-DXPUB-XPRV-EXPOSED",
                "CRITICAL: " + std::to_string(xprv) + " xprv keys exposed while locked!", "", 10));
        } else if (xpub > 0) {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-DXPUB-XPUB-EXPOSED",
                "MEDIUM: " + std::to_string(xpub) + " xpub keys exposed while locked — enables balance tracking", "", 5));
        } else {
            results.push_back(make_finding(ver, "wal_interact_novel", "WIN-DXPUB-CLEAN", "PASS: No key material in listdescriptors", "", 0));
        }
        return results;
    }

