        ScopedProfile prof("WIN", "wal_interact_novel_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto w1=engine_wal_novel_hd_recon(inst,p);        r.insert(r.end(),w1.begin(),w1.end());
