    // ----------------------------------------------------------------
    // 83.3: WAL-BYPASS-NOVEL — Encryption Bypass Detection (4 engines)
    // ----------------------------------------------------------------

    // WAL-BYPASS-1: Six-RPC Lock Gate (mainnet-ready)
    std::vector<DynamicFinding> engine_wal_bypass_six_rpc(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (!p.wallet_available) { results.push_back(make_finding(ver, "wal_bypass", "WB-6RPC-SKIP", "SKIP", "", 0)); return results; }
        if (!p.wallet_encrypted) {
            auto enc = rpc(inst, "encryptwallet", "\"" + wallet_encryption_passphrase_ + "\"");
            if (!enc.success || enc.is_error()) {
                results.push_back(make_finding(ver, "wal_bypass", "WB-6RPC-NOENC", "SKIP: Cannot encrypt", "", 0));
                return results;
            }
            std::this_thread::sleep_for(std::chrono::seconds(3));
            for (int r2 = 0; r2 < 10; r2++) { auto bc = rpc_fast(inst, "getblockcount"); if (bc.success && !bc.is_error()) break; std::this_thread::sleep_for(std::chrono::seconds(1)); }
        }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(500));
        std::string addr = p.test_addresses.empty() ? "bcrt1qtest" : p.test_addresses[0];
        struct RpcTest { std::string method; std::string params; std::string tag; };
        std::vector<RpcTest> tests = {
            {"sendtoaddress", "\"" + addr + "\" 0.001", "SEND"},
            {"signmessage", "\"" + addr + "\" \"test\"", "SIGN"},
            {"keypoolrefill", "10", "KEYPOOL"}
        };
        if (em < 23) {
            tests.push_back({"dumpprivkey", "\"" + addr + "\"", "DUMP"});
            tests.push_back({"importprivkey", "\"cVpF924EFkHEqR3JDiXTqGXudiVzGeLqfFj6SPZqMRdwaukEsekj\"", "IMPORT"});
            if (em >= 17) tests.push_back({"sethdseed", "true", "HDSEED"});
        }
        int bypasses = 0; std::vector<std::string> bypassed;
        for (auto& t : tests) {
            auto r2 = rpc(inst, t.method, t.params);
            bool rejected = !r2.success || r2.is_error() || r2.output.find("locked") != std::string::npos ||
                r2.output.find("passphrase") != std::string::npos || r2.output.find("encrypted") != std::string::npos;
            if (!rejected) { bypasses++; bypassed.push_back(t.method); }
        }
        if (bypasses > 0) {
            std::string bl; for (auto& b : bypassed) { if (!bl.empty()) bl += ","; bl += b; }
            results.push_back(make_finding(ver, "wal_bypass", "WB-6RPC-BYPASS",
                "CRITICAL: " + std::to_string(bypasses) + "/" + std::to_string(tests.size()) +
                " RPCs accepted while locked: " + bl, "", bypasses == (int)tests.size() ? 10 : 9));
        } else {
            results.push_back(make_finding(ver, "wal_bypass", "WB-6RPC-PASS",
                "PASS: All " + std::to_string(tests.size()) + " RPCs rejected while locked", "", 0));
        }
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        return results;
    }

    // WAL-BYPASS-2: PSBT Accepted While Locked
    std::vector<DynamicFinding> engine_wal_bypass_psbt(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em < 17 || !p.wallet_available || p.utxos.empty()) {
            results.push_back(make_finding(ver, "wal_bypass", "WB-PSBT-SKIP", "SKIP", "", 0)); return results;
        }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(300));
        auto& u = p.utxos[0]; std::string addr = p.test_addresses.empty() ? "bcrt1qtest" : p.test_addresses[0];
        double amt = std::max(0.00001, (u.amount_sat - 1000) / 1e8);
        auto raw = rpc(inst, "createrawtransaction",
            "'[{\"txid\":\"" + u.txid + "\",\"vout\":" + std::to_string(u.vout) + "}]' " +
            "'{\"" + addr + "\":" + std::to_string(amt) + "}'");
        if (!raw.success || raw.is_error()) { results.push_back(make_finding(ver, "wal_bypass", "WB-PSBT-CFAIL", "SKIP", "", 0)); return results; }
        auto psbt = rpc(inst, "converttopsbt", raw.result());
        if (!psbt.success || psbt.is_error()) { results.push_back(make_finding(ver, "wal_bypass", "WB-PSBT-CVFAIL", "SKIP", "", 0)); return results; }
        auto wp = rpc(inst, "walletprocesspsbt", "[\"" + psbt.result() + "\"]");
        bool signed_ok = wp.success && !wp.is_error() && wp.has("\"complete\": true");
        if (signed_ok) {
            results.push_back(make_finding(ver, "wal_bypass", "WB-PSBT-SIGNED-LOCKED",
                "CRITICAL: walletprocesspsbt signed transaction while locked", "", 9));
        } else {
            results.push_back(make_finding(ver, "wal_bypass", "WB-PSBT-REJECTED", "PASS: Rejected while locked", "", 0));
        }
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        return results;
    }

