    // ----------------------------------------------------------------
    // 84.9: KL-ENTROPY-ANALYSIS — Entropy-based leak detection (4 engines)
    // ----------------------------------------------------------------

    // 84.9.1: Wallet File Entropy Map
    std::vector<DynamicFinding> engine_entropy_wallet_map(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (!p.wallet_encrypted) { results.push_back(make_finding(ver, "entropy", "ENT-MAP-SKIP", "SKIP", "", 0)); return results; }
        auto wd = read_wallet_backup(inst, "_entmap");
        if (wd.empty()) { results.push_back(make_finding(ver, "entropy", "ENT-MAP-NOBK", "SKIP", "", 0)); return results; }
        // Compute entropy per 256-byte block
        int low_entropy_blocks = 0; int high_entropy_blocks = 0; int total_blocks = 0;
        for (size_t off = 0; off + 256 <= wd.size(); off += 256) {
            int freq[256] = {};
            for (size_t j = off; j < off + 256; j++) freq[(uint8_t)wd[j]]++;
            double ent = 0;
            for (int i = 0; i < 256; i++) {
                if (freq[i] == 0) continue;
                double px = freq[i] / 256.0;
                ent -= px * std::log2(px);
            }
            total_blocks++;
            if (ent < 3.0) low_entropy_blocks++;
            else if (ent > 7.5) high_entropy_blocks++;
        }
        double low_ratio = (total_blocks > 0) ? (double)low_entropy_blocks / total_blocks : 0;
        if (low_ratio > 0.15) {
            char rb[32]; snprintf(rb, sizeof(rb), "%.1f%%", low_ratio * 100);
            results.push_back(make_finding(ver, "entropy", "ENT-MAP-LOWENT-"+ver,
                "MEDIUM: " + std::string(rb) + " of wallet blocks have entropy<3.0 (" +
                std::to_string(low_entropy_blocks) + "/" + std::to_string(total_blocks) +
                ") — possible plaintext key regions", "", 5));
        } else {
            results.push_back(make_finding(ver, "entropy", "ENT-MAP-OK-"+ver,
                "PASS: " + std::to_string(low_entropy_blocks) + "/" + std::to_string(total_blocks) +
                " low-entropy blocks", "", 0));
        }
        return results;
    }

    // 84.9.2: Ciphertext vs Plaintext Region Classifier
    std::vector<DynamicFinding> engine_entropy_classifier(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_encrypted) { results.push_back(make_finding(ver, "entropy", "ENT-CLASS-SKIP", "SKIP", "", 0)); return results; }
        auto wd = read_wallet_backup(inst, "_entclass");
        if (wd.empty()) { results.push_back(make_finding(ver, "entropy", "ENT-CLASS-NOBK", "SKIP", "", 0)); return results; }
        // Look for transitions from high-entropy to low-entropy regions
        // which indicate ciphertext-plaintext boundaries
        int transitions = 0; bool prev_high = false;
        std::vector<size_t> boundary_offsets;
        for (size_t off = 0; off + 64 <= wd.size(); off += 64) {
            int freq[256] = {};
            for (size_t j = off; j < off + 64; j++) freq[(uint8_t)wd[j]]++;
            double ent = 0;
            for (int i = 0; i < 256; i++) {
                if (freq[i] == 0) continue;
                double px = freq[i] / 64.0;
                ent -= px * std::log2(px);
            }
            bool cur_high = ent > 6.0;
            if (prev_high && !cur_high) { transitions++; boundary_offsets.push_back(off); }
            prev_high = cur_high;
        }
        if (transitions > 3) {
            std::string offsets_str;
            for (size_t i = 0; i < std::min(boundary_offsets.size(), (size_t)5); i++)
                offsets_str += "0x" + ([](size_t v){ char b[20]; snprintf(b,sizeof(b),"%zx",v); return std::string(b); })(boundary_offsets[i]) + " ";
            results.push_back(make_finding(ver, "entropy", "ENT-CLASS-TRANS-"+ver,
                "MEDIUM: " + std::to_string(transitions) + " cipher/plain boundaries at [" + offsets_str + "]",
                "", 5));
        } else {
            results.push_back(make_finding(ver, "entropy", "ENT-CLASS-OK-"+ver,
                "PASS: " + std::to_string(transitions) + " transitions", "", 0));
        }
        return results;
    }

    // 84.9.3: Debug.log Entropy Anomaly
    std::vector<DynamicFinding> engine_entropy_debuglog(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        std::string rd = inst.data_directory + (inst.is_regtest ? "/regtest" : "");
        std::string debug_log = rd + "/debug.log";
        std::ifstream dl(debug_log);
        if (!dl.is_open()) { results.push_back(make_finding(ver, "entropy", "ENT-DLOG-NODL", "SKIP", "", 0)); return results; }
        int high_entropy_lines = 0; int total_lines = 0;
        std::string line;
        while (std::getline(dl, line) && total_lines < 10000) {
            total_lines++;
            if (line.size() < 20) continue;
            // Check if line has anomalously high entropy (possible binary leak)
            int freq[256] = {};
            for (char c : line) freq[(uint8_t)c]++;
            double ent = 0;
            for (int i = 0; i < 256; i++) {
                if (freq[i] == 0) continue;
                double px = freq[i] / (double)line.size();
                ent -= px * std::log2(px);
            }
            if (ent > 5.0 && line.size() > 40) high_entropy_lines++;
        }
        if (high_entropy_lines > 10) {
            results.push_back(make_finding(ver, "entropy", "ENT-DLOG-HIGHENT-"+ver,
                "LOW: " + std::to_string(high_entropy_lines) + "/" + std::to_string(total_lines) +
                " high-entropy lines in debug.log — possible binary data leak", "", 3));
        } else {
            results.push_back(make_finding(ver, "entropy", "ENT-DLOG-OK-"+ver,
                "PASS: " + std::to_string(high_entropy_lines) + " high-entropy lines", "", 0));
        }
        return results;
    }

    // 84.9.4: RPC Error Entropy (information leakage via error diversity)
    std::vector<DynamicFinding> engine_entropy_rpc_errors(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_encrypted) { results.push_back(make_finding(ver, "entropy", "ENT-RPCE-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        // Probe 30 sensitive RPCs while locked and classify error responses
        std::vector<std::string> rpcs = {
            "dumpprivkey", "dumpwallet", "importprivkey", "importwallet",
            "signmessage", "signrawtransactionwithwallet", "sendtoaddress",
            "sendmany", "fundrawtransaction", "bumpfee", "walletprocesspsbt",
            "getnewaddress", "getrawchangeaddress", "keypoolrefill",
            "listunspent", "listtransactions", "getbalance", "getwalletinfo",
            "listaddressgroupings", "getaddressesbylabel", "listreceivedbyaddress",
            "rescanblockchain", "backupwallet", "encryptwallet",
            "sethdseed", "importdescriptors", "listdescriptors",
            "createwallet", "upgradewallet", "getbalances"
        };
        std::map<std::string, int> error_classes;
        int accessible_while_locked = 0;
        for (auto& cmd : rpcs) {
            auto r = rpc(inst, cmd);
            if (r.success && !r.is_error()) {
                accessible_while_locked++;
                error_classes["SUCCESS"]++;
            } else {
                std::string code = jx(r.output, "code");
                error_classes[code]++;
            }
        }
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        if (accessible_while_locked > 10) {
            results.push_back(make_finding(ver, "entropy", "ENT-RPCE-WIDE-"+ver,
                "MEDIUM: " + std::to_string(accessible_while_locked) + "/" + std::to_string(rpcs.size()) +
                " RPCs succeed while locked, " + std::to_string(error_classes.size()) + " error classes", "", 5));
        } else if (error_classes.size() > 5) {
            results.push_back(make_finding(ver, "entropy", "ENT-RPCE-DIVERSE-"+ver,
                "LOW: " + std::to_string(error_classes.size()) + " distinct error classes across " +
                std::to_string(rpcs.size()) + " RPCs", "", 2));
        } else {
            results.push_back(make_finding(ver, "entropy", "ENT-RPCE-OK-"+ver,
                "PASS: " + std::to_string(error_classes.size()) + " error classes, " +
                std::to_string(accessible_while_locked) + " accessible", "", 0));
        }
        return results;
    }

