    // 84.10.1: getbalance Timing (locked vs unlocked comparison)
    std::vector<DynamicFinding> engine_timing_getbalance(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "timing", "TIM-BAL-SKIP", "SKIP", "", 0)); return results; }
        // Measure locked
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        std::vector<double> locked_ts;
        for (int i = 0; i < 10; i++) locked_ts.push_back(timed_rpc(inst, "getbalance").elapsed_ms);
        // Measure unlocked
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        std::vector<double> unlocked_ts;
        for (int i = 0; i < 10; i++) unlocked_ts.push_back(timed_rpc(inst, "getbalance").elapsed_ms);
        double lm = 0, um = 0;
        for (auto t : locked_ts) lm += t; lm /= locked_ts.size();
        for (auto t : unlocked_ts) um += t; um /= unlocked_ts.size();
        double diff = std::abs(lm - um);
        if (diff > 20)
            results.push_back(make_finding(ver, "timing", "TIM-BAL-DIFF-"+ver,
                "LOW: getbalance locked=" + std::to_string((int)lm) + "ms unlocked=" +
                std::to_string((int)um) + "ms — timing leaks lock state", "", 2));
        else
            results.push_back(make_finding(ver, "timing", "TIM-BAL-OK-"+ver,
                "PASS: diff=" + std::to_string((int)diff) + "ms", "", 0));
        return results;
    }

