    // 84.10.5: keypoolrefill CPU Timing Oracle
    std::vector<DynamicFinding> engine_timing_keypoolrefill(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_encrypted) { results.push_back(make_finding(ver, "timing", "TIM-KPR-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        auto t1 = timed_rpc(inst, "keypoolrefill", "1");
        auto t2 = timed_rpc(inst, "keypoolrefill", "100");
        bool r1_ok = t1.success && !t1.response.empty();
        double diff = (t1.elapsed_ms > 0.1) ? t2.elapsed_ms / t1.elapsed_ms : 1.0;
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        if (r1_ok && diff > 3.0)
            results.push_back(make_finding(ver, "timing", "TIM-KPR-SCALE-"+ver,
                "LOW: keypoolrefill scales " + std::to_string((int)diff) + "x while locked — leaks keypool state", "", 2));
        else
            results.push_back(make_finding(ver, "timing", "TIM-KPR-OK-"+ver,
                "PASS: ratio=" + std::to_string((int)diff), "", 0));
        return results;
    }

    // 84.10.6: signrawtransactionwithkey Error Differentiation
    std::vector<DynamicFinding> engine_timing_signraw_error(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em < 18 || !p.wallet_available) { results.push_back(make_finding(ver, "timing", "TIM-SRE-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        // Try signing with wrong key while locked
        auto sr1 = rpc(inst, "signrawtransactionwithkey",
            "\"0200000001\" [\"cVt4o7BGAig1UXywgGSmARhxMdzP5qvQsxKkSsc1XEkw3tDTQFpy\"]");
        auto sr2 = rpc(inst, "signrawtransactionwithwallet", "\"0200000001\"");
        std::string e1 = jx(sr1.output, "code");
        std::string e2 = jx(sr2.output, "code");
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        if (e1 != e2 && !e1.empty() && !e2.empty())
            results.push_back(make_finding(ver, "timing", "TIM-SRE-DIVERGE-"+ver,
                "LOW: signrawtxwithkey vs signrawtxwithwallet error divergence while locked ("+e1+" vs "+e2+")", "", 2));
        else
            results.push_back(make_finding(ver, "timing", "TIM-SRE-OK-"+ver, "PASS", "", 0));
        return results;
    }

