    // 84.11.3: Descriptor Wallet SQLite Direct Query
    std::vector<DynamicFinding> engine_desc_sqlite_query(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em < 23) { results.push_back(make_finding(ver, "desc", "DESC-SQL-SKIP", "SKIP", "", 0)); return results; }
        std::string rd = inst.data_directory + (inst.is_regtest ? "/regtest" : "");
        std::string db_path;
        // Find the SQLite wallet database
        try {
            for (auto& p2 : {rd + "/wallets/" + inst.wallet_name + "/wallet.dat",
                            rd + "/wallets/" + inst.wallet_name + "/wallet.sqlite"}) {
                if (std::filesystem::exists(p2)) { db_path = p2; break; }
            }
        } catch (...) {}
        if (db_path.empty()) { results.push_back(make_finding(ver, "desc", "DESC-SQL-NODB", "SKIP", "", 0)); return results; }
        // Check SQLite file header and look for plaintext key material
        std::ifstream f(db_path, std::ios::binary);
        if (!f.is_open()) { results.push_back(make_finding(ver, "desc", "DESC-SQL-NOREAD", "SKIP", "", 0)); return results; }
        std::vector<uint8_t> data(2*1024*1024);
        f.read(reinterpret_cast<char*>(data.data()), data.size());
        data.resize((size_t)f.gcount()); f.close();
        auto ks = scan_for_key_material(data);
        int total_keys = ks.der_keys + ks.wif_candidates + ks.xprv_strings;
        if (total_keys > 0)
            results.push_back(make_finding(ver, "desc", "DESC-SQL-KEYS-"+ver,
                "HIGH: SQLite wallet contains " + std::to_string(total_keys) + " plaintext key patterns (DER=" +
                std::to_string(ks.der_keys) + " WIF=" + std::to_string(ks.wif_candidates) +
                " xprv=" + std::to_string(ks.xprv_strings) + ")", "", 7));
        else
            results.push_back(make_finding(ver, "desc", "DESC-SQL-CLEAN-"+ver,
                "PASS: No plaintext keys in SQLite wallet", "", 0));
        return results;
    }

    // 84.11.4: getaddressinfo Locked Depth
    std::vector<DynamicFinding> engine_desc_addrinfo(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em < 18 || !p.wallet_available || p.test_addresses.empty()) {
            results.push_back(make_finding(ver, "desc", "DESC-ADDR-SKIP", "SKIP", "", 0)); return results;
        }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        auto ai = rpc(inst, "getaddressinfo", "\"" + p.test_addresses[0] + "\"");
        int fields_exposed = 0;
        if (ai.success && !ai.is_error()) {
            if (ai.has("\"pubkey\"")) fields_exposed++;
            if (ai.has("\"hdkeypath\"")) fields_exposed++;
            if (ai.has("\"hdseedid\"")) fields_exposed++;
            if (ai.has("\"desc\"")) fields_exposed++;
            if (ai.has("\"parent_desc\"")) fields_exposed++;
            if (ai.has("\"scriptPubKey\"")) fields_exposed++;
            if (ai.has("\"ismine\": true")) fields_exposed++;
        }
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        if (fields_exposed >= 4)
            results.push_back(make_finding(ver, "desc", "DESC-ADDR-RICH-"+ver,
                "MEDIUM: getaddressinfo exposes " + std::to_string(fields_exposed) + " fields while locked " +
                "(pubkey, hdkeypath, descriptor, etc.)", "", 4));
        else if (fields_exposed > 0)
            results.push_back(make_finding(ver, "desc", "DESC-ADDR-PARTIAL-"+ver,
                "LOW: " + std::to_string(fields_exposed) + " fields exposed while locked", "", 2));
        else
            results.push_back(make_finding(ver, "desc", "DESC-ADDR-BLOCKED-"+ver,
                "PASS: getaddressinfo blocked or minimal", "", 0));
        return results;
    }

