    // PSBT family dispatcher
    std::vector<DynamicFinding> engine_psbt_family(VersionInstance& inst, const ChainParams& p) {
        ScopedProfile prof("PSBT", "psbt_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto p1=engine_psbt_create(inst,p);      r.insert(r.end(),p1.begin(),p1.end());
        auto p2=engine_psbt_process(inst,p);     r.insert(r.end(),p2.begin(),p2.end());
        auto p3=engine_psbt_analyze(inst,p);     r.insert(r.end(),p3.begin(),p3.end());
        auto p4=engine_psbt_utxoupdate(inst,p);  r.insert(r.end(),p4.begin(),p4.end());
        return r;
    }

