    // 84.17.2: lockunspent Locked
    std::vector<DynamicFinding> engine_cc_lockunspent(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available || p.utxos.empty()) {
            results.push_back(make_finding(ver, "coinctrl", "CC-LOCKUTXO-SKIP", "SKIP", "", 0)); return results;
        }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        auto lu = rpc(inst, "lockunspent", "false '[{\"txid\":\"" + p.utxos[0].txid +
            "\",\"vout\":" + std::to_string(p.utxos[0].vout) + "}]'");
        bool locked_utxo = lu.success && !lu.is_error();
        // Unlock it
        rpc(inst, "lockunspent", "true '[{\"txid\":\"" + p.utxos[0].txid +
            "\",\"vout\":" + std::to_string(p.utxos[0].vout) + "}]'");
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        if (locked_utxo)
            results.push_back(make_finding(ver, "coinctrl", "CC-LOCKUTXO-ACCEPT-"+ver,
                "MEDIUM: lockunspent modifies UTXO lock state while wallet is locked", "", 4));
        else
            results.push_back(make_finding(ver, "coinctrl", "CC-LOCKUTXO-BLOCKED-"+ver, "PASS", "", 0));
        return results;
    }

    // 84.17.3: getbalances Locked Granularity
    std::vector<DynamicFinding> engine_cc_getbalances(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em < 22 || !p.wallet_available) { results.push_back(make_finding(ver, "coinctrl", "CC-GBAL-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        auto gb = rpc(inst, "getbalances");
        int balance_fields = 0;
        if (gb.success && !gb.is_error()) {
            if (gb.has("\"trusted\"")) balance_fields++;
            if (gb.has("\"untrusted_pending\"")) balance_fields++;
            if (gb.has("\"immature\"")) balance_fields++;
            if (gb.has("\"used\"")) balance_fields++;
        }
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        if (balance_fields >= 3)
            results.push_back(make_finding(ver, "coinctrl", "CC-GBAL-RICH-"+ver,
                "LOW: getbalances returns " + std::to_string(balance_fields) + " balance categories while locked", "", 2));
        else
            results.push_back(make_finding(ver, "coinctrl", "CC-GBAL-OK-"+ver,
                "PASS: " + std::to_string(balance_fields) + " fields", "", 0));
        return results;
    }

    // 84.17.4: listsinceblock Locked
    std::vector<DynamicFinding> engine_cc_listsinceblock(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "coinctrl", "CC-LSB-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        auto lsb = rpc(inst, "listsinceblock");
        int tx_count = 0;
        if (lsb.success && !lsb.is_error()) {
            size_t pos = 0;
            while ((pos = lsb.output.find("\"txid\"", pos+1)) != std::string::npos) tx_count++;
        }
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        if (tx_count > 0)
            results.push_back(make_finding(ver, "coinctrl", "CC-LSB-EXPOSED-"+ver,
                "MEDIUM: listsinceblock returns " + std::to_string(tx_count) + " transactions while locked", "", 4));
        else
            results.push_back(make_finding(ver, "coinctrl", "CC-LSB-OK-"+ver, "PASS", "", 0));
        return results;
    }

