    // ----------------------------------------------------------------
    // 84.21: KL-FILESYSTEM-PERMS — File Permission & Ownership Audit (4)
    // ----------------------------------------------------------------

    // 84.21.1: Datadir Permission Scan
    std::vector<DynamicFinding> engine_fsperm_datadir(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        std::string rd = inst.data_directory + (inst.is_regtest ? "/regtest" : "");
        int world_issues = 0; int group_issues = 0;
        std::vector<std::string> sensitive_dirs = {rd, rd + "/wallets", rd + "/blocks", rd + "/chainstate"};
        for (auto& d : sensitive_dirs) {
            struct stat st;
            if (stat(d.c_str(), &st) == 0) {
                if (st.st_mode & S_IROTH) world_issues++;
                if (st.st_mode & S_IWOTH) world_issues++;
                if (st.st_mode & S_IWGRP) group_issues++;
            }
        }
        if (world_issues > 0)
            results.push_back(make_finding(ver, "fsperm", "FSP-DIR-WORLD-"+ver,
                "MEDIUM: " + std::to_string(world_issues) + " world-accessible permissions on datadir subdirectories",
                "", 5));
        else if (group_issues > 0)
            results.push_back(make_finding(ver, "fsperm", "FSP-DIR-GROUP-"+ver,
                "LOW: " + std::to_string(group_issues) + " group-writable directories", "", 2));
        else
            results.push_back(make_finding(ver, "fsperm", "FSP-DIR-OK-"+ver,
                "PASS: Directory permissions secure", "", 0));
        return results;
    }

    // 84.21.2: Cookie Auth File Permission
    std::vector<DynamicFinding> engine_fsperm_cookie(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        std::string rd = inst.data_directory + (inst.is_regtest ? "/regtest" : "");
        std::string cookie_path = rd + "/.cookie";
        struct stat st;
        if (stat(cookie_path.c_str(), &st) == 0) {
            bool world_read = st.st_mode & S_IROTH;
            bool group_read = st.st_mode & S_IRGRP;
            if (world_read)
                results.push_back(make_finding(ver, "fsperm", "FSP-COOKIE-WORLD-"+ver,
                    "HIGH: .cookie file is world-readable — any local user can authenticate to RPC", "", 7));
            else if (group_read)
                results.push_back(make_finding(ver, "fsperm", "FSP-COOKIE-GROUP-"+ver,
                    "MEDIUM: .cookie file is group-readable", "", 4));
            else
                results.push_back(make_finding(ver, "fsperm", "FSP-COOKIE-OK-"+ver,
                    "PASS: .cookie file permissions secure (mode=" +
                    std::to_string(st.st_mode & 0777) + ")", "", 0));
        } else {
            results.push_back(make_finding(ver, "fsperm", "FSP-COOKIE-NONE-"+ver,
                "INFO: No .cookie file found", "", 0));
        }
        return results;
    }

    // 84.21.3: bitcoin.conf Credential Exposure
    std::vector<DynamicFinding> engine_fsperm_conf(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        std::string conf_path = inst.data_directory + "/bitcoin.conf";
        std::ifstream cf(conf_path);
        if (!cf.is_open()) {
            results.push_back(make_finding(ver, "fsperm", "FSP-CONF-NOFILE-"+ver, "INFO: No bitcoin.conf", "", 0));
            return results;
        }
        bool has_rpcpassword = false; bool has_rpcauth = false;
        std::string line;
        while (std::getline(cf, line)) {
            // Strip comments
            size_t hash = line.find('#');
            if (hash != std::string::npos) line = line.substr(0, hash);
            if (line.find("rpcpassword=") != std::string::npos) has_rpcpassword = true;
            if (line.find("rpcauth=") != std::string::npos) has_rpcauth = true;
        }
        struct stat st;
        bool world_read = false;
        if (stat(conf_path.c_str(), &st) == 0) world_read = st.st_mode & S_IROTH;
        if (has_rpcpassword && world_read)
            results.push_back(make_finding(ver, "fsperm", "FSP-CONF-EXPOSED-"+ver,
                "CRITICAL: bitcoin.conf contains rpcpassword and is world-readable", "", 9));
        else if (has_rpcpassword)
            results.push_back(make_finding(ver, "fsperm", "FSP-CONF-RPCPW-"+ver,
                "MEDIUM: bitcoin.conf uses deprecated rpcpassword (prefer rpcauth)", "", 4));
        else if (has_rpcauth)
            results.push_back(make_finding(ver, "fsperm", "FSP-CONF-AUTH-"+ver,
                "PASS: Uses rpcauth (hashed credentials)", "", 0));
        else
            results.push_back(make_finding(ver, "fsperm", "FSP-CONF-NOCRED-"+ver,
                "INFO: No RPC credentials in conf", "", 0));
        return results;
    }

    // 84.21.4: Stale Lock File Detection
    std::vector<DynamicFinding> engine_fsperm_lockfile(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        std::string rd = inst.data_directory + (inst.is_regtest ? "/regtest" : "");
        std::vector<std::string> lock_files = {
            rd + "/.lock", rd + "/db.log", rd + "/banlist.json",
            rd + "/fee_estimates.dat", rd + "/peers.dat"
        };
        int stale_files = 0;
        for (auto& lf : lock_files) {
            struct stat st;
            if (stat(lf.c_str(), &st) == 0) {
                // Check if file is older than 7 days (stale)
                time_t now = time(nullptr);
                if (now - st.st_mtime > 7 * 86400) stale_files++;
            }
        }
        if (stale_files > 2)
            results.push_back(make_finding(ver, "fsperm", "FSP-STALE-"+ver,
                "LOW: " + std::to_string(stale_files) + " stale state files (possible unclean shutdown)", "", 2));
        else
            results.push_back(make_finding(ver, "fsperm", "FSP-STALE-OK-"+ver, "PASS", "", 0));
        return results;
    }

    // Filesystem permissions family dispatcher
    std::vector<DynamicFinding> engine_fsperm_family(VersionInstance& inst, const ChainParams& p) {
        ScopedProfile prof("FSP", "fsperm_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto f1=engine_fsperm_datadir(inst,p);   r.insert(r.end(),f1.begin(),f1.end());
        auto f2=engine_fsperm_cookie(inst,p);    r.insert(r.end(),f2.begin(),f2.end());
        auto f3=engine_fsperm_conf(inst,p);      r.insert(r.end(),f3.begin(),f3.end());
        auto f4=engine_fsperm_lockfile(inst,p);  r.insert(r.end(),f4.begin(),f4.end());
        return r;
    }

