    // 84.23.1: getwalletinfo Locked Depth
    std::vector<DynamicFinding> engine_meta_walletinfo(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "meta", "META-WI-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        auto wi = rpc(inst, "getwalletinfo");
        int fields = 0;
        if (wi.success && !wi.is_error()) {
            if (wi.has("\"walletname\"")) fields++;
            if (wi.has("\"walletversion\"")) fields++;
            if (wi.has("\"balance\"")) fields++;
            if (wi.has("\"unconfirmed_balance\"")) fields++;
            if (wi.has("\"immature_balance\"")) fields++;
            if (wi.has("\"txcount\"")) fields++;
            if (wi.has("\"keypoololdest\"")) fields++;
            if (wi.has("\"keypoolsize\"")) fields++;
            if (wi.has("\"hdseedid\"")) fields++;
            if (wi.has("\"private_keys_enabled\"")) fields++;
            if (wi.has("\"unlocked_until\"")) fields++;
            if (wi.has("\"paytxfee\"")) fields++;
        }
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        if (fields >= 8)
            results.push_back(make_finding(ver, "meta", "META-WI-RICH-"+ver,
                "MEDIUM: getwalletinfo exposes " + std::to_string(fields) +
                " fields while locked (balance, txcount, hdseedid, etc.)", "", 4));
        else if (fields > 0)
            results.push_back(make_finding(ver, "meta", "META-WI-PARTIAL-"+ver,
                "LOW: " + std::to_string(fields) + " fields exposed while locked", "", 2));
        else
            results.push_back(make_finding(ver, "meta", "META-WI-BLOCKED-"+ver, "PASS", "", 0));
        return results;
    }

