    // ----------------------------------------------------------------
    // 84.25: KL-BDB-STRUCTURE — BDB Internal Structure Analysis (4)
    // ----------------------------------------------------------------

    // 84.25.1: BDB Page Size / Slack Space Analysis
    std::vector<DynamicFinding> engine_bdb_slack(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em >= 23) { results.push_back(make_finding(ver, "bdb", "BDB-SLACK-NA", "SKIP: SQLite wallet", "", 0)); return results; }
        auto wd = read_wallet_backup(inst, "_bdbslack");
        if (wd.size() < 4096) { results.push_back(make_finding(ver, "bdb", "BDB-SLACK-SMALL", "SKIP", "", 0)); return results; }
        // BDB uses 4096-byte pages typically. Check slack space in each page for key remnants
        int pages_with_keys = 0; int total_pages = 0;
        size_t page_size = 4096;
        // Try to read page size from header (offset 20, 4 bytes LE)
        if (wd.size() > 24) {
            uint32_t ps = uint32_t(wd[20]) | (uint32_t(wd[21])<<8) | (uint32_t(wd[22])<<16) | (uint32_t(wd[23])<<24);
            if (ps >= 512 && ps <= 65536 && (ps & (ps-1)) == 0) page_size = ps;
        }
        for (size_t off = page_size; off + page_size <= wd.size() && total_pages < 1000; off += page_size) {
            total_pages++;
            // Check last 256 bytes of each page (slack space)
            size_t slack_start = off + page_size - 256;
            std::vector<uint8_t> slack(wd.begin() + slack_start, wd.begin() + off + page_size);
            auto ks = scan_for_key_material(slack);
            if (ks.der_keys > 0 || ks.wif_candidates > 0) pages_with_keys++;
        }
        if (pages_with_keys > 0)
            results.push_back(make_finding(ver, "bdb", "BDB-SLACK-KEYS-"+ver,
                "MEDIUM: " + std::to_string(pages_with_keys) + "/" + std::to_string(total_pages) +
                " BDB pages contain key remnants in slack space (page_size=" + std::to_string(page_size) + ")",
                "", 5));
        else
            results.push_back(make_finding(ver, "bdb", "BDB-SLACK-CLEAN-"+ver,
                "PASS: " + std::to_string(total_pages) + " pages scanned, no keys in slack", "", 0));
        return results;
    }

    // 84.25.2: BDB Overflow Page Analysis
    std::vector<DynamicFinding> engine_bdb_overflow(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em >= 23) { results.push_back(make_finding(ver, "bdb", "BDB-OVF-NA", "SKIP: SQLite", "", 0)); return results; }
        auto wd = read_wallet_backup(inst, "_bdbovf");
        if (wd.size() < 8192) { results.push_back(make_finding(ver, "bdb", "BDB-OVF-SMALL", "SKIP", "", 0)); return results; }
        // Look for BDB overflow page markers and scan them for key data
        // BDB page type at offset 25 in page header: P_OVERFLOW = 7
        int overflow_pages = 0; int overflow_with_keys = 0;
        size_t page_size = 4096;
        if (wd.size() > 24) {
            uint32_t ps = uint32_t(wd[20]) | (uint32_t(wd[21])<<8) | (uint32_t(wd[22])<<16) | (uint32_t(wd[23])<<24);
            if (ps >= 512 && ps <= 65536 && (ps & (ps-1)) == 0) page_size = ps;
        }
        for (size_t off = page_size; off + page_size <= wd.size(); off += page_size) {
            // Page type is at offset 25 within page header
            if (off + 26 < wd.size() && wd[off + 25] == 7) {
                overflow_pages++;
                std::vector<uint8_t> page_data(wd.begin() + off, wd.begin() + off + page_size);
                auto ks = scan_for_key_material(page_data);
                if (ks.der_keys > 0 || ks.wif_candidates > 0 || ks.xprv_strings > 0)
                    overflow_with_keys++;
            }
        }
        if (overflow_with_keys > 0)
            results.push_back(make_finding(ver, "bdb", "BDB-OVF-KEYS-"+ver,
                "MEDIUM: " + std::to_string(overflow_with_keys) + "/" + std::to_string(overflow_pages) +
                " BDB overflow pages contain key material", "", 5));
        else
            results.push_back(make_finding(ver, "bdb", "BDB-OVF-CLEAN-"+ver,
                "PASS: " + std::to_string(overflow_pages) + " overflow pages clean", "", 0));
        return results;
    }

    // 84.25.3: BDB Free List Analysis
    std::vector<DynamicFinding> engine_bdb_freelist(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em >= 23) { results.push_back(make_finding(ver, "bdb", "BDB-FREE-NA", "SKIP: SQLite", "", 0)); return results; }
        auto wd = read_wallet_backup(inst, "_bdbfree");
        if (wd.size() < 4096) { results.push_back(make_finding(ver, "bdb", "BDB-FREE-SMALL", "SKIP", "", 0)); return results; }
        // BDB header: free list pointer at offset 16 (4 bytes)
        uint32_t free_ptr = (wd.size() > 20) ? (uint32_t(wd[16]) | (uint32_t(wd[17])<<8) |
            (uint32_t(wd[18])<<16) | (uint32_t(wd[19])<<24)) : 0;
        int free_pages = 0; int free_with_keys = 0;
        size_t page_size = 4096;
        if (wd.size() > 24) {
            uint32_t ps = uint32_t(wd[20]) | (uint32_t(wd[21])<<8) | (uint32_t(wd[22])<<16) | (uint32_t(wd[23])<<24);
            if (ps >= 512 && ps <= 65536 && (ps & (ps-1)) == 0) page_size = ps;
        }
        // Follow free list
        uint32_t cur = free_ptr;
        while (cur > 0 && cur < wd.size() / page_size && free_pages < 100) {
            size_t off = cur * page_size;
            if (off + page_size > wd.size()) break;
            free_pages++;
            std::vector<uint8_t> fpage(wd.begin() + off, wd.begin() + off + page_size);
            auto ks = scan_for_key_material(fpage);
            if (ks.der_keys > 0 || ks.wif_candidates > 0) free_with_keys++;
            // Next free page pointer at offset 12 in page header
            if (off + 16 < wd.size())
                cur = uint32_t(wd[off+12]) | (uint32_t(wd[off+13])<<8) |
                      (uint32_t(wd[off+14])<<16) | (uint32_t(wd[off+15])<<24);
            else break;
        }
        if (free_with_keys > 0)
            results.push_back(make_finding(ver, "bdb", "BDB-FREE-KEYS-"+ver,
                "MEDIUM: " + std::to_string(free_with_keys) + "/" + std::to_string(free_pages) +
                " BDB free list pages contain key remnants", "", 5));
        else
            results.push_back(make_finding(ver, "bdb", "BDB-FREE-CLEAN-"+ver,
                "PASS: " + std::to_string(free_pages) + " free pages clean", "", 0));
        return results;
    }

    // 84.25.4: BDB Header Metadata Disclosure
    std::vector<DynamicFinding> engine_bdb_header(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em >= 23) { results.push_back(make_finding(ver, "bdb", "BDB-HDR-NA", "SKIP: SQLite", "", 0)); return results; }
        auto wd = read_wallet_backup(inst, "_bdbhdr");
        if (wd.size() < 512) { results.push_back(make_finding(ver, "bdb", "BDB-HDR-SMALL", "SKIP", "", 0)); return results; }
        // BDB metadata page: magic, version, pagesize, encrypt_alg, etc.
        uint32_t magic = (wd.size() > 16) ? (uint32_t(wd[12]) | (uint32_t(wd[13])<<8) |
            (uint32_t(wd[14])<<16) | (uint32_t(wd[15])<<24)) : 0;
        uint32_t bdb_version = (wd.size() > 20) ? (uint32_t(wd[16]) | (uint32_t(wd[17])<<8) |
            (uint32_t(wd[18])<<16) | (uint32_t(wd[19])<<24)) : 0;
        uint32_t pagesize = (wd.size() > 24) ? (uint32_t(wd[20]) | (uint32_t(wd[21])<<8) |
            (uint32_t(wd[22])<<16) | (uint32_t(wd[23])<<24)) : 0;
        // Count total records (key + data pairs)
        int record_count = 0;
        for (size_t i = 0; i < wd.size() - 4; i++) {
            // Look for "name" key pattern (BDB key records)
            if (wd[i]=='n'&&wd[i+1]=='a'&&wd[i+2]=='m'&&wd[i+3]=='e') record_count++;
            if (wd[i]=='k'&&wd[i+1]=='e'&&wd[i+2]=='y'&&i+3<wd.size()&&wd[i+3]==0x00) record_count++;
        }
        results.push_back(make_finding(ver, "bdb", "BDB-HDR-META-"+ver,
            "INFO: BDB v" + std::to_string(bdb_version) + " pagesize=" +
            std::to_string(pagesize) + " records~" + std::to_string(record_count),
            "", record_count > 100 ? 1 : 0));
        return results;
    }

    // BDB structure family dispatcher
    std::vector<DynamicFinding> engine_bdb_family(VersionInstance& inst, const ChainParams& p) {
        ScopedProfile prof("BDB", "bdb_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto b1=engine_bdb_slack(inst,p);      r.insert(r.end(),b1.begin(),b1.end());
        auto b2=engine_bdb_overflow(inst,p);   r.insert(r.end(),b2.begin(),b2.end());
        auto b3=engine_bdb_freelist(inst,p);   r.insert(r.end(),b3.begin(),b3.end());
        auto b4=engine_bdb_header(inst,p);     r.insert(r.end(),b4.begin(),b4.end());
        return r;
    }

    // ----------------------------------------------------------------
    // 84.26: KL-PROCESS-NOVEL — Process & Environment Leak Engines (4)
    // ----------------------------------------------------------------

    // 84.26.1: /proc/pid/cmdline Check
    std::vector<DynamicFinding> engine_proc_cmdline(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        // Find bitcoind PID and check cmdline
        auto ps = popen_with_timeout("pgrep -a bitcoin 2>/dev/null | head -5", 2);
        bool passphrase_in_cmdline = false; int processes = 0;
        if (!ps.timed_out && !ps.output.empty()) {
            std::istringstream iss(ps.output); std::string line;
            while (std::getline(iss, line)) {
                if (line.empty()) continue; processes++;
                if (line.find("passphrase") != std::string::npos ||
                    line.find("rpcpassword") != std::string::npos)
                    passphrase_in_cmdline = true;
            }
        }
        if (passphrase_in_cmdline)
            results.push_back(make_finding(ver, "proc", "PROC-CMD-PASS-"+ver,
                "HIGH: Passphrase/password visible in process cmdline", "", 7));
        else
            results.push_back(make_finding(ver, "proc", "PROC-CMD-OK-"+ver,
                "PASS: " + std::to_string(processes) + " bitcoin processes, no credentials in cmdline", "", 0));
        return results;
    }

    // 84.26.2: Environment Variable Leak
    std::vector<DynamicFinding> engine_proc_environ(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        // Check for sensitive env vars
        std::vector<std::string> sensitive_vars = {
            "BITCOIN_RPC_PASSWORD", "BTC_PASSPHRASE", "WALLET_PASSWORD",
            "BITCOIN_CONF", "RPC_AUTH"
        };
        int leaked = 0;
        for (auto& v : sensitive_vars) {
            const char* val = getenv(v.c_str());
            if (val && strlen(val) > 0) leaked++;
        }
        if (leaked > 0)
            results.push_back(make_finding(ver, "proc", "PROC-ENV-LEAK-"+ver,
                "MEDIUM: " + std::to_string(leaked) + " sensitive environment variables set", "", 5));
        else
            results.push_back(make_finding(ver, "proc", "PROC-ENV-OK-"+ver, "PASS", "", 0));
        return results;
    }

    // 84.26.3: Open File Descriptor Analysis
    std::vector<DynamicFinding> engine_proc_fds(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        auto lsof = popen_with_timeout("lsof -c bitcoind 2>/dev/null | wc -l", 2);
        int fd_count = 0;
        if (!lsof.timed_out) { try { fd_count = std::stoi(lsof.output); } catch (...) {} }
        results.push_back(make_finding(ver, "proc", "PROC-FDS-"+ver,
            "INFO: bitcoind has " + std::to_string(fd_count) + " open file descriptors", "", 0));
        return results;
    }

    // 84.26.4: Swap File Key Exposure Check
    std::vector<DynamicFinding> engine_proc_swap(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        auto sw = popen_with_timeout("sysctl vm.swapusage 2>/dev/null || swapon --show 2>/dev/null", 2);
        bool swap_active = false;
        if (!sw.timed_out && !sw.output.empty()) {
            if (sw.output.find("used = 0") == std::string::npos &&
                sw.output.find("0B") == std::string::npos) swap_active = true;
        }
        // Check mlock status
        auto mi = rpc(inst, "getmemoryinfo", "\"stats\"");
        std::string locked = jx(mi.output, "locked");
        int64_t lv = 0; try { lv = std::stoll(locked); } catch (...) {}
        if (swap_active && lv == 0)
            results.push_back(make_finding(ver, "proc", "PROC-SWAP-RISK-"+ver,
                "MEDIUM: Swap is active with no mlock protection — keys may be swapped to disk", "", 5));
        else if (swap_active)
            results.push_back(make_finding(ver, "proc", "PROC-SWAP-PARTIAL-"+ver,
                "LOW: Swap active but mlock=" + std::to_string(lv) + "B", "", 2));
        else
            results.push_back(make_finding(ver, "proc", "PROC-SWAP-OK-"+ver,
                "PASS: No active swap or mlock in use", "", 0));
        return results;
    }

    // Process family dispatcher
    std::vector<DynamicFinding> engine_proc_family(VersionInstance& inst, const ChainParams& p) {
        ScopedProfile prof("PROC", "proc_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto p1=engine_proc_cmdline(inst,p);  r.insert(r.end(),p1.begin(),p1.end());
        auto p2=engine_proc_environ(inst,p);  r.insert(r.end(),p2.begin(),p2.end());
        auto p3=engine_proc_fds(inst,p);      r.insert(r.end(),p3.begin(),p3.end());
        auto p4=engine_proc_swap(inst,p);     r.insert(r.end(),p4.begin(),p4.end());
        return r;
    }


    // ----------------------------------------------------------------
    // 84.27: KL-WALLET-FORMAT — Wallet Format & Migration Leak (4)
    // ----------------------------------------------------------------

    // 84.27.1: Wallet Format Detection
    std::vector<DynamicFinding> engine_wfmt_detect(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        std::string rd = inst.data_directory + (inst.is_regtest ? "/regtest" : "");
        // Detect wallet format
        std::string format = "unknown";
        bool has_bdb = false, has_sqlite = false;
        try {
            for (auto& wp : {rd + "/wallet.dat", rd + "/wallets/" + inst.wallet_name + "/wallet.dat"}) {
                if (std::filesystem::exists(wp)) {
                    std::ifstream f(wp, std::ios::binary);
                    char magic[16] = {};
                    f.read(magic, 16);
                    if (std::string(magic, 6) == "SQLite") { has_sqlite = true; format = "SQLite"; }
                    else if (magic[0] == 0x00 && magic[1] == 0x06) { has_bdb = true; format = "BDB"; }
                    else { has_bdb = true; format = "BDB(legacy)"; }
                }
            }
        } catch (...) {}
        results.push_back(make_finding(ver, "wfmt", "WFMT-DETECT-"+ver,
            "INFO: Wallet format=" + format + " (BDB=" + std::string(has_bdb?"Y":"N") +
            " SQLite=" + std::string(has_sqlite?"Y":"N") + ")", "", 0));
        return results;
    }

    // 84.27.2: migratewallet Lock Gate
    std::vector<DynamicFinding> engine_wfmt_migrate(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em < 24 || !p.wallet_available) { results.push_back(make_finding(ver, "wfmt", "WFMT-MIG-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        // Test migratewallet while locked (don't actually migrate)
        auto mw = rpc(inst, "migratewallet");
        bool locked_err = mw.is_error() && (mw.output.find("locked") != std::string::npos ||
            mw.output.find("passphrase") != std::string::npos);
        bool accepted = mw.success && !mw.is_error();
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        if (accepted)
            results.push_back(make_finding(ver, "wfmt", "WFMT-MIG-BYPASS-"+ver,
                "HIGH: migratewallet accepted while locked — format change without auth", "", 7));
        else
            results.push_back(make_finding(ver, "wfmt", "WFMT-MIG-BLOCKED-"+ver,
                "PASS: migratewallet " + std::string(locked_err ? "requires unlock" : "rejected"), "", 0));
        return results;
    }

    // 84.27.3: Wallet Version Downgrade Check
    std::vector<DynamicFinding> engine_wfmt_downgrade(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_available) { results.push_back(make_finding(ver, "wfmt", "WFMT-DWN-SKIP", "SKIP", "", 0)); return results; }
        auto wi = rpc(inst, "getwalletinfo");
        std::string wver = jx(wi.output, "walletversion");
        int wallet_version = 0; try { wallet_version = std::stoi(wver); } catch (...) {}
        // Check if wallet version is outdated relative to node
        int em = effective_major(ver);
        bool outdated = false;
        if (em >= 22 && wallet_version < 169900) outdated = true;
        if (em >= 24 && wallet_version < 219900) outdated = true;
        if (outdated)
            results.push_back(make_finding(ver, "wfmt", "WFMT-DWN-OUTDATED-"+ver,
                "LOW: Wallet version " + std::to_string(wallet_version) + " is outdated for node v" +
                ver + " — may lack security features", "", 2));
        else
            results.push_back(make_finding(ver, "wfmt", "WFMT-DWN-OK-"+ver,
                "PASS: wallet_version=" + std::to_string(wallet_version), "", 0));
        return results;
    }

    // 84.27.4: Dual-Format Wallet File Leak
    std::vector<DynamicFinding> engine_wfmt_dual(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        std::string rd = inst.data_directory + (inst.is_regtest ? "/regtest" : "");
        // Check if both BDB and SQLite wallet files exist simultaneously
        bool bdb_exists = false, sqlite_exists = false;
        try {
            for (auto& wp : {rd + "/wallets/" + inst.wallet_name, rd}) {
                if (!std::filesystem::exists(wp)) continue;
                for (auto& e : std::filesystem::directory_iterator(wp)) {
                    std::string fn = e.path().filename().string();
                    if (fn == "wallet.dat") {
                        std::ifstream f(e.path(), std::ios::binary);
                        char hdr[6] = {};
                        f.read(hdr, 6);
                        if (std::string(hdr, 6) == "SQLite") sqlite_exists = true;
                        else bdb_exists = true;
                    }
                    if (fn.find(".sqlite") != std::string::npos) sqlite_exists = true;
                }
            }
        } catch (...) {}
        if (bdb_exists && sqlite_exists)
            results.push_back(make_finding(ver, "wfmt", "WFMT-DUAL-"+ver,
                "MEDIUM: Both BDB and SQLite wallet files present — migration residue may contain plaintext keys", "", 5));
        else
            results.push_back(make_finding(ver, "wfmt", "WFMT-DUAL-NONE-"+ver,
                "PASS: Single format (BDB=" + std::string(bdb_exists?"Y":"N") +
                " SQLite=" + std::string(sqlite_exists?"Y":"N") + ")", "", 0));
        return results;
    }

    // Wallet format family dispatcher
    std::vector<DynamicFinding> engine_wfmt_family(VersionInstance& inst, const ChainParams& p) {
        ScopedProfile prof("WFMT", "wfmt_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto w1=engine_wfmt_detect(inst,p);     r.insert(r.end(),w1.begin(),w1.end());
        auto w2=engine_wfmt_migrate(inst,p);    r.insert(r.end(),w2.begin(),w2.end());
        auto w3=engine_wfmt_downgrade(inst,p);  r.insert(r.end(),w3.begin(),w3.end());
        auto w4=engine_wfmt_dual(inst,p);       r.insert(r.end(),w4.begin(),w4.end());
        return r;
    }

    // ----------------------------------------------------------------
    // 84.28: KL-SOFTFORK-NOVEL — Softfork & Activation Analysis (4)
    // ----------------------------------------------------------------

    // 84.28.1: getdeploymentinfo Lock Gate
    std::vector<DynamicFinding> engine_sf_deployment(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em < 22) { results.push_back(make_finding(ver, "sf", "SF-DEPLOY-SKIP", "SKIP", "", 0)); return results; }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        auto di = rpc(inst, "getdeploymentinfo");
        bool exposed = di.success && !di.is_error();
        int deployments = 0;
        if (exposed) {
            size_t pos = 0;
            while ((pos = di.output.find("\"status\"", pos+1)) != std::string::npos) deployments++;
        }
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        results.push_back(make_finding(ver, "sf", "SF-DEPLOY-"+ver,
            "INFO: getdeploymentinfo accessible while locked (" + std::to_string(deployments) +
            " deployments)", "", 0));
        return results;
    }

    // 84.28.2: getblockchaininfo Softfork Fingerprint
    std::vector<DynamicFinding> engine_sf_bcinfo(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        auto bi = rpc(inst, "getblockchaininfo");
        bool has_softforks = bi.has("\"softforks\"") || bi.has("\"bip9_softforks\"");
        bool has_warnings = bi.has("\"warnings\"");
        std::string chain = jx(bi.output, "chain");
        results.push_back(make_finding(ver, "sf", "SF-BCINFO-"+ver,
            "INFO: chain=" + chain + " softforks=" + std::string(has_softforks?"Y":"N") +
            " warnings=" + std::string(has_warnings?"Y":"N"), "", 0));
        return results;
    }

    // 84.28.3: Taproot Activation Consistency
    std::vector<DynamicFinding> engine_sf_taproot(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em < 22) { results.push_back(make_finding(ver, "sf", "SF-TAP-SKIP", "SKIP", "", 0)); return results; }
        auto bi = rpc(inst, "getblockchaininfo");
        bool taproot_active = bi.has("\"taproot\"") && bi.has("\"active\"");
        // Check if tr() addresses work
        auto na = rpc(inst, "getnewaddress", "\"\" \"bech32m\"");
        bool bech32m_ok = na.success && !na.is_error() && na.output.find("bcrt1p") != std::string::npos;
        if (taproot_active && !bech32m_ok)
            results.push_back(make_finding(ver, "sf", "SF-TAP-INCONSIST-"+ver,
                "LOW: Taproot shows active but bech32m address generation fails", "", 2));
        else
            results.push_back(make_finding(ver, "sf", "SF-TAP-OK-"+ver,
                "PASS: taproot=" + std::string(taproot_active?"active":"inactive") +
                " bech32m=" + std::string(bech32m_ok?"Y":"N"), "", 0));
        return results;
    }

    // 84.28.4: Version Bits Confusion Attack Surface
    std::vector<DynamicFinding> engine_sf_versionbits(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (p.current_height < 1) { results.push_back(make_finding(ver, "sf", "SF-VBITS-SKIP", "SKIP", "", 0)); return results; }
        auto bh = rpc(inst, "getblock", "\"" + p.best_block_hash + "\"");
        std::string version_hex = jx(bh.output, "versionHex");
        int32_t block_version = 0;
        try { block_version = (int32_t)std::stoul(version_hex, nullptr, 16); } catch (...) {}
        // Check for unexpected version bits
        int set_bits = 0;
        for (int b = 0; b < 29; b++) if (block_version & (1 << b)) set_bits++;
        if (set_bits > 3)
            results.push_back(make_finding(ver, "sf", "SF-VBITS-UNUSUAL-"+ver,
                "LOW: Block version has " + std::to_string(set_bits) + " bits set (" +
                version_hex + ") — unusual signaling", "", 2));
        else
            results.push_back(make_finding(ver, "sf", "SF-VBITS-OK-"+ver,
                "PASS: version=" + version_hex, "", 0));
        return results;
    }

    // Softfork family dispatcher
    std::vector<DynamicFinding> engine_sf_family(VersionInstance& inst, const ChainParams& p) {
        ScopedProfile prof("SF", "sf_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto s1=engine_sf_deployment(inst,p);    r.insert(r.end(),s1.begin(),s1.end());
        auto s2=engine_sf_bcinfo(inst,p);        r.insert(r.end(),s2.begin(),s2.end());
        auto s3=engine_sf_taproot(inst,p);       r.insert(r.end(),s3.begin(),s3.end());
        auto s4=engine_sf_versionbits(inst,p);   r.insert(r.end(),s4.begin(),s4.end());
        return r;
    }


    // ----------------------------------------------------------------
    // 84.29: KL-CROSS-WALLET-LEAK — Cross-file Leak Detectors (4)
    // ----------------------------------------------------------------

    // 84.29.1: peers.dat Wallet Address Correlation
    std::vector<DynamicFinding> engine_xwallet_peers(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        std::string rd = inst.data_directory + (inst.is_regtest ? "/regtest" : "");
        std::string peers_path = rd + "/peers.dat";
        struct stat st;
        bool exists = stat(peers_path.c_str(), &st) == 0;
        if (!exists) { results.push_back(make_finding(ver, "xwallet", "XW-PEERS-NONE-"+ver, "SKIP", "", 0)); return results; }
        // Check if peers.dat leaks wallet addresses through encoded data
        std::ifstream f(peers_path, std::ios::binary);
        std::vector<uint8_t> data(std::min((size_t)st.st_size, (size_t)(512*1024)));
        f.read(reinterpret_cast<char*>(data.data()), data.size());
        data.resize((size_t)f.gcount()); f.close();
        // Scan for Bitcoin address patterns in peers data
        auto ks = scan_for_key_material(data);
        if (ks.der_keys > 0 || ks.wif_candidates > 0 || ks.xprv_strings > 0)
            results.push_back(make_finding(ver, "xwallet", "XW-PEERS-LEAK-"+ver,
                "MEDIUM: peers.dat contains key/address material", "", 5));
        else
            results.push_back(make_finding(ver, "xwallet", "XW-PEERS-CLEAN-"+ver,
                "PASS: No key material in peers.dat (" + std::to_string(data.size()/1024) + "KB)", "", 0));
        return results;
    }

    // 84.29.2: banlist.json Wallet Correlation
    std::vector<DynamicFinding> engine_xwallet_banlist(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        std::string rd = inst.data_directory + (inst.is_regtest ? "/regtest" : "");
        // Check both old and new format
        for (auto& bn : {"banlist.json", "banlist.dat"}) {
            std::string bp = rd + "/" + bn;
            struct stat st;
            if (stat(bp.c_str(), &st) == 0 && st.st_size > 0) {
                // World-readable banlist could be used for peer fingerprinting
                bool world_read = st.st_mode & S_IROTH;
                if (world_read)
                    results.push_back(make_finding(ver, "xwallet", "XW-BAN-WORLD-"+ver,
                        "LOW: " + std::string(bn) + " is world-readable", "", 2));
                else
                    results.push_back(make_finding(ver, "xwallet", "XW-BAN-OK-"+ver,
                        "PASS: " + std::string(bn) + " permissions OK", "", 0));
                return results;
            }
        }
        results.push_back(make_finding(ver, "xwallet", "XW-BAN-NONE-"+ver, "INFO: No banlist file", "", 0));
        return results;
    }

    // 84.29.3: fee_estimates.dat Information Leak
    std::vector<DynamicFinding> engine_xwallet_feeest(VersionInstance& inst, const ChainParams& p) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        std::string rd = inst.data_directory + (inst.is_regtest ? "/regtest" : "");
        std::string fee_path = rd + "/fee_estimates.dat";
        struct stat st;
        if (stat(fee_path.c_str(), &st) == 0) {
            bool world_read = st.st_mode & S_IROTH;
            results.push_back(make_finding(ver, "xwallet", "XW-FEEEST-"+ver,
                std::string(world_read ? "LOW" : "INFO") + ": fee_estimates.dat exists (" +
                std::to_string(st.st_size) + "B" + std::string(world_read ? " WORLD-READABLE" : "") + ")",
                "", world_read ? 2 : 0));
        } else {
            results.push_back(make_finding(ver, "xwallet", "XW-FEEEST-NONE-"+ver, "PASS", "", 0));
        }
        return results;
    }

