        run84("LOCKTIME-NOVEL",       [&]() { return engine_locktime_family(inst, params); });
        run84("SIGNING-NOVEL",        [&]() { return engine_signing_family(inst, params); });
        run84("FSPERM-NOVEL",         [&]() { return engine_fsperm_family(inst, params); });
        run84("DEBUGRPC-NOVEL",       [&]() { return engine_debugrpc_family(inst, params); });
