    // ── Per-version RPC info cache (speed optimization) ──────────────
    struct VersionRpcCache {
        RpcResult network_info;
        RpcResult blockchain_info;
        RpcResult wallet_info;
        RpcResult rpcinfo;
        std::string subversion;
        int protocol_version = 0;
        std::string build_date;
        int keypool_size = 0;
        bool has_descriptor_wallet = false;
        bool has_legacy_wallet = false;
        bool has_taproot = false;
        bool has_bip125 = false;
        bool has_segwit = false;
        bool has_psbt = false;
        bool has_package_relay = false;
        int pbkdf2_iterations = 0;
        bool populated = false;
    };

    VersionRpcCache populate_version_cache(VersionInstance& inst, const ChainParams& p) {
        VersionRpcCache c;
        int em = effective_major(inst.version_string);
        c.network_info = rpc_cached(inst, "getnetworkinfo");
        c.blockchain_info = rpc_cached(inst, "getblockchaininfo");
        c.wallet_info = rpc_cached(inst, "getwalletinfo");
        c.rpcinfo = rpc_cached(inst, "getrpcinfo");
        c.subversion = jx(c.network_info.output, "subversion");
        try { c.protocol_version = std::stoi(jx(c.network_info.output, "protocolversion")); } catch (...) {}
        try { c.keypool_size = std::stoi(jx(c.wallet_info.output, "keypoolsize")); } catch (...) {}
        c.has_descriptor_wallet = c.wallet_info.has("\"descriptors\": true") ||
            c.wallet_info.has("\"descriptors\":true");
        c.has_legacy_wallet = !c.has_descriptor_wallet;
        c.has_taproot = em >= 22;
        c.has_bip125 = em >= 19;
        c.has_segwit = em >= 16;
        c.has_psbt = em >= 18;
        c.has_package_relay = em >= 28;
        // Extract PBKDF2 iterations from wallet backup
        if (p.wallet_encrypted) {
            auto wd = read_wallet_backup(inst, "_cache_iter");
            for (size_t i = 0; i + 8 < wd.size(); i++) {
                if (wd[i]=='m'&&wd[i+1]=='k'&&wd[i+2]=='e'&&wd[i+3]=='y') {
                    for (size_t j = i+4; j+4 < wd.size() && j < i+100; j++) {
                        uint32_t val = uint32_t(wd[j]) | (uint32_t(wd[j+1])<<8) |
                            (uint32_t(wd[j+2])<<16) | (uint32_t(wd[j+3])<<24);
                        if (val >= 1000 && val <= 10000000) { c.pbkdf2_iterations = val; break; }
                    }
                    break;
                }
            }
        }
        c.populated = true;
        return c;
    }

    // ── UNIQUENESS-PROBE: inject version fingerprint to break uniformity ──
    DynamicFinding make_uniqueness_probe(VersionInstance& inst, const VersionRpcCache& vc) {
        int em = effective_major(inst.version_string);
        std::string fp = "v=" + inst.version_string +
            " subv=" + vc.subversion +
            " proto=" + std::to_string(vc.protocol_version) +
            " desc=" + std::string(vc.has_descriptor_wallet ? "Y" : "N") +
            " kpool=" + std::to_string(vc.keypool_size) +
            " taproot=" + std::string(vc.has_taproot ? "Y" : "N") +
            " iter=" + std::to_string(vc.pbkdf2_iterations) +
            " em=" + std::to_string(em);
        return make_finding(inst.version_string, "uniformity", "UNIQUENESS-PROBE-" + inst.version_string,
            "VERSION-FINGERPRINT: " + fp, fp, 0);
    }

    // ================================================================
    // 85.1: WALLET-STATE DESYNC ATTACKS (3 engines)
    // ================================================================

    // 85.1.1: WAL-LOCK-STATE-DESYNC — concurrent RPC connection lock bypass
    std::vector<DynamicFinding> engine_desync_lock_state(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc, const std::string& state) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (!p.wallet_encrypted || em < 19) {
            results.push_back(make_finding(ver, "desync", "DESYNC-LOCK-SKIP-"+state, "SKIP", "", 0));
            return results;
        }
        // Unlock wallet, then lock from a concurrent perspective
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 10");
        // Immediately lock
        rpc(inst, "walletlock");
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
        // Race: try key operation immediately after lock
        std::atomic<bool> bypassed{false};
        std::vector<std::thread> racers;
        for (int i = 0; i < 5; i++) {
            racers.emplace_back([&]() {
                std::string addr = p.test_addresses.empty() ? "bcrt1qtest" : p.test_addresses[0];
                auto dp = rpc_fast(inst, "dumpprivkey", "[\"" + addr + "\"]");
                if (dp.success && !dp.is_error() && dp.output.size() > 20 &&
                    dp.output.find("error") == std::string::npos)
                    bypassed.store(true);
            });
        }
        for (auto& t : racers) t.join();
        if (bypassed)
            results.push_back(make_finding(ver, "desync", "DESYNC-LOCK-RACE-"+state+"-"+ver,
                "CRITICAL["+state+"]: Lock-state race: dumpprivkey succeeded after walletlock", "", 10));
        else
            results.push_back(make_finding(ver, "desync", "DESYNC-LOCK-OK-"+state+"-"+ver,
                "PASS["+state+"]: Lock state consistent after concurrent race", "", 0));
        return results;
    }

    // 85.1.2: WAL-MIGRATE-LOCK-BYPASS — migratewallet while locked
    std::vector<DynamicFinding> engine_desync_migrate_bypass(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc, const std::string& state) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em < 24 || !p.wallet_encrypted) {
            results.push_back(make_finding(ver, "desync", "DESYNC-MIG-SKIP-"+state, "SKIP: pre-v24 or unencrypted", "", 0));
            return results;
        }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(300));
        // Create a test wallet to migrate
        std::string test_w = "desync_mig_test_" + ver + "_" + state;
        auto cw = rpc(inst, "createwallet", "\"" + test_w + "\" false false \"test\" false false");
        if (!cw.success || cw.is_error()) {
            results.push_back(make_finding(ver, "desync", "DESYNC-MIG-NOCREATE-"+state, "SKIP: createwallet failed", "", 0));
            rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
            return results;
        }
        // Try migratewallet while locked
        std::string orig_wallet = inst.wallet_name;
        inst.wallet_name = test_w;
        auto mw = rpc(inst, "migratewallet");
        bool migrated = mw.success && !mw.is_error();
        std::string err_msg = jx(mw.output, "message");
        inst.wallet_name = orig_wallet;
        // Cleanup
        rpc(inst, "unloadwallet", "\"" + test_w + "\"");
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        if (migrated)
            results.push_back(make_finding(ver, "desync", "DESYNC-MIG-BYPASS-"+state+"-"+ver,
                "HIGH["+state+"]: migratewallet succeeded while locked — plaintext keys may transfer", "", 8));
        else
            results.push_back(make_finding(ver, "desync", "DESYNC-MIG-BLOCKED-"+state+"-"+ver,
                "PASS["+state+"]: migratewallet blocked: " + err_msg.substr(0, 60), "", 0));
        return results;
    }

    // 85.1.3: WAL-RESTORE-LOCK-BYPASS — restorewallet while locked
    std::vector<DynamicFinding> engine_desync_restore_bypass(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc, const std::string& state) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em < 24 || !p.wallet_available) {
            results.push_back(make_finding(ver, "desync", "DESYNC-REST-SKIP-"+state, "SKIP", "", 0));
            return results;
        }
        // First create a backup while unlocked
        std::string bk_path = inst.data_directory + "/desync_restore_" + ver + "_" + state + ".bak";
        rpc(inst, "backupwallet", "\"" + bk_path + "\"");
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        // Try restorewallet while locked
        std::string rest_name = "desync_restored_" + ver + "_" + state;
        auto rw = rpc(inst, "restorewallet", "\"" + rest_name + "\" \"" + bk_path + "\"");
        bool restored = rw.success && !rw.is_error();
        if (restored) {
            // Check if restored wallet allows key access without passphrase
            std::string orig = inst.wallet_name;
            inst.wallet_name = rest_name;
            std::string addr = p.test_addresses.empty() ? "bcrt1qtest" : p.test_addresses[0];
            auto dp = rpc(inst, "dumpprivkey", "\"" + addr + "\"");
            bool key_accessible = dp.success && !dp.is_error() && dp.output.size() > 20;
            inst.wallet_name = orig;
            rpc(inst, "unloadwallet", "\"" + rest_name + "\"");
            if (key_accessible)
                results.push_back(make_finding(ver, "desync", "DESYNC-REST-KEYBYPASS-"+state+"-"+ver,
                    "CRITICAL["+state+"]: Restored wallet provides key access without passphrase", "", 10));
            else
                results.push_back(make_finding(ver, "desync", "DESYNC-REST-ENC-"+state+"-"+ver,
                    "LOW["+state+"]: restorewallet succeeds while locked but wallet stays encrypted", "", 2));
        } else {
            results.push_back(make_finding(ver, "desync", "DESYNC-REST-BLOCKED-"+state+"-"+ver,
                "PASS["+state+"]: restorewallet blocked while locked", "", 0));
        }
        std::remove(bk_path.c_str());
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        return results;
    }

    // Wallet-State Desync family dispatcher
    std::vector<DynamicFinding> engine_desync_family(VersionInstance& inst, const ChainParams& p, const VersionRpcCache& vc) {
        ScopedProfile prof("DESYNC", "desync_" + inst.version_string);
        return backtest_three_states(inst, p, "DESYNC", [this, &vc](auto& i, auto& p2, const std::string& st) {
            std::vector<DynamicFinding> r;
            auto d1 = engine_desync_lock_state(i, p2, vc, st);     r.insert(r.end(), d1.begin(), d1.end());
            auto d2 = engine_desync_migrate_bypass(i, p2, vc, st);  r.insert(r.end(), d2.begin(), d2.end());
            auto d3 = engine_desync_restore_bypass(i, p2, vc, st);  r.insert(r.end(), d3.begin(), d3.end());
            return r;
        });
    }

