    // 85.7.1: Address type generation test — varies by version
    std::vector<DynamicFinding> engine_vdiff_addrtype(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (!p.wallet_available) {
            results.push_back(make_finding(ver, "vdiff", "VD-ADDR-SKIP", "SKIP", "", 0));
            return results;
        }
        // Try generating each address type — availability changes per version
        struct AddrTest { std::string type; int min_ver; };
        std::vector<AddrTest> addr_tests = {
            {"legacy", 16}, {"p2sh-segwit", 16}, {"bech32", 18}, {"bech32m", 22}
        };
        int generated = 0;
        for (auto& at : addr_tests) {
            if (em < at.min_ver) continue;
            auto r = rpc(inst, "getnewaddress", "\"\" \"" + at.type + "\"");
            if (r.success && !r.is_error()) generated++;
        }
        // Default address type varies by version
        auto def = rpc(inst, "getnewaddress");
        std::string def_addr = def.output;
        while (!def_addr.empty() && (def_addr.back()=='\n'||def_addr.back()=='"')) def_addr.pop_back();
        while (!def_addr.empty() && def_addr.front()=='"') def_addr = def_addr.substr(1);
        std::string def_type = "unknown";
        if (def_addr.find("bcrt1q") == 0) def_type = "bech32";
        else if (def_addr.find("bcrt1p") == 0) def_type = "bech32m";
        else if (def_addr.find("2") == 0) def_type = "p2sh-segwit";
        else if (def_addr.find("m") == 0 || def_addr.find("n") == 0) def_type = "legacy";
        results.push_back(make_finding(ver, "vdiff", "VD-ADDR-"+ver,
            "VERSION-DIFF: " + std::to_string(generated) + " addr types, default=" + def_type +
            " descriptor=" + std::string(vc.has_descriptor_wallet?"Y":"N") + " em=" + std::to_string(em),
            "", 0));
        return results;
    }

    // 85.7.2: Mempool policy detection — varies by version
    std::vector<DynamicFinding> engine_vdiff_mempool_policy(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        auto mi = rpc(inst, "getmempoolinfo");
        std::string maxmempool = jx(mi.output, "maxmempool");
        std::string mempoolminfee = jx(mi.output, "mempoolminfee");
        std::string minrelaytxfee = jx(mi.output, "minrelaytxfee");
        std::string incrementalrelayfee = jx(mi.output, "incrementalrelayfee");
        bool has_fullrbf = mi.has("\"fullrbf\"");
        bool fullrbf = mi.has("\"fullrbf\": true") || mi.has("\"fullrbf\":true");
        results.push_back(make_finding(ver, "vdiff", "VD-MEMPOOL-"+ver,
            "VERSION-DIFF: maxmempool=" + maxmempool + " minfee=" + mempoolminfee +
            " relayfee=" + minrelaytxfee + " incfee=" + incrementalrelayfee +
            " fullrbf=" + std::string(has_fullrbf ? (fullrbf ? "true" : "false") : "N/A") +
            " em=" + std::to_string(em), "", 0));
        return results;
    }

