    // Version-differentiation family dispatcher
    std::vector<DynamicFinding> engine_vdiff_family(VersionInstance& inst, const ChainParams& p, const VersionRpcCache& vc) {
        ScopedProfile prof("VDIFF", "vdiff_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto v1 = engine_vdiff_addrtype(inst, p, vc);        r.insert(r.end(), v1.begin(), v1.end());
        auto v2 = engine_vdiff_mempool_policy(inst, p, vc);  r.insert(r.end(), v2.begin(), v2.end());
        auto v3 = engine_vdiff_services(inst, p, vc);        r.insert(r.end(), v3.begin(), v3.end());
        auto v4 = engine_vdiff_chainparams(inst, p, vc);     r.insert(r.end(), v4.begin(), v4.end());
        auto v5 = engine_vdiff_wallet_caps(inst, p, vc);     r.insert(r.end(), v5.begin(), v5.end());
        return r;
    }

    // ================================================================
    // 85.8: ADVANCED LOCK-BYPASS AND RACE CONDITION ENGINES
    // ================================================================

    // 85.8.1: Concurrent createwallet + encrypt race
    std::vector<DynamicFinding> engine_race_create_encrypt(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em < 19) {
            results.push_back(make_finding(ver, "race", "RACE-CE-SKIP", "SKIP: pre-v19", "", 0));
            return results;
        }
        // Create an unencrypted wallet, then race encrypt + key operations
        std::string test_w = "race_encrypt_" + ver;
        rpc(inst, "createwallet", "\"" + test_w + "\" false false \"\" false false");
        std::string orig = inst.wallet_name;
        inst.wallet_name = test_w;
        // Generate an address before encryption
        auto addr = rpc(inst, "getnewaddress");
        std::string test_addr = addr.output;
        while (!test_addr.empty() && (test_addr.back()=='\n'||test_addr.back()=='"')) test_addr.pop_back();
        while (!test_addr.empty() && test_addr.front()=='"') test_addr = test_addr.substr(1);
        // Race: encrypt wallet while simultaneously trying to dump keys
        std::atomic<bool> key_during_encrypt{false};
        std::thread encryptor([&]() {
            rpc(inst, "encryptwallet", "\"race_test_pass_123\"");
        });
        // Try dumping key during encryption
        for (int i = 0; i < 10; i++) {
            if (!test_addr.empty()) {
                auto dp = rpc_fast(inst, "dumpprivkey", "[\"" + test_addr + "\"]");
                if (dp.success && !dp.is_error() && dp.output.size() > 20)
                    key_during_encrypt.store(true);
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
        encryptor.join();
        inst.wallet_name = orig;
        // Cleanup
        rpc(inst, "unloadwallet", "\"" + test_w + "\"");
        if (key_during_encrypt)
            results.push_back(make_finding(ver, "race", "RACE-CE-BYPASS-"+ver,
                "MEDIUM: Key accessible during encryptwallet race window", "", 5));
        else
            results.push_back(make_finding(ver, "race", "RACE-CE-OK-"+ver,
                "PASS: No race condition during encrypt", "", 0));
        return results;
    }

    // 85.8.2: Wallet unload/load state leak
    std::vector<DynamicFinding> engine_race_unload_state(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em < 19 || !p.wallet_encrypted) {
            results.push_back(make_finding(ver, "race", "RACE-UL-SKIP", "SKIP", "", 0));
            return results;
        }
        // Unlock wallet, then unload and reload — check if lock state persists
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        // Dump a key while unlocked to verify we can
        std::string addr = p.test_addresses.empty() ? "bcrt1qtest" : p.test_addresses[0];
        auto dp_before = rpc(inst, "dumpprivkey", "\"" + addr + "\"");
        bool before_ok = dp_before.success && !dp_before.is_error();
        // Unload and reload
        rpc(inst, "unloadwallet", "\"" + inst.wallet_name + "\"");
        std::this_thread::sleep_for(std::chrono::milliseconds(500));
        rpc(inst, "loadwallet", "\"" + inst.wallet_name + "\"");
        std::this_thread::sleep_for(std::chrono::milliseconds(300));
        // Check if still unlocked
        auto dp_after = rpc(inst, "dumpprivkey", "\"" + addr + "\"");
        bool after_ok = dp_after.success && !dp_after.is_error() && dp_after.output.size() > 20;
        if (before_ok && after_ok)
            results.push_back(make_finding(ver, "race", "RACE-UL-PERSIST-"+ver,
                "HIGH: Wallet remained unlocked through unload/reload cycle", "", 7));
        else
            results.push_back(make_finding(ver, "race", "RACE-UL-RESET-"+ver,
                "PASS: Wallet properly locked after reload (before=" +
                std::string(before_ok?"Y":"N") + " after=" + std::string(after_ok?"Y":"N") + ")", "", 0));
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        return results;
    }

    // 85.8.3: Concurrent walletpassphrase with different timeouts
    std::vector<DynamicFinding> engine_race_timeout_confusion(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_encrypted) {
            results.push_back(make_finding(ver, "race", "RACE-TO-SKIP", "SKIP", "", 0));
            return results;
        }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        // Race: unlock with 1s timeout, then immediately unlock with 600s
        std::atomic<bool> timeout_confused{false};
        std::thread t1([&]() {
            rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 1");
        });
        std::thread t2([&]() {
            rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        });
        t1.join(); t2.join();
        // Wait for the 1s timeout
        std::this_thread::sleep_for(std::chrono::seconds(2));
        // Check if wallet is still unlocked (600s should win)
        std::string addr = p.test_addresses.empty() ? "bcrt1qtest" : p.test_addresses[0];
        auto dp = rpc(inst, "dumpprivkey", "\"" + addr + "\"");
        bool still_unlocked = dp.success && !dp.is_error() && dp.output.size() > 20;
        // Now check with short timeout first
        rpc(inst, "walletlock");
        std::this_thread::sleep_for(std::chrono::milliseconds(200));
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 1");
        std::this_thread::sleep_for(std::chrono::seconds(2));
        auto dp2 = rpc(inst, "dumpprivkey", "\"" + addr + "\"");
        bool short_wins = !(dp2.success && !dp2.is_error());
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        if (!still_unlocked)
            results.push_back(make_finding(ver, "race", "RACE-TO-1SWINS-"+ver,
                "MEDIUM: 1s timeout overrides concurrent 600s unlock — wallet locked unexpectedly", "", 5));
        else if (short_wins)
            results.push_back(make_finding(ver, "race", "RACE-TO-LASTWRITE-"+ver,
                "LOW: Last walletpassphrase call wins (short timeout overrides long)", "", 2));
        else
            results.push_back(make_finding(ver, "race", "RACE-TO-OK-"+ver,
                "PASS: Timeout handling consistent", "", 0));
        return results;
    }

    // Race condition family dispatcher
    std::vector<DynamicFinding> engine_race_family(VersionInstance& inst, const ChainParams& p, const VersionRpcCache& vc) {
        ScopedProfile prof("RACE", "race_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto r1 = engine_race_create_encrypt(inst, p, vc);      r.insert(r.end(), r1.begin(), r1.end());
        auto r2 = engine_race_unload_state(inst, p, vc);        r.insert(r.end(), r2.begin(), r2.end());
        auto r3 = engine_race_timeout_confusion(inst, p, vc);   r.insert(r.end(), r3.begin(), r3.end());
        return r;
    }

    // ================================================================
    // 85.9: ADVANCED OFFLINE KEY LEAKAGE ENGINES
    // ================================================================

    // 85.9.1: Debug.log sensitive RPC argument logging
    std::vector<DynamicFinding> engine_offline_debuglog_args(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        std::string rd = inst.data_directory + (inst.is_regtest ? "/regtest" : "");
        std::string debug_log = rd + "/debug.log";
        std::ifstream dl(debug_log);
        if (!dl.is_open()) {
            results.push_back(make_finding(ver, "offline", "OFF-DLOG-SKIP", "SKIP", "", 0));
            return results;
        }
        int sensitive_args = 0; int passphrase_logged = 0;
        std::string line;
        while (std::getline(dl, line)) {
            if (line.find("walletpassphrase") != std::string::npos &&
                line.find("\"") != std::string::npos) passphrase_logged++;
            if (line.find("importprivkey") != std::string::npos) sensitive_args++;
            if (line.find("dumpprivkey") != std::string::npos) sensitive_args++;
            if (line.find("sethdseed") != std::string::npos) sensitive_args++;
        }
        if (passphrase_logged > 0)
            results.push_back(make_finding(ver, "offline", "OFF-DLOG-PASSPHRASE-"+ver,
                "MEDIUM: " + std::to_string(passphrase_logged) +
                " walletpassphrase calls logged with arguments in debug.log", "", 5));
        else if (sensitive_args > 0)
            results.push_back(make_finding(ver, "offline", "OFF-DLOG-SENSITIVE-"+ver,
                "LOW: " + std::to_string(sensitive_args) + " sensitive RPC commands in debug.log", "", 2));
        else
            results.push_back(make_finding(ver, "offline", "OFF-DLOG-CLEAN-"+ver,
                "PASS: No sensitive RPC arguments in debug.log", "", 0));
        return results;
    }

    // 85.9.2: Wallet file timestamp metadata leak
    std::vector<DynamicFinding> engine_offline_timestamps(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        std::string rd = inst.data_directory + (inst.is_regtest ? "/regtest" : "");
        std::vector<std::string> wallet_paths = {
            rd + "/wallet.dat",
            rd + "/wallets/" + inst.wallet_name + "/wallet.dat",
            rd + "/wallets/" + inst.wallet_name + "/wallet.sqlite"
        };
        for (auto& wp : wallet_paths) {
            struct stat st;
            if (stat(wp.c_str(), &st) == 0) {
                time_t now = time(nullptr);
                time_t age_days = (now - st.st_mtime) / 86400;
                time_t create_age = (now - st.st_ctime) / 86400;
                results.push_back(make_finding(ver, "offline", "OFF-TS-"+ver,
                    "INFO: Wallet file modified " + std::to_string(age_days) +
                    "d ago, created " + std::to_string(create_age) +
                    "d ago, size=" + std::to_string(st.st_size) + "B", "", 0));
                return results;
            }
        }
        results.push_back(make_finding(ver, "offline", "OFF-TS-NOFILE-"+ver, "SKIP", "", 0));
        return results;
    }

    // 85.9.3: Datadir residual files scan
    std::vector<DynamicFinding> engine_offline_residual(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        std::string rd = inst.data_directory + (inst.is_regtest ? "/regtest" : "");
        int residual_files = 0;
        std::vector<std::string> dangerous_patterns = {
            "*.bak", "dump*.txt", "*.old", "*.tmp", "core.*"
        };
        for (auto& pat : dangerous_patterns) {
            std::string cmd = "find '" + rd + "' -maxdepth 2 -name '" + pat + "' 2>/dev/null | wc -l";
            auto r = popen_with_timeout(cmd, 2);
            if (!r.timed_out) {
                try { residual_files += std::stoi(r.output); } catch (...) {}
            }
        }
        if (residual_files > 0)
            results.push_back(make_finding(ver, "offline", "OFF-RESID-"+ver,
                "LOW: " + std::to_string(residual_files) + " residual files in datadir " +
                "(backups, dumps, core files)", "", 2));
        else
            results.push_back(make_finding(ver, "offline", "OFF-RESID-CLEAN-"+ver,
                "PASS: No residual files", "", 0));
        return results;
    }

    // Offline family dispatcher
    std::vector<DynamicFinding> engine_offline_family(VersionInstance& inst, const ChainParams& p, const VersionRpcCache& vc) {
        ScopedProfile prof("OFFLINE", "offline_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto o1 = engine_offline_debuglog_args(inst, p, vc);  r.insert(r.end(), o1.begin(), o1.end());
        auto o2 = engine_offline_timestamps(inst, p, vc);     r.insert(r.end(), o2.begin(), o2.end());
        auto o3 = engine_offline_residual(inst, p, vc);       r.insert(r.end(), o3.begin(), o3.end());
        return r;
    }


    // ================================================================
    // 85.11: MULTI-WALLET ISOLATION ATTACKS
    // ================================================================

    // 85.11.1: Cross-wallet key contamination — check if keys from one wallet
    // appear accessible from another wallet in the same node
    std::vector<DynamicFinding> engine_mwi_key_contamination(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc, const std::string& state) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em < 19 || !p.wallet_available) {
            results.push_back(make_finding(ver, "mwi", "MWI-CONTAM-SKIP-"+state, "SKIP", "", 0));
            return results;
        }
        // Create a second test wallet
        std::string w2 = "mwi_iso_" + ver + "_" + state;
        auto cw = rpc(inst, "createwallet", "\"" + w2 + "\" false false \"\" false false");
        if (!cw.success || cw.is_error()) {
            results.push_back(make_finding(ver, "mwi", "MWI-CONTAM-NOCREATE-"+state, "SKIP", "", 0));
            return results;
        }
        // Generate address in primary wallet
        std::string orig = inst.wallet_name;
        std::string addr1 = rpc_safe(inst, "getnewaddress");
        // Switch to second wallet and check if addr1's key is accessible
        inst.wallet_name = w2;
        auto vi = rpc(inst, "getaddressinfo", "\"" + addr1 + "\"");
        bool is_mine_in_w2 = vi.has("\"ismine\": true") || vi.has("\"ismine\":true");
        // Try dumpprivkey from w2
        auto dp = rpc(inst, "dumpprivkey", "\"" + addr1 + "\"");
        bool key_leaked = dp.success && !dp.is_error() && dp.output.size() > 20 &&
            dp.output.find("error") == std::string::npos;
        inst.wallet_name = orig;
        rpc(inst, "unloadwallet", "\"" + w2 + "\"");
        if (key_leaked)
            results.push_back(make_finding(ver, "mwi", "MWI-CONTAM-KEYLEAK-"+state+"-"+ver,
                "CRITICAL["+state+"]: Private key from wallet '" + orig +
                "' accessible via wallet '" + w2 + "'", "", 10));
        else if (is_mine_in_w2)
            results.push_back(make_finding(ver, "mwi", "MWI-CONTAM-ISMINE-"+state+"-"+ver,
                "HIGH["+state+"]: Address from primary wallet shows ismine=true in isolated wallet", "", 7));
        else
            results.push_back(make_finding(ver, "mwi", "MWI-CONTAM-OK-"+state+"-"+ver,
                "PASS["+state+"]: Wallets properly isolated", "", 0));
        return results;
    }

    // 85.11.2: Multi-wallet RPC routing confusion — test if RPC to one wallet
    // name can be redirected to operate on another
    std::vector<DynamicFinding> engine_mwi_rpc_routing(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc, const std::string& state) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em < 19) {
            results.push_back(make_finding(ver, "mwi", "MWI-ROUTE-SKIP-"+state, "SKIP", "", 0));
            return results;
        }
        // Create wallets with similar names (path traversal probe)
        std::string w_normal = "mwi_normal_" + ver;
        std::string w_tricky = "mwi_normal_" + ver + "/../../mwi_normal_" + ver;
        auto cw1 = rpc(inst, "createwallet", "\"" + w_normal + "\"");
        auto cw2 = rpc(inst, "createwallet", "\"" + w_tricky + "\"");
        bool path_traversal = cw2.success && !cw2.is_error();
        if (path_traversal)
            results.push_back(make_finding(ver, "mwi", "MWI-ROUTE-PATHTRV-"+state+"-"+ver,
                "HIGH["+state+"]: Path traversal wallet name accepted: " + w_tricky, "", 7));
        else
            results.push_back(make_finding(ver, "mwi", "MWI-ROUTE-SAFE-"+state+"-"+ver,
                "PASS["+state+"]: Path traversal wallet name rejected", "", 0));
        // Cleanup
        rpc(inst, "unloadwallet", "\"" + w_normal + "\"");
        if (path_traversal) rpc(inst, "unloadwallet", "\"" + w_tricky + "\"");
        return results;
    }

    // 85.11.3: Multi-wallet lock state bleeding
    std::vector<DynamicFinding> engine_mwi_lock_bleed(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc, const std::string& state) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em < 19 || !p.wallet_encrypted) {
            results.push_back(make_finding(ver, "mwi", "MWI-LOCKBLEED-SKIP-"+state, "SKIP", "", 0));
            return results;
        }
        // Create encrypted second wallet
        std::string w2 = "mwi_lockbleed_" + ver + "_" + state;
        rpc(inst, "createwallet", "\"" + w2 + "\" false false \"\" false false");
        std::string orig = inst.wallet_name;
        inst.wallet_name = w2;
        rpc(inst, "encryptwallet", "\"lockbleed_pass_456\"");
        std::this_thread::sleep_for(std::chrono::seconds(1));
        // Reload after encryption
        rpc(inst, "loadwallet", "\"" + w2 + "\"");
        inst.wallet_name = orig;
        // Unlock primary wallet
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        // Check if w2 is also unlocked
        inst.wallet_name = w2;
        std::string addr2 = rpc_safe(inst, "getnewaddress");
        auto dp = rpc(inst, "dumpprivkey", "\"" + addr2 + "\"");
        bool w2_unlocked = dp.success && !dp.is_error() && dp.output.size() > 20 &&
            dp.output.find("error") == std::string::npos;
        inst.wallet_name = orig;
        rpc(inst, "unloadwallet", "\"" + w2 + "\"");
        if (w2_unlocked)
            results.push_back(make_finding(ver, "mwi", "MWI-LOCKBLEED-YES-"+state+"-"+ver,
                "CRITICAL["+state+"]: Unlocking primary wallet also unlocked separate wallet '" + w2 + "'",
                "", 10));
        else
            results.push_back(make_finding(ver, "mwi", "MWI-LOCKBLEED-NO-"+state+"-"+ver,
                "PASS["+state+"]: Lock states properly isolated between wallets", "", 0));
        return results;
    }

    // 85.11.4: Multi-wallet memory cross-contamination
    std::vector<DynamicFinding> engine_mwi_memory_cross(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc, const std::string& state) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em < 19) {
            results.push_back(make_finding(ver, "mwi", "MWI-MEMX-SKIP-"+state, "SKIP", "", 0));
            return results;
        }
        // Create multiple wallets, generate keys, then scan process memory
        std::string w2 = "mwi_memx_" + ver + "_" + state;
        rpc(inst, "createwallet", "\"" + w2 + "\" false false \"\" false false");
        std::string orig = inst.wallet_name;
        // Generate addresses in both wallets
        std::vector<std::string> w1_addrs, w2_addrs;
        for (int i = 0; i < 3; i++) {
            inst.wallet_name = orig;
            w1_addrs.push_back(rpc_safe(inst, "getnewaddress"));
            inst.wallet_name = w2;
            w2_addrs.push_back(rpc_safe(inst, "getnewaddress"));
        }
        // Unload w2
        inst.wallet_name = orig;
        rpc(inst, "unloadwallet", "\"" + w2 + "\"");
        std::this_thread::sleep_for(std::chrono::milliseconds(300));
        // Scan process memory for w2 addresses (should be cleaned up)
        std::string pid = std::to_string(inst.bitcoind_pid);
        int residual = 0;
        if (inst.bitcoind_pid > 0) {
            for (auto& a : w2_addrs) {
                if (a.empty()) continue;
                std::string cmd = "strings /proc/" + pid + "/environ 2>/dev/null | grep -c '" +
                    a.substr(0, 10) + "' || true";
                // On macOS, use vmmap instead
                #ifdef __APPLE__
                cmd = "vmmap " + pid + " 2>/dev/null | head -1 || true";
                auto r = vmmap_run(cmd, 1);
                #else
                auto r = popen_with_timeout(cmd, 1);
                #endif
                if (!r.timed_out) {
                    int cnt = 0; try { cnt = std::stoi(r.output); } catch (...) {}
                    residual += cnt;
                }
            }
        }
        if (residual > 0)
            results.push_back(make_finding(ver, "mwi", "MWI-MEMX-RESID-"+state+"-"+ver,
                "MEDIUM["+state+"]: " + std::to_string(residual) +
                " address patterns from unloaded wallet remain in process memory", "", 4));
        else
            results.push_back(make_finding(ver, "mwi", "MWI-MEMX-CLEAN-"+state+"-"+ver,
                "PASS["+state+"]: Unloaded wallet data cleared from memory", "", 0));
        return results;
    }

    // Multi-wallet isolation family dispatcher
    std::vector<DynamicFinding> engine_mwi_family(VersionInstance& inst, const ChainParams& p, const VersionRpcCache& vc) {
        ScopedProfile prof("MWI", "mwi_" + inst.version_string);
        return backtest_three_states(inst, p, "MWI", [this, &vc](auto& i, auto& p2, const std::string& st) {
            std::vector<DynamicFinding> r;
            auto m1 = engine_mwi_key_contamination(i, p2, vc, st); r.insert(r.end(), m1.begin(), m1.end());
            auto m2 = engine_mwi_rpc_routing(i, p2, vc, st);      r.insert(r.end(), m2.begin(), m2.end());
            auto m3 = engine_mwi_lock_bleed(i, p2, vc, st);       r.insert(r.end(), m3.begin(), m3.end());
            auto m4 = engine_mwi_memory_cross(i, p2, vc, st);     r.insert(r.end(), m4.begin(), m4.end());
            return r;
        });
    }

    // ================================================================
    // 85.12: TRANSACTION CONSTRUCTION ATTACKS
    // ================================================================

    // 85.12.1: TX-MALLEABLE-SIG — check if the node produces malleable signatures
    std::vector<DynamicFinding> engine_txmal_malleable_sig(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (!p.wallet_available || p.utxos.empty()) {
            results.push_back(make_finding(ver, "txmal", "TXMAL-SIG-SKIP", "SKIP", "", 0));
            return results;
        }
        // Create and sign same transaction twice, compare signatures
        std::string addr = rpc_safe(inst, "getnewaddress");
        if (addr.empty() || p.utxos.empty()) {
            results.push_back(make_finding(ver, "txmal", "TXMAL-SIG-NOADDR", "SKIP", "", 0));
            return results;
        }
        auto raw = rpc(inst, "createrawtransaction",
            "'[{\"txid\":\"" + p.utxos[0].txid + "\",\"vout\":" +
            std::to_string(p.utxos[0].vout) + "}]' '[{\"" + addr + "\":49.999}]'");
        if (!raw.success || raw.is_error()) {
            results.push_back(make_finding(ver, "txmal", "TXMAL-SIG-NOCREATE", "SKIP", "", 0));
            return results;
        }
        std::string raw_hex = raw.output;
        while (!raw_hex.empty() && (raw_hex.back()=='\n'||raw_hex.back()=='"')) raw_hex.pop_back();
        while (!raw_hex.empty() && raw_hex.front()=='"') raw_hex = raw_hex.substr(1);
        // Sign twice
        std::string sign_cmd = (em >= 18) ? "signrawtransactionwithwallet" : "signrawtransaction";
        auto sig1 = rpc(inst, sign_cmd, "\"" + raw_hex + "\"");
        auto sig2 = rpc(inst, sign_cmd, "\"" + raw_hex + "\"");
        std::string hex1 = jx(sig1.output, "hex");
        std::string hex2 = jx(sig2.output, "hex");
        bool deterministic = (hex1 == hex2) && !hex1.empty();
        // Check for low-S (BIP-62/BIP-66)
        bool complete1 = sig1.has("\"complete\": true") || sig1.has("\"complete\":true");
        if (!deterministic && !hex1.empty() && !hex2.empty())
            results.push_back(make_finding(ver, "txmal", "TXMAL-SIG-NONDET-"+ver,
                "HIGH: Non-deterministic signatures — transaction malleability risk. " +
                std::string("sig1_len=") + std::to_string(hex1.size()) +
                " sig2_len=" + std::to_string(hex2.size()), "", 7));
        else if (deterministic)
            results.push_back(make_finding(ver, "txmal", "TXMAL-SIG-DET-"+ver,
                "PASS: Deterministic (RFC6979) signatures confirmed, complete=" +
                std::string(complete1?"Y":"N"), "", 0));
        else
            results.push_back(make_finding(ver, "txmal", "TXMAL-SIG-NOSIGN-"+ver,
                "INFO: Could not sign transaction for malleability test", "", 0));
        return results;
    }

    // 85.12.2: TX-CHANGE-ADDR-LEAK — check if change address type reveals version
    std::vector<DynamicFinding> engine_txmal_change_leak(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (!p.wallet_available) {
            results.push_back(make_finding(ver, "txmal", "TXMAL-CHANGE-SKIP", "SKIP", "", 0));
            return results;
        }
        // Get raw change address to check type
        auto rca = rpc(inst, "getrawchangeaddress");
        std::string change = rca.output;
        while (!change.empty() && (change.back()=='\n'||change.back()=='"')) change.pop_back();
        while (!change.empty() && change.front()=='"') change = change.substr(1);
        std::string change_type = "unknown";
        if (change.find("bcrt1q") == 0) change_type = "bech32";
        else if (change.find("bcrt1p") == 0) change_type = "bech32m";
        else if (change.find("2") == 0) change_type = "p2sh-segwit";
        else if (change.find("m") == 0 || change.find("n") == 0) change_type = "legacy";
        // Compare with default address type
        auto ra = rpc(inst, "getnewaddress");
        std::string recv = ra.output;
        while (!recv.empty() && (recv.back()=='\n'||recv.back()=='"')) recv.pop_back();
        while (!recv.empty() && recv.front()=='"') recv = recv.substr(1);
        std::string recv_type = "unknown";
        if (recv.find("bcrt1q") == 0) recv_type = "bech32";
        else if (recv.find("bcrt1p") == 0) recv_type = "bech32m";
        else if (recv.find("2") == 0) recv_type = "p2sh-segwit";
        else if (recv.find("m") == 0 || recv.find("n") == 0) recv_type = "legacy";
        bool type_mismatch = (change_type != recv_type);
        results.push_back(make_finding(ver, "txmal", "TXMAL-CHANGE-"+ver,
            "VERSION-DIFF: change=" + change_type + " receive=" + recv_type +
            " mismatch=" + std::string(type_mismatch?"Y":"N") +
            " descriptor=" + std::string(vc.has_descriptor_wallet?"Y":"N") + " em=" + std::to_string(em),
            "", type_mismatch ? 2 : 0));
        return results;
    }

    // 85.12.3: TX-LOCKTIME-FINGERPRINT — check default nLockTime behaviour
    std::vector<DynamicFinding> engine_txmal_locktime(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (!p.wallet_available || p.utxos.empty()) {
            results.push_back(make_finding(ver, "txmal", "TXMAL-LT-SKIP", "SKIP", "", 0));
            return results;
        }
        // Create a transaction and check its nLockTime
        std::string addr = rpc_safe(inst, "getnewaddress");
        if (addr.empty()) {
            results.push_back(make_finding(ver, "txmal", "TXMAL-LT-NOADDR", "SKIP", "", 0));
            return results;
        }
        // Use fundrawtransaction to see default locktime
        auto raw = rpc(inst, "createrawtransaction",
            "'[{\"txid\":\"" + p.utxos[0].txid + "\",\"vout\":" +
            std::to_string(p.utxos[0].vout) + "}]' '[{\"" + addr + "\":49.999}]'");
        if (!raw.success || raw.is_error()) {
            results.push_back(make_finding(ver, "txmal", "TXMAL-LT-NOCREATE", "SKIP", "", 0));
            return results;
        }
        std::string raw_hex = raw.output;
        while (!raw_hex.empty() && (raw_hex.back()=='\n'||raw_hex.back()=='"')) raw_hex.pop_back();
        while (!raw_hex.empty() && raw_hex.front()=='"') raw_hex = raw_hex.substr(1);
        auto decoded = rpc(inst, "decoderawtransaction", "\"" + raw_hex + "\"");
        std::string locktime = jx(decoded.output, "locktime");
        // Fund a transaction (this will set nLockTime to current height)
        auto funded = rpc(inst, "fundrawtransaction", "\"" + raw_hex + "\"");
        std::string funded_hex = jx(funded.output, "hex");
        auto funded_decoded = rpc(inst, "decoderawtransaction", "\"" + funded_hex + "\"");
        std::string funded_locktime = jx(funded_decoded.output, "locktime");
        // Anti-fee-sniping: v0.11+ should set locktime = current_height
        bool anti_feesnipe = false;
        int64_t lt = 0; try { lt = std::stoll(funded_locktime); } catch (...) {}
        if (lt > 0 && lt <= p.current_height + 1 && lt >= p.current_height - 2)
            anti_feesnipe = true;
        results.push_back(make_finding(ver, "txmal", "TXMAL-LT-"+ver,
            "VERSION-DIFF: raw_locktime=" + locktime + " funded_locktime=" + funded_locktime +
            " anti_feesnipe=" + std::string(anti_feesnipe?"Y":"N") +
            " height=" + std::to_string(p.current_height) + " em=" + std::to_string(em),
            "", anti_feesnipe ? 0 : 3));
        return results;
    }

    // 85.12.4: TX-RBFOPT-FINGERPRINT — check default RBF opt-in policy
    std::vector<DynamicFinding> engine_txmal_rbf(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (!p.wallet_available || p.utxos.empty()) {
            results.push_back(make_finding(ver, "txmal", "TXMAL-RBF-SKIP", "SKIP", "", 0));
            return results;
        }
        // Check if wallet defaults to RBF opt-in
        auto wi = rpc_cached(inst, "getwalletinfo");
        // Create tx and check sequence numbers
        std::string addr = rpc_safe(inst, "getnewaddress");
        if (addr.empty()) {
            results.push_back(make_finding(ver, "txmal", "TXMAL-RBF-NOADDR", "SKIP", "", 0));
            return results;
        }
        auto raw = rpc(inst, "createrawtransaction",
            "'[{\"txid\":\"" + p.utxos[0].txid + "\",\"vout\":" +
            std::to_string(p.utxos[0].vout) + "}]' '[{\"" + addr + "\":49.999}]'");
        std::string raw_hex = raw.output;
        while (!raw_hex.empty() && (raw_hex.back()=='\n'||raw_hex.back()=='"')) raw_hex.pop_back();
        while (!raw_hex.empty() && raw_hex.front()=='"') raw_hex = raw_hex.substr(1);
        auto funded = rpc(inst, "fundrawtransaction", "\"" + raw_hex + "\"");
        std::string funded_hex = jx(funded.output, "hex");
        auto decoded = rpc(inst, "decoderawtransaction", "\"" + funded_hex + "\"");
        // Check vin[0].sequence for RBF signal (0xfffffffd = BIP125 opt-in)
        bool has_rbf_signal = decoded.has("4294967293") || decoded.has("0xfffffffd");
        // Version-specific: v0.14+ default to opt-in RBF, v24+ default to fullrbf
        std::string expected_rbf = "none";
        if (em >= 24) expected_rbf = "fullrbf";
        else if (em >= 14) expected_rbf = "optin";
        results.push_back(make_finding(ver, "txmal", "TXMAL-RBF-"+ver,
            "VERSION-DIFF: rbf_signal=" + std::string(has_rbf_signal?"Y":"N") +
            " expected=" + expected_rbf + " em=" + std::to_string(em), "", 0));
        return results;
    }

    // Transaction construction family dispatcher
    std::vector<DynamicFinding> engine_txmal_family(VersionInstance& inst, const ChainParams& p, const VersionRpcCache& vc) {
        ScopedProfile prof("TXMAL", "txmal_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto t1 = engine_txmal_malleable_sig(inst, p, vc);  r.insert(r.end(), t1.begin(), t1.end());
        auto t2 = engine_txmal_change_leak(inst, p, vc);    r.insert(r.end(), t2.begin(), t2.end());
        auto t3 = engine_txmal_locktime(inst, p, vc);       r.insert(r.end(), t3.begin(), t3.end());
        auto t4 = engine_txmal_rbf(inst, p, vc);            r.insert(r.end(), t4.begin(), t4.end());
        return r;
    }

    // ================================================================
    // 85.13: PEER & NETWORK FINGERPRINTING ENGINES
    // ================================================================

    // 85.13.1: NET-HANDSHAKE-LEAK — version handshake information disclosure
    std::vector<DynamicFinding> engine_net_handshake(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        auto ni = rpc_cached(inst, "getnetworkinfo");
        // Check what the node reveals to peers
        std::string subversion = jx(ni.output, "subversion");
        bool reveals_version = subversion.find("Satoshi:") != std::string::npos;
        std::string relay_fee = jx(ni.output, "relayfee");
        std::string local_addrs = jx(ni.output, "localaddresses");
        int proto = vc.protocol_version;
        // Check BIP324 support (v26+)
        bool has_bip324 = ni.has("\"v2transport\"") || em >= 26;
        results.push_back(make_finding(ver, "netfp", "NET-HANDSHAKE-"+ver,
            "VERSION-DIFF: subversion=" + subversion + " reveals_ver=" +
            std::string(reveals_version?"Y":"N") + " proto=" + std::to_string(proto) +
            " bip324=" + std::string(has_bip324?"Y":"N") + " relay_fee=" + relay_fee +
            " em=" + std::to_string(em), "", reveals_version ? 2 : 0));
        return results;
    }

    // 85.13.2: NET-ADDR-RELAY — address relay policy fingerprint
    std::vector<DynamicFinding> engine_net_addr_relay(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        // Check for version-specific address manager features
        // ADDRv2 (BIP155) in v22+, anchor connections in v19+
        auto ni = rpc_cached(inst, "getnetworkinfo");
        bool has_addrv2 = em >= 22;
        bool has_tor_v3 = ni.has("\"onion\"") || em >= 21;
        bool has_i2p = ni.has("\"i2p\"") || em >= 23;
        bool has_cjdns = ni.has("\"cjdns\"") || em >= 24;
        // Get peer count and check for diversity
        auto peers = rpc(inst, "getpeerinfo");
        int peer_count = 0;
        size_t pos = 0;
        while ((pos = peers.output.find("\"id\"", pos+1)) != std::string::npos) peer_count++;
        results.push_back(make_finding(ver, "netfp", "NET-ADDRRELAY-"+ver,
            "VERSION-DIFF: addrv2=" + std::string(has_addrv2?"Y":"N") +
            " torv3=" + std::string(has_tor_v3?"Y":"N") +
            " i2p=" + std::string(has_i2p?"Y":"N") +
            " cjdns=" + std::string(has_cjdns?"Y":"N") +
            " peers=" + std::to_string(peer_count) + " em=" + std::to_string(em), "", 0));
        return results;
    }

    // 85.13.3: NET-BLOCKRELAY-POLICY — compact blocks + blocksonly fingerprint
    std::vector<DynamicFinding> engine_net_blockrelay(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        auto ni = rpc_cached(inst, "getnetworkinfo");
        // Compact blocks (BIP152) in v0.13.0+
        bool has_sendcmpct = em >= 13;
        // Check getblockchaininfo for version bits
        auto bci = rpc_cached(inst, "getblockchaininfo");
        std::string initial_block_download = jx(bci.output, "initialblockdownload");
        std::string versionbits = jx(bci.output, "versionbits_computed");
        // Headers-first sync (always since 0.10, but verify)
        bool has_headers = em >= 10;
        results.push_back(make_finding(ver, "netfp", "NET-BLOCKRELAY-"+ver,
            "VERSION-DIFF: compact_blocks=" + std::string(has_sendcmpct?"Y":"N") +
            " headers_first=" + std::string(has_headers?"Y":"N") +
            " ibd=" + initial_block_download + " em=" + std::to_string(em), "", 0));
        return results;
    }

    // Network fingerprint family dispatcher
    std::vector<DynamicFinding> engine_netfp_family(VersionInstance& inst, const ChainParams& p, const VersionRpcCache& vc) {
        ScopedProfile prof("NETFP", "netfp_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto n1 = engine_net_handshake(inst, p, vc);    r.insert(r.end(), n1.begin(), n1.end());
        auto n2 = engine_net_addr_relay(inst, p, vc);   r.insert(r.end(), n2.begin(), n2.end());
        auto n3 = engine_net_blockrelay(inst, p, vc);   r.insert(r.end(), n3.begin(), n3.end());
        return r;
    }

    // ================================================================
    // 85.14: DESCRIPTOR WALLET SECURITY ENGINES (v21+)
    // ================================================================

    // 85.14.1: DESC-RANGED-DERIVATION — check for key derivation outside range
    std::vector<DynamicFinding> engine_desc_range(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (!vc.has_descriptor_wallet || em < 21) {
            results.push_back(make_finding(ver, "descwal", "DESC-RANGE-SKIP", "SKIP", "", 0));
            return results;
        }
        // List descriptors and check range
        auto ld = rpc(inst, "listdescriptors");
        if (!ld.success || ld.is_error()) {
            results.push_back(make_finding(ver, "descwal", "DESC-RANGE-NOLIST", "SKIP", "", 0));
            return results;
        }
        // Count descriptors and extract ranges
        int desc_count = 0; int range_max = 0;
        size_t pos = 0;
        while ((pos = ld.output.find("\"desc\"", pos+1)) != std::string::npos) desc_count++;
        // Extract largest range
        pos = 0;
        while ((pos = ld.output.find("\"range\"", pos+1)) != std::string::npos) {
            size_t bracket = ld.output.find("[", pos);
            size_t comma = ld.output.find(",", bracket);
            size_t close = ld.output.find("]", comma);
            if (bracket != std::string::npos && comma != std::string::npos && close != std::string::npos) {
                try {
                    int end = std::stoi(ld.output.substr(comma+1, close-comma-1));
                    if (end > range_max) range_max = end;
                } catch (...) {}
            }
        }
        results.push_back(make_finding(ver, "descwal", "DESC-RANGE-"+ver,
            "VERSION-DIFF: descriptors=" + std::to_string(desc_count) +
            " max_range=" + std::to_string(range_max) +
            " keypool=" + std::to_string(vc.keypool_size) + " em=" + std::to_string(em),
            "", range_max > 10000 ? 2 : 0));
        return results;
    }

    // 85.14.2: DESC-PRIVATE-EXPORT — check if private descriptors can be exported while locked
    std::vector<DynamicFinding> engine_desc_private_export(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (!vc.has_descriptor_wallet || em < 21) {
            results.push_back(make_finding(ver, "descwal", "DESC-PRIV-SKIP", "SKIP", "", 0));
            return results;
        }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        // Try to export private descriptors while locked
        auto ld_priv = rpc(inst, "listdescriptors", "true");
        bool priv_exported = ld_priv.success && !ld_priv.is_error() && ld_priv.has("\"xprv\"");
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        if (priv_exported)
            results.push_back(make_finding(ver, "descwal", "DESC-PRIV-BYPASS-"+ver,
                "CRITICAL: listdescriptors(true) returns private keys while wallet locked", "", 9));
        else
            results.push_back(make_finding(ver, "descwal", "DESC-PRIV-BLOCKED-"+ver,
                "PASS: Private descriptor export blocked while locked", "", 0));
        return results;
    }

    // 85.14.3: DESC-IMPORT-PERSISTENCE — check if imported descriptors survive encrypt
    std::vector<DynamicFinding> engine_desc_import_persist(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (!vc.has_descriptor_wallet || em < 21) {
            results.push_back(make_finding(ver, "descwal", "DESC-IMP-SKIP", "SKIP", "", 0));
            return results;
        }
        // Get current descriptor count
        auto ld_before = rpc(inst, "listdescriptors");
        int count_before = 0;
        size_t pos = 0;
        while ((pos = ld_before.output.find("\"desc\"", pos+1)) != std::string::npos) count_before++;
        // Try importing a test descriptor
        std::string test_desc = "wpkh(tprv8ZgxMBicQKsPdDArR4xSAECuVxeX1jwCU84TAKqFEhK"
            "ot73x5JnJ1ELm5sLfDAEa1p3qA1RF1yqvGwLXAih2G39QLBVE1dUxd5gLqcv"
            "B8bfK/84h/1h/0h/0/*)#jrsjnrfy";
        auto imp = rpc(inst, "importdescriptors",
            "'[{\"desc\":\"" + test_desc + "\",\"timestamp\":\"now\",\"range\":[0,10]}]'");
        bool imported = imp.success && !imp.is_error();
        auto ld_after = rpc(inst, "listdescriptors");
        int count_after = 0; pos = 0;
        while ((pos = ld_after.output.find("\"desc\"", pos+1)) != std::string::npos) count_after++;
        results.push_back(make_finding(ver, "descwal", "DESC-IMP-"+ver,
            "VERSION-DIFF: before=" + std::to_string(count_before) +
            " after=" + std::to_string(count_after) +
            " imported=" + std::string(imported?"Y":"N") + " em=" + std::to_string(em),
            "", 0));
        return results;
    }

    // Descriptor wallet family dispatcher
    std::vector<DynamicFinding> engine_descwal_family(VersionInstance& inst, const ChainParams& p, const VersionRpcCache& vc) {
        ScopedProfile prof("DESCWAL", "descwal_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto d1 = engine_desc_range(inst, p, vc);           r.insert(r.end(), d1.begin(), d1.end());
        auto d2 = engine_desc_private_export(inst, p, vc);  r.insert(r.end(), d2.begin(), d2.end());
        auto d3 = engine_desc_import_persist(inst, p, vc);  r.insert(r.end(), d3.begin(), d3.end());
        return r;
    }

    // ================================================================
    // 85.15: SIGNING ORACLE & PSBT SECURITY ENGINES
    // ================================================================

    // 85.15.1: PSBT-UTXO-PROOF — check PSBT UTXO proof validation
    std::vector<DynamicFinding> engine_psbt_utxo_proof(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em < 18 || p.utxos.empty()) {
            results.push_back(make_finding(ver, "psbt2", "PSBT2-UTXO-SKIP", "SKIP", "", 0));
            return results;
        }
        // Create a PSBT with witness UTXO only (non-witness gets non_witness_utxo)
        std::string addr = rpc_safe(inst, "getnewaddress");
        if (addr.empty()) {
            results.push_back(make_finding(ver, "psbt2", "PSBT2-UTXO-NOADDR", "SKIP", "", 0));
            return results;
        }
        auto psbt = rpc(inst, "walletcreatefundedpsbt",
            "'[{\"txid\":\"" + p.utxos[0].txid + "\",\"vout\":" +
            std::to_string(p.utxos[0].vout) + "}]' '[{\"" + addr + "\":0.001}]'");
        if (!psbt.success || psbt.is_error()) {
            results.push_back(make_finding(ver, "psbt2", "PSBT2-UTXO-NOCREATE", "SKIP", "", 0));
            return results;
        }
        std::string psbt_str = jx(psbt.output, "psbt");
        // Decode and check UTXO proof type
        auto decoded = rpc(inst, "decodepsbt", "\"" + psbt_str + "\"");
        bool has_witness_utxo = decoded.has("\"witness_utxo\"");
        bool has_non_witness_utxo = decoded.has("\"non_witness_utxo\"");
        // Try to sign
        auto signed_psbt = rpc(inst, "walletprocesspsbt", "\"" + psbt_str + "\"");
        bool signed_ok = signed_psbt.has("\"complete\": true") || signed_psbt.has("\"complete\":true");
        results.push_back(make_finding(ver, "psbt2", "PSBT2-UTXO-"+ver,
            "VERSION-DIFF: witness_utxo=" + std::string(has_witness_utxo?"Y":"N") +
            " non_witness_utxo=" + std::string(has_non_witness_utxo?"Y":"N") +
            " signed=" + std::string(signed_ok?"Y":"N") + " em=" + std::to_string(em),
            "", 0));
        return results;
    }

    // 85.15.2: PSBT-GLOBAL-XPUB — check if PSBT reveals global xpubs
    std::vector<DynamicFinding> engine_psbt_global_xpub(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (em < 18 || p.utxos.empty()) {
            results.push_back(make_finding(ver, "psbt2", "PSBT2-XPUB-SKIP", "SKIP", "", 0));
            return results;
        }
        std::string addr = rpc_safe(inst, "getnewaddress");
        auto psbt = rpc(inst, "walletcreatefundedpsbt",
            "'[]' '[{\"" + addr + "\":0.001}]'");
        std::string psbt_str = jx(psbt.output, "psbt");
        if (psbt_str.empty()) {
            results.push_back(make_finding(ver, "psbt2", "PSBT2-XPUB-NOPSBT", "SKIP", "", 0));
            return results;
        }
        auto decoded = rpc(inst, "decodepsbt", "\"" + psbt_str + "\"");
        bool has_global_xpub = decoded.has("\"xpub\"") || decoded.has("\"global_xpubs\"");
        bool has_bip32_derivs = decoded.has("\"bip32_derivs\"");
        results.push_back(make_finding(ver, "psbt2", "PSBT2-XPUB-"+ver,
            "VERSION-DIFF: global_xpub=" + std::string(has_global_xpub?"Y":"N") +
            " bip32_derivs=" + std::string(has_bip32_derivs?"Y":"N") + " em=" + std::to_string(em),
            "", has_global_xpub ? 3 : 0));
        return results;
    }

    // 85.15.3: SIGN-EXTERNAL-SIGNER — probe external signer support
    std::vector<DynamicFinding> engine_psbt_external_signer(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        // External signer support added in v0.21
        bool has_external = em >= 21;
        auto es = rpc(inst, "enumeratesigners");
        bool enum_available = es.success && !es.is_error();
        bool enum_rpc_exists = es.output.find("not found") == std::string::npos;
        results.push_back(make_finding(ver, "psbt2", "PSBT2-EXTSIGN-"+ver,
            "VERSION-DIFF: external_signer=" + std::string(has_external?"expected":"N/A") +
            " enumerate_rpc=" + std::string(enum_rpc_exists?"Y":"N") +
            " enumerate_ok=" + std::string(enum_available?"Y":"N") + " em=" + std::to_string(em),
            "", 0));
        return results;
    }

    // PSBT/signing family dispatcher
    std::vector<DynamicFinding> engine_psbt2_family(VersionInstance& inst, const ChainParams& p, const VersionRpcCache& vc) {
        ScopedProfile prof("PSBT2", "psbt2_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto p1 = engine_psbt_utxo_proof(inst, p, vc);        r.insert(r.end(), p1.begin(), p1.end());
        auto p2 = engine_psbt_global_xpub(inst, p, vc);       r.insert(r.end(), p2.begin(), p2.end());
        auto p3 = engine_psbt_external_signer(inst, p, vc);   r.insert(r.end(), p3.begin(), p3.end());
        return r;
    }

    // ================================================================
    // 85.16: RPC AUTH & ACCESS CONTROL ENGINES
    // ================================================================

    // 85.16.1: RPC-HIDDEN-COMMANDS — probe for undocumented/hidden RPCs
    std::vector<DynamicFinding> engine_rpcauth_hidden(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        // Test for debug/hidden RPCs that shouldn't be available in production
        std::vector<std::pair<std::string,int>> hidden_rpcs = {
            {"mockscheduler", 19}, {"setmocktime", 16}, {"invalidateblock", 16},
            {"reconsiderblock", 16}, {"generatetodescriptor", 21},
            {"waitforblock", 16}, {"waitfornewblock", 16},
        };
        int hidden_available = 0;
        for (auto& [cmd, min_ver] : hidden_rpcs) {
            if (em < min_ver) continue;
            auto r = rpc(inst, cmd);
            bool exists = r.output.find("not found") == std::string::npos &&
                r.output.find("unknown") == std::string::npos;
            if (exists) hidden_available++;
        }
        results.push_back(make_finding(ver, "rpcauth", "RPCAUTH-HIDDEN-"+ver,
            "VERSION-DIFF: " + std::to_string(hidden_available) + " debug/testing RPCs available in " +
            (inst.is_regtest ? "regtest" : "mainnet") + " mode, em=" + std::to_string(em),
            "", (!inst.is_regtest && hidden_available > 3) ? 4 : 0));
        return results;
    }

    // 85.16.2: RPC-DEPRECATION-MAP — map deprecated RPCs per version
    std::vector<DynamicFinding> engine_rpcauth_deprecated(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        // Check deprecated RPCs
        std::vector<std::pair<std::string,int>> deprecated_rpcs = {
            {"getinfo", 16}, {"signrawtransaction", 18},
            {"getaccount", 18}, {"getaccountaddress", 18},
            {"generate", 19}, {"getpeerinfo", 16},
        };
        int deprecated_available = 0;
        for (auto& [cmd, depr_ver] : deprecated_rpcs) {
            if (em >= depr_ver) continue; // Skip if past deprecation
            auto r = rpc(inst, cmd);
            bool exists = r.output.find("not found") == std::string::npos;
            if (exists) deprecated_available++;
        }
        // Also check -deprecatedrpc flags
        auto help = rpc_cached(inst, "help");
        int total_rpcs = 0;
        std::istringstream iss(help.output); std::string line;
        while (std::getline(iss, line)) {
            if (!line.empty() && line[0] != '=' && line[0] != ' ') total_rpcs++;
        }
        results.push_back(make_finding(ver, "rpcauth", "RPCAUTH-DEPR-"+ver,
            "VERSION-DIFF: " + std::to_string(deprecated_available) + " deprecated RPCs still available, " +
            std::to_string(total_rpcs) + " total RPCs, em=" + std::to_string(em), "", 0));
        return results;
    }

    // 85.16.3: RPC-BATCH-AMPLIFICATION — test for RPC batch request abuse
    std::vector<DynamicFinding> engine_rpcauth_batch(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        // Test batch RPC with many operations — check if resource limits exist
        // Construct a batch of 100 getblockcount calls
        std::string batch = "[";
        for (int i = 0; i < 100; i++) {
            if (i > 0) batch += ",";
            batch += "{\"jsonrpc\":\"1.0\",\"id\":" + std::to_string(i) +
                ",\"method\":\"getblockcount\",\"params\":[]}";
        }
        batch += "]";
        // Execute via curl (RPC batch)
        std::string port = std::to_string(inst.rpc_port);
        std::string curl_cmd = "curl -s --max-time 5 -u __cookie__:$(cat '" + inst.data_directory +
            (inst.is_regtest ? "/regtest" : "") + "/.cookie' 2>/dev/null | cut -d: -f2) "
            "http://127.0.0.1:" + port + "/ -H 'Content-Type:application/json' -d '" + batch + "'";
        auto start = std::chrono::steady_clock::now();
        auto br = popen_with_timeout(curl_cmd, 5);
        auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::steady_clock::now() - start).count();
        bool batch_worked = !br.timed_out && br.output.size() > 100;
        int response_count = 0;
        size_t pos = 0;
        while ((pos = br.output.find("\"result\"", pos+1)) != std::string::npos) response_count++;
        results.push_back(make_finding(ver, "rpcauth", "RPCAUTH-BATCH-"+ver,
            "VERSION-DIFF: batch_100=" + std::string(batch_worked?"Y":"N") +
            " responses=" + std::to_string(response_count) +
            " elapsed=" + std::to_string(elapsed) + "ms em=" + std::to_string(em),
            "", (batch_worked && elapsed < 500) ? 1 : 0));
        return results;
    }

    // RPC auth family dispatcher
    std::vector<DynamicFinding> engine_rpcauth_family(VersionInstance& inst, const ChainParams& p, const VersionRpcCache& vc) {
        ScopedProfile prof("RPCAUTH", "rpcauth_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto a1 = engine_rpcauth_hidden(inst, p, vc);      r.insert(r.end(), a1.begin(), a1.end());
        auto a2 = engine_rpcauth_deprecated(inst, p, vc);   r.insert(r.end(), a2.begin(), a2.end());
        auto a3 = engine_rpcauth_batch(inst, p, vc);        r.insert(r.end(), a3.begin(), a3.end());
        return r;
    }

    // ================================================================
    // 85.17: WALLET BACKUP & RECOVERY ATTACK ENGINES
    // ================================================================

    // 85.17.1: BACKUP-HOTSWAP — check if wallet backup can be hotswapped while running
    std::vector<DynamicFinding> engine_backup_hotswap(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (!p.wallet_available) {
            results.push_back(make_finding(ver, "backup2", "BK2-HOTSWAP-SKIP", "SKIP", "", 0));
            return results;
        }
        // Create backup
        std::string bk_path = inst.data_directory + "/hotswap_test_" + ver + ".bak";
        auto bk = rpc(inst, "backupwallet", "\"" + bk_path + "\"");
        if (!bk.success || bk.is_error()) {
            results.push_back(make_finding(ver, "backup2", "BK2-HOTSWAP-NOBK", "SKIP", "", 0));
            return results;
        }
        // Check backup file properties
        struct stat st;
        bool bk_exists = stat(bk_path.c_str(), &st) == 0;
        int64_t bk_size = bk_exists ? st.st_size : 0;
        // Check if backup is identical to live wallet
        std::string rd = inst.data_directory + (inst.is_regtest ? "/regtest" : "");
        std::string live_path;
        for (auto& wp : {rd + "/wallets/" + inst.wallet_name + "/wallet.dat",
                        rd + "/wallets/" + inst.wallet_name + "/wallet.sqlite",
                        rd + "/wallet.dat"}) {
            if (stat(wp.c_str(), &st) == 0) { live_path = wp; break; }
        }
        // Scan backup for key material
        std::vector<uint8_t> bk_data;
        if (bk_exists) {
            std::ifstream f(bk_path, std::ios::binary);
            bk_data.resize(std::min((int64_t)2*1024*1024, bk_size));
            f.read(reinterpret_cast<char*>(bk_data.data()), bk_data.size());
            bk_data.resize((size_t)f.gcount());
        }
        auto ks = bk_data.empty() ? KeyScanResult{} : scan_for_key_material(bk_data);
        int keys_in_backup = ks.der_keys + ks.wif_candidates + ks.xprv_strings;
        std::remove(bk_path.c_str());
        if (keys_in_backup > 0 && p.wallet_encrypted)
            results.push_back(make_finding(ver, "backup2", "BK2-HOTSWAP-KEYS-"+ver,
                "HIGH: " + std::to_string(keys_in_backup) +
                " plaintext key patterns in backup of encrypted wallet (size=" +
                std::to_string(bk_size) + "B)", "", 7));
        else
            results.push_back(make_finding(ver, "backup2", "BK2-HOTSWAP-OK-"+ver,
                "PASS: Backup size=" + std::to_string(bk_size) + "B keys=" +
                std::to_string(keys_in_backup) + " encrypted=" +
                std::string(p.wallet_encrypted?"Y":"N"), "", 0));
        return results;
    }

    // 85.17.2: BACKUP-DUMPWALLET-LOCK — test dumpwallet while locked
    std::vector<DynamicFinding> engine_backup_dumpwallet_lock(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (!p.wallet_encrypted || !p.wallet_available) {
            results.push_back(make_finding(ver, "backup2", "BK2-DUMPLOCK-SKIP", "SKIP", "", 0));
            return results;
        }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        // Try dumpwallet while locked
        std::string dump_path = inst.data_directory + "/dumpwallet_lock_" + ver + ".txt";
        auto dw = rpc(inst, "dumpwallet", "\"" + dump_path + "\"");
        bool dump_succeeded = dw.success && !dw.is_error();
        // Check if dump file was created and contains keys
        bool has_keys = false;
        if (dump_succeeded) {
            std::ifstream f(dump_path);
            std::string line;
            while (std::getline(f, line)) {
                if (line.find("addr=") != std::string::npos && line.size() > 50) {
                    has_keys = true; break;
                }
            }
        }
        std::remove(dump_path.c_str());
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        if (dump_succeeded && has_keys)
            results.push_back(make_finding(ver, "backup2", "BK2-DUMPLOCK-BYPASS-"+ver,
                "CRITICAL: dumpwallet succeeds with key export while wallet is locked", "", 9));
        else if (dump_succeeded)
            results.push_back(make_finding(ver, "backup2", "BK2-DUMPLOCK-PARTIAL-"+ver,
                "MEDIUM: dumpwallet succeeds while locked but keys appear encrypted", "", 4));
        else
            results.push_back(make_finding(ver, "backup2", "BK2-DUMPLOCK-BLOCKED-"+ver,
                "PASS: dumpwallet blocked while locked", "", 0));
        return results;
    }

    // 85.17.3: BACKUP-LISTADDRESSGROUPINGS — information leak while locked
    std::vector<DynamicFinding> engine_backup_listgroups(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (!p.wallet_available) {
            results.push_back(make_finding(ver, "backup2", "BK2-LISTGRP-SKIP", "SKIP", "", 0));
            return results;
        }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        auto lag = rpc(inst, "listaddressgroupings");
        bool groups_available = lag.success && !lag.is_error() && lag.output.size() > 10;
        // Count addresses revealed
        int addr_count = 0;
        size_t pos = 0;
        while ((pos = lag.output.find("bcrt1", pos+1)) != std::string::npos) addr_count++;
        pos = 0;
        while ((pos = lag.output.find("\"m", pos+1)) != std::string::npos) addr_count++;
        // Also check listtransactions
        auto lt = rpc(inst, "listtransactions");
        bool txs_available = lt.success && !lt.is_error() && lt.output.size() > 10;
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        int total_leaked = (groups_available ? addr_count : 0) + (txs_available ? 1 : 0);
        if (total_leaked > 0)
            results.push_back(make_finding(ver, "backup2", "BK2-LISTGRP-LEAK-"+ver,
                "LOW: " + std::to_string(addr_count) + " addresses + " +
                std::string(txs_available?"tx history":"no txs") + " visible while locked", "", 2));
        else
            results.push_back(make_finding(ver, "backup2", "BK2-LISTGRP-BLOCKED-"+ver,
                "PASS: Address groupings blocked while locked", "", 0));
        return results;
    }

    // Backup/recovery family dispatcher
    std::vector<DynamicFinding> engine_backup2_family(VersionInstance& inst, const ChainParams& p, const VersionRpcCache& vc) {
        ScopedProfile prof("BACKUP2", "backup2_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto b1 = engine_backup_hotswap(inst, p, vc);         r.insert(r.end(), b1.begin(), b1.end());
        auto b2 = engine_backup_dumpwallet_lock(inst, p, vc);  r.insert(r.end(), b2.begin(), b2.end());
        auto b3 = engine_backup_listgroups(inst, p, vc);       r.insert(r.end(), b3.begin(), b3.end());
        return r;
    }

    // ================================================================
    // 85.18: BLOCK VALIDATION & REORG SECURITY ENGINES
    // ================================================================

    // 85.18.1: REORG-HANDLING — check invalidateblock/reconsiderblock behaviour
    std::vector<DynamicFinding> engine_reorg_handling(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (p.current_height < 10) {
            results.push_back(make_finding(ver, "reorg", "REORG-SKIP", "SKIP", "", 0));
            return results;
        }
        // Get current tip
        auto bci = rpc_cached(inst, "getblockchaininfo");
        std::string best_hash = jx(bci.output, "bestblockhash");
        int height_before = p.current_height;
        // Invalidate the tip
        auto inv = rpc(inst, "invalidateblock", "\"" + best_hash + "\"");
        bool inv_ok = inv.success && !inv.is_error();
        if (!inv_ok) {
            results.push_back(make_finding(ver, "reorg", "REORG-NOINV", "SKIP", "", 0));
            return results;
        }
        // Check new height
        auto bci2 = rpc(inst, "getblockchaininfo");
        std::string height_after_str = jx(bci2.output, "blocks");
        int height_after = 0; try { height_after = std::stoi(height_after_str); } catch (...) {}
        bool reorged = height_after < height_before;
        // Reconsider block to restore
        rpc(inst, "reconsiderblock", "\"" + best_hash + "\"");
        auto bci3 = rpc(inst, "getblockchaininfo");
        std::string height_restored_str = jx(bci3.output, "blocks");
        int height_restored = 0; try { height_restored = std::stoi(height_restored_str); } catch (...) {}
        bool restored = height_restored >= height_before;
        // Check wallet balance consistency through reorg
        auto bal_after_reorg = rpc(inst, "getbalance");
        results.push_back(make_finding(ver, "reorg", "REORG-HANDLING-"+ver,
            "VERSION-DIFF: invalidate=" + std::string(reorged?"Y":"N") +
            " height=" + std::to_string(height_before) + "->" + std::to_string(height_after) +
            "->" + std::to_string(height_restored) +
            " restored=" + std::string(restored?"Y":"N") + " em=" + std::to_string(em),
            "", (!restored) ? 5 : 0));
        return results;
    }

    // 85.18.2: HEADER-VALIDATION — check header-only validation behaviour
    std::vector<DynamicFinding> engine_reorg_headers(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        // Get chain tips to detect any forks
        auto ct = rpc(inst, "getchaintips");
        if (!ct.success || ct.is_error()) {
            results.push_back(make_finding(ver, "reorg", "REORG-HDR-SKIP", "SKIP", "", 0));
            return results;
        }
        int tips = 0; int headers_only = 0; int valid_fork = 0;
        size_t pos = 0;
        while ((pos = ct.output.find("\"status\"", pos+1)) != std::string::npos) {
            tips++;
            size_t val_start = ct.output.find(":", pos) + 1;
            size_t val_end = ct.output.find(",", val_start);
            if (val_end == std::string::npos) val_end = ct.output.find("}", val_start);
            std::string status = ct.output.substr(val_start, val_end - val_start);
            if (status.find("headers-only") != std::string::npos) headers_only++;
            if (status.find("valid-fork") != std::string::npos) valid_fork++;
        }
        results.push_back(make_finding(ver, "reorg", "REORG-HDR-"+ver,
            "VERSION-DIFF: tips=" + std::to_string(tips) + " headers_only=" +
            std::to_string(headers_only) + " valid_fork=" + std::to_string(valid_fork) +
            " em=" + std::to_string(em), "", 0));
        return results;
    }

    // 85.18.3: ASSUMEVALID-FINGERPRINT — check assumevalid block
    std::vector<DynamicFinding> engine_reorg_assumevalid(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        // Check for version-specific consensus parameters
        auto bci = rpc_cached(inst, "getblockchaininfo");
        // Try getdeploymentinfo (v23+) for more detailed info
        auto di = rpc(inst, "getdeploymentinfo");
        bool has_deployment_info = di.success && !di.is_error();
        int deployments = 0;
        if (has_deployment_info) {
            size_t pos = 0;
            while ((pos = di.output.find("\"type\"", pos+1)) != std::string::npos) deployments++;
        }
        // Check for specific deployment statuses
        bool has_csv = bci.has("\"csv\"");
        bool has_segwit = bci.has("\"segwit\"");
        bool has_taproot = bci.has("\"taproot\"");
        results.push_back(make_finding(ver, "reorg", "REORG-ASSUMEVALID-"+ver,
            "VERSION-DIFF: deploymentinfo=" + std::string(has_deployment_info?"Y":"N") +
            " deployments=" + std::to_string(deployments) +
            " csv=" + std::string(has_csv?"Y":"N") +
            " segwit=" + std::string(has_segwit?"Y":"N") +
            " taproot=" + std::string(has_taproot?"Y":"N") + " em=" + std::to_string(em),
            "", 0));
        return results;
    }

    // Reorg/validation family dispatcher
    std::vector<DynamicFinding> engine_reorg_family(VersionInstance& inst, const ChainParams& p, const VersionRpcCache& vc) {
        ScopedProfile prof("REORG", "reorg_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto r1 = engine_reorg_handling(inst, p, vc);       r.insert(r.end(), r1.begin(), r1.end());
        auto r2 = engine_reorg_headers(inst, p, vc);        r.insert(r.end(), r2.begin(), r2.end());
        auto r3 = engine_reorg_assumevalid(inst, p, vc);    r.insert(r.end(), r3.begin(), r3.end());
        return r;
    }

    // ================================================================
    // 85.19: WALLET ENCRYPTION LIFECYCLE ENGINES
    // ================================================================

    // 85.19.1: ENC-WALLETPASSPHRASE-TIMING — measure walletpassphrase timing
    // variations across different password lengths to detect timing oracle
    std::vector<DynamicFinding> engine_enc_timing_oracle(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc, const std::string& state) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_encrypted) {
            results.push_back(make_finding(ver, "enclife", "ENCL-TIMING-SKIP-"+state, "SKIP", "", 0));
            return results;
        }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        // Measure timing for passwords of varying lengths
        std::vector<std::pair<int,double>> length_timings;
        for (int len : {1, 4, 8, 16, 32, 64}) {
            auto tm = timed_rpc(inst, "walletpassphrase",
                "[\"" + std::string(len, 'X') + "\",1]");
            length_timings.push_back({len, tm.elapsed_ms});
        }
        // Check for correlation between length and timing
        double min_t = 1e9, max_t = 0;
        for (auto& [l, t] : length_timings) { min_t = std::min(min_t, t); max_t = std::max(max_t, t); }
        double range = max_t - min_t;
        double ratio = (min_t > 0.1) ? max_t / min_t : 1.0;
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        char rb[32]; snprintf(rb, sizeof(rb), "%.2f", ratio);
        if (ratio > 2.0)
            results.push_back(make_finding(ver, "enclife", "ENCL-TIMING-ORACLE-"+state+"-"+ver,
                "MEDIUM["+state+"]: Timing varies " + std::string(rb) + "x across password lengths (" +
                std::to_string((int)min_t) + "-" + std::to_string((int)max_t) +
                "ms) — length-dependent oracle", "", 5));
        else
            results.push_back(make_finding(ver, "enclife", "ENCL-TIMING-OK-"+state+"-"+ver,
                "PASS["+state+"]: Timing ratio=" + std::string(rb) + " (constant-time)", "", 0));
        return results;
    }

    // 85.19.2: ENC-WALLETPASSPHRASECHANGE — test passphrase change semantics
    std::vector<DynamicFinding> engine_enc_passchange(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc, const std::string& state) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (!p.wallet_encrypted) {
            results.push_back(make_finding(ver, "enclife", "ENCL-PASSCHG-SKIP-"+state, "SKIP", "", 0));
            return results;
        }
        // Test passphrase change while wallet is locked vs unlocked
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        // Try changing passphrase while locked
        std::string new_pass = "encl_new_pass_" + ver + "_" + state;
        auto pc_locked = rpc(inst, "walletpassphrasechange",
            "\"" + wallet_encryption_passphrase_ + "\" \"" + new_pass + "\"");
        bool change_while_locked = pc_locked.success && !pc_locked.is_error();
        if (change_while_locked) {
            // Verify new passphrase works
            auto verify = rpc(inst, "walletpassphrase", "\"" + new_pass + "\" 600");
            bool new_works = verify.success && !verify.is_error();
            // Change back
            rpc(inst, "walletpassphrasechange", "\"" + new_pass + "\" \"" + wallet_encryption_passphrase_ + "\"");
            results.push_back(make_finding(ver, "enclife", "ENCL-PASSCHG-LOCKED-"+state+"-"+ver,
                "INFO["+state+"]: walletpassphrasechange works while locked, new_verified=" +
                std::string(new_works?"Y":"N"), "", 0));
        } else {
            rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
            results.push_back(make_finding(ver, "enclife", "ENCL-PASSCHG-BLOCKED-"+state+"-"+ver,
                "INFO["+state+"]: walletpassphrasechange requires unlock", "", 0));
        }
        return results;
    }

    // 85.19.3: ENC-IMPORT-UNENCRYPTED — check if importprivkey while unlocked
    // stores key unencrypted in any file
    std::vector<DynamicFinding> engine_enc_import_unenc(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc, const std::string& state) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (!p.wallet_encrypted || vc.has_descriptor_wallet) {
            results.push_back(make_finding(ver, "enclife", "ENCL-IMPORT-SKIP-"+state, "SKIP", "", 0));
            return results;
        }
        // Generate a test key externally
        std::string test_key = "cNW2wYBFhfSTNv5Fy4FkFbVp49dREsjGiSVjqR7C3TxZNdjXX1sE";
        // Try importing while unlocked
        auto imp = rpc(inst, "importprivkey", "\"" + test_key + "\" \"encl_test\" false");
        bool imported = imp.success && !imp.is_error();
        if (!imported) {
            results.push_back(make_finding(ver, "enclife", "ENCL-IMPORT-FAIL-"+state, "SKIP", "", 0));
            return results;
        }
        // Lock wallet and check if the imported key is still accessible
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        auto dp = rpc(inst, "dumpprivkey", "\"$(bitcoin-cli -regtest getaddressesbylabel encl_test 2>/dev/null | head -1)\"");
        bool leaked = dp.success && !dp.is_error() && dp.output.find(test_key) != std::string::npos;
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        if (leaked)
            results.push_back(make_finding(ver, "enclife", "ENCL-IMPORT-LEAK-"+state+"-"+ver,
                "HIGH["+state+"]: Imported key accessible while locked", "", 7));
        else
            results.push_back(make_finding(ver, "enclife", "ENCL-IMPORT-OK-"+state+"-"+ver,
                "PASS["+state+"]: Imported key properly encrypted", "", 0));
        return results;
    }

    // Encryption lifecycle family dispatcher
    std::vector<DynamicFinding> engine_enclife_family(VersionInstance& inst, const ChainParams& p, const VersionRpcCache& vc) {
        ScopedProfile prof("ENCLIFE", "enclife_" + inst.version_string);
        return backtest_three_states(inst, p, "ENCLIFE", [this, &vc](auto& i, auto& p2, const std::string& st) {
            std::vector<DynamicFinding> r;
            auto e1 = engine_enc_timing_oracle(i, p2, vc, st);   r.insert(r.end(), e1.begin(), e1.end());
            auto e2 = engine_enc_passchange(i, p2, vc, st);      r.insert(r.end(), e2.begin(), e2.end());
            auto e3 = engine_enc_import_unenc(i, p2, vc, st);    r.insert(r.end(), e3.begin(), e3.end());
            return r;
        });
    }

