    // 85.20: SPEED-OPTIMIZED VERSION-AWARE HELPER ENGINES
    // ================================================================

    // 85.20.1: SPEED-RPC-COUNT — fast RPC surface comparison
    std::vector<DynamicFinding> engine_speed_rpc_count(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        // Quick hash of all available RPCs for fast differentiation
        auto help = rpc_cached(inst, "help");
        size_t rpc_hash = std::hash<std::string>{}(help.output);
        results.push_back(make_finding(ver, "speed", "SPEED-RPCHASH-"+ver,
            "UNIQUENESS: rpc_hash=" + std::to_string(rpc_hash) + " em=" + std::to_string(em),
            "", 0));
        return results;
    }

    // 85.20.2: SPEED-BUILDINFO — version build info fingerprint
    std::vector<DynamicFinding> engine_speed_buildinfo(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        // Binary hash for version differentiation
        std::string hash_cmd = "shasum -a 256 '" + inst.binary_path + "' 2>/dev/null | cut -c1-16";
        auto hr = popen_with_timeout(hash_cmd, 2);
        std::string bin_hash = hr.timed_out ? "timeout" : hr.output;
        while (!bin_hash.empty() && bin_hash.back()=='\n') bin_hash.pop_back();
        // Build date from --version
        std::string ver_cmd = "'" + inst.binary_path + "' --version 2>/dev/null | head -1";
        auto vr = popen_with_timeout(ver_cmd, 2);
        std::string ver_line = vr.timed_out ? "timeout" : vr.output;
        while (!ver_line.empty() && ver_line.back()=='\n') ver_line.pop_back();
        results.push_back(make_finding(ver, "speed", "SPEED-BUILD-"+ver,
            "UNIQUENESS: hash=" + bin_hash + " version=" + ver_line + " em=" + std::to_string(em),
            "", 0));
        return results;
    }

    // 85.20.3: SPEED-CHAIN-FINGERPRINT — fast chain state comparison
    std::vector<DynamicFinding> engine_speed_chain_fp(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        // Combine multiple version-specific attributes into one finding
        auto bci = rpc_cached(inst, "getblockchaininfo");
        auto mi = rpc(inst, "getmempoolinfo");
        std::string composite = "v=" + ver + " proto=" + std::to_string(vc.protocol_version) +
            " subv=" + vc.subversion + " desc=" + std::string(vc.has_descriptor_wallet?"Y":"N") +
            " kpool=" + std::to_string(vc.keypool_size) + " iter=" + std::to_string(vc.pbkdf2_iterations) +
            " maxmp=" + jx(mi.output, "maxmempool");
        size_t composite_hash = std::hash<std::string>{}(composite);
        results.push_back(make_finding(ver, "speed", "SPEED-COMPOSITE-"+ver,
            "UNIQUENESS: " + composite + " hash=" + std::to_string(composite_hash), "", 0));
        return results;
    }

    // Speed family dispatcher
    std::vector<DynamicFinding> engine_speed_family(VersionInstance& inst, const ChainParams& p, const VersionRpcCache& vc) {
        ScopedProfile prof("SPEED", "speed_" + inst.version_string);
        std::vector<DynamicFinding> r;
        auto s1 = engine_speed_rpc_count(inst, p, vc);   r.insert(r.end(), s1.begin(), s1.end());
        auto s2 = engine_speed_buildinfo(inst, p, vc);   r.insert(r.end(), s2.begin(), s2.end());
        auto s3 = engine_speed_chain_fp(inst, p, vc);    r.insert(r.end(), s3.begin(), s3.end());
        return r;
    }

    // ================================================================

    // ================================================================
    // 85.22: ENCRYPTION KEY SCHEDULE ANALYSIS ENGINES
    // ================================================================

    // 85.22.1: KEY-SCHEDULE-CORRELATION — detect key schedule weaknesses
    std::vector<DynamicFinding> engine_keysched_correlation(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc, const std::string& state) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (!p.wallet_encrypted) {
            results.push_back(make_finding(ver, "keysched", "KS-CORR-SKIP-"+state, "SKIP", "", 0));
            return results;
        }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        // Probe error message diversity as a proxy for key schedule strength
        // Different password prefixes should produce indistinguishable errors
        std::map<std::string, int> error_distribution;
        int num_probes = inst.is_regtest ? 12 : 6;
        for (int i = 0; i < num_probes; i++) {
            std::string pw = "ks_probe_" + std::to_string(i) + "_" + std::string(i * 4 + 1, char('a' + i));
            auto r = rpc(inst, "walletpassphrase", "[\"" + pw + "\",1]");
            std::string err_key = jx(r.output, "code") + "|" + std::to_string(r.output.size() % 100);
            error_distribution[err_key]++;
        }
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        // All probes should produce identical error responses
        bool uniform_errors = error_distribution.size() <= 2;
        results.push_back(make_finding(ver, "keysched", "KS-CORR-"+state+"-"+ver,
            std::string(uniform_errors ? "PASS" : "MEDIUM") + "[" + state + "]: " +
            std::to_string(error_distribution.size()) + " distinct error classes from " +
            std::to_string(num_probes) + " probes — " +
            std::string(uniform_errors ? "consistent" : "information leakage via error diversity") +
            " backend=" + std::string(em >= 23 ? "SQLite" : "BDB") +
            " iter=" + std::to_string(vc.pbkdf2_iterations),
            "", uniform_errors ? 0 : 4));
        return results;
    }

    // 85.22.2: KEY-SCHEDULE-MEMORY — check if key schedule remains in memory after lock
    std::vector<DynamicFinding> engine_keysched_memory(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc, const std::string& state) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string; int em = effective_major(ver);
        if (!p.wallet_encrypted) {
            results.push_back(make_finding(ver, "keysched", "KS-MEM-SKIP-"+state, "SKIP", "", 0));
            return results;
        }
        // Unlock, perform key operations, then lock and check for residual patterns
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 5");
        // Generate addresses to force key derivation
        for (int i = 0; i < 5; i++) rpc_fast(inst, "getnewaddress", "[]");
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(500));
        // Check if wallet RPC still returns key-related info
        auto wi = rpc(inst, "getwalletinfo");
        std::string keypoolsize_after = jx(wi.output, "keypoolsize");
        // Try signmessage (should fail if properly locked)
        std::string addr = p.test_addresses.empty() ? "bcrt1qtest" : p.test_addresses[0];
        auto sm = rpc(inst, "signmessage", "\"" + addr + "\" \"residual_test\"");
        bool sign_after_lock = sm.success && !sm.is_error();
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        if (sign_after_lock)
            results.push_back(make_finding(ver, "keysched", "KS-MEM-RESIDUAL-"+state+"-"+ver,
                "HIGH["+state+"]: signmessage succeeded after walletlock — key schedule residual", "", 7));
        else
            results.push_back(make_finding(ver, "keysched", "KS-MEM-OK-"+state+"-"+ver,
                "PASS["+state+"]: Key schedule cleared after lock, keypool=" + keypoolsize_after, "", 0));
        return results;
    }

    // 85.22.3: KEY-SCHEDULE-BRANCH-PRED — branch prediction side-channel via timing
    std::vector<DynamicFinding> engine_keysched_branch_pred(VersionInstance& inst, const ChainParams& p,
            const VersionRpcCache& vc, const std::string& state) {
        std::vector<DynamicFinding> results;
        std::string ver = inst.version_string;
        if (!p.wallet_encrypted) {
            results.push_back(make_finding(ver, "keysched", "KS-BP-SKIP-"+state, "SKIP", "", 0));
            return results;
        }
        rpc(inst, "walletlock"); std::this_thread::sleep_for(std::chrono::milliseconds(200));
        // Measure timing distribution for identical passwords repeated
        std::vector<double> timings;
        std::string fixed_pw = "branch_pred_probe_fixed_12345";
        int samples = inst.is_regtest ? 8 : 4;
        for (int i = 0; i < samples; i++) {
            auto tm = timed_rpc(inst, "walletpassphrase", "[\"" + fixed_pw + "\",1]");
            timings.push_back(tm.elapsed_ms);
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
        }
        // Calculate jitter — high jitter suggests branch prediction effects
        double sum = 0; for (auto t : timings) sum += t;
        double mean = sum / timings.size();
        double max_dev = 0;
        for (auto t : timings) { double d = std::abs(t - mean); if (d > max_dev) max_dev = d; }
        double jitter_pct = (mean > 0.1) ? (max_dev / mean * 100.0) : 0;
        rpc(inst, "walletpassphrase", "\"" + wallet_encryption_passphrase_ + "\" 600");
        char jb[32]; snprintf(jb, sizeof(jb), "%.1f", jitter_pct);
        results.push_back(make_finding(ver, "keysched", "KS-BP-"+state+"-"+ver,
            std::string(jitter_pct > 30 ? "LOW" : "PASS") + "[" + state + "]: timing jitter=" +
            std::string(jb) + "% mean=" + std::to_string((int)mean) + "ms samples=" +
            std::to_string(samples), "", jitter_pct > 30 ? 2 : 0));
        return results;
    }

    // Key schedule family dispatcher
    std::vector<DynamicFinding> engine_keysched_family(VersionInstance& inst, const ChainParams& p, const VersionRpcCache& vc) {
        ScopedProfile prof("KEYSCHED", "keysched_" + inst.version_string);
        return backtest_three_states(inst, p, "KEYSCHED", [this, &vc](auto& i, auto& p2, const std::string& st) {
            std::vector<DynamicFinding> r;
            auto k1 = engine_keysched_correlation(i, p2, vc, st);   r.insert(r.end(), k1.begin(), k1.end());
            auto k2 = engine_keysched_memory(i, p2, vc, st);        r.insert(r.end(), k2.begin(), k2.end());
            auto k3 = engine_keysched_branch_pred(i, p2, vc, st);   r.insert(r.end(), k3.begin(), k3.end());
            return r;
        });
    }

