    // ================================================================
    // 88.17: SI-OVERFLOW-ANALYSIS — BDB Overflow Page Usage Analysis
    // Detects abnormal numbers of overflow pages which may indicate
    // large value storage or database fragmentation issues.
    // ================================================================
    std::vector<DynamicFinding> engine_s88_overflow_analysis(
        VersionInstance& inst, const ChainParams& params, const std::string& edir) {
        ScopedProfile prof("S88-OA","s88_oa_"+inst.version_string);
        std::vector<DynamicFinding> res;
        std::string ver=inst.version_string;
        if (!params.wallet_available||inst.node_dead_) {
            res.push_back(make_finding(ver,"sec88_oa","SI-OA-SKIP-"+ver,"SKIP: wallet or node unavailable","",0)); return res;
        }
        EnhancedStructuredLogger::instance()->log(LogLevel::INFO,"sec88",ver+": 88.17 starting");
        std::string walletdir=inst.data_directory;
        if (inst.is_regtest) walletdir+="/regtest";
        std::string walletpath=walletdir+"/wallet.dat";
        struct stat ws;
        bool file_ok=(stat(walletpath.c_str(),&ws)==0);
        int64_t fsize=file_ok?(int64_t)ws.st_size:0;
        // Heuristic: if file size >> typical wallet size, overflow pages are likely
        int64_t threshold=50*1024*1024; // 50MB
        bool large_file=(fsize>threshold);
        std::string m="fsize="+std::to_string(fsize)+" threshold="+std::to_string(threshold)+" large="+std::to_string(large_file);
        EnhancedStructuredLogger::instance()->log(LogLevel::INFO,"sec88",ver+": 88.17 meas: "+m);
        if (large_file) {
            auto f=s88_emit(ver,"SI-OA-LARGE","SI-OA-LARGE-"+ver,
                "CONFIRMED: wallet.dat size "+std::to_string(fsize/1024/1024)+"MB exceeds threshold — "
                "excessive overflow pages or fragmentation suspected",
                4,s88_confidence(6,10,1,0),
                s88_triple_confirm([&]{return large_file;}),true,m);
            res.insert(res.end(),f.begin(),f.end());
        } else {
            res.push_back(make_finding(ver,"sec88_oa","SI-OA-PASS-"+ver,
                "PASS: Overflow analysis — file size within expected range fsize="+std::to_string(fsize),"",0));
        }
        EnhancedStructuredLogger::instance()->log(LogLevel::INFO,"sec88",ver+": 88.17 done");
        return res;
    }

    // ================================================================
    // 88.18: SI-BTREE-DEPTH-ANALYSIS — BDB B-tree Depth Measurement
