    // 94.01: MK-REDEEMSCRIPT-LEAK — P2SH redeemScript exposure while locked
    // getaddressinfo reveals full redeemScript for P2SH UTXOs, leaking
    // multisig threshold, participant pubkeys, and witness structure
    std::vector<DynamicFinding> engine_mk_redeemscript_leak(
        VersionInstance& inst, const ChainParams& params, const std::string& edir) {
        ScopedProfile prof("MK-REDEEM", "mk_redeem_" + inst.version_string);
        auto trace = s89_begin("MK-REDEEMSCRIPT", inst.version_string);
        std::vector<DynamicFinding> res;
        std::string ver = inst.version_string;

        rpc(inst, "walletlock");

        auto lu = rpc(inst, "listunspent");
        if (lu.is_error()) {
            res.push_back(make_finding(ver,"sec94_rs","MK-REDEEM-SKIP-"+ver,
                "SKIP: listunspent failed","",0));
            return res;
        }
        auto uj = nlohmann_json_parse(lu.output);
        if (!uj.is_array() || uj.empty()) {
            res.push_back(make_finding(ver,"sec94_rs","MK-REDEEM-SKIP-"+ver,
                "SKIP: no UTXOs","",0));
            return res;
        }

        int utxos_checked = 0;
        int redeem_exposed = 0;
        int witness_exposed = 0;
        int pubkeys_leaked = 0;
        int multisig_detected = 0;
        std::vector<std::string> exposed_details;

        for (auto& u : uj) {
            std::string addr = u.value("address","");
            if (addr.empty()) continue;
            utxos_checked++;
            trace.samples++;

            auto ai = rpc(inst, "getaddressinfo", "\"" + addr + "\"");
            if (ai.is_error()) continue;
            auto aj = nlohmann_json_parse(ai.output);

            // Check for exposed redeemScript
            std::string redeem = aj.value("hex","");
            if (redeem.empty()) redeem = aj.value("redeemscript","");
            // Check embedded field (P2SH-P2WPKH has nested structure)
            if (aj.contains("embedded")) {
                auto& emb = aj["embedded"];
                std::string emb_hex = emb.value("hex","");
                std::string emb_script = emb.value("script","");
                std::string emb_redeem = emb.value("redeemscript","");
                if (!emb_hex.empty() || !emb_script.empty()) {
                    witness_exposed++;
                    std::string detail = addr.substr(0,12) + ": embedded script exposed";
                    if (!emb_script.empty()) detail += " type=" + emb_script;
                    // Count exposed pubkeys
                    if (emb.contains("pubkeys") && emb["pubkeys"].is_array()) {
                        int pk_count = emb["pubkeys"].size();
                        pubkeys_leaked += pk_count;
                        detail += " pubkeys=" + std::to_string(pk_count);
                    }
                    if (emb.contains("pubkey")) {
                        pubkeys_leaked++;
                    }
                    exposed_details.push_back(detail);
                }
            }

            // Check for direct redeemScript (P2SH multisig)
            if (aj.contains("sigsrequired")) {
                int sigsreq = aj.value("sigsrequired",0);
                if (sigsreq > 0) {
                    multisig_detected++;
                    std::string detail = addr.substr(0,12) + ": multisig " +
                        std::to_string(sigsreq) + "-of-?";
                    if (aj.contains("pubkeys") && aj["pubkeys"].is_array()) {
                        detail += " (" + std::to_string(aj["pubkeys"].size()) + " pubkeys exposed)";
                        pubkeys_leaked += aj["pubkeys"].size();
                    }
                    exposed_details.push_back(detail);
                    redeem_exposed++;
                }
            }

            // Even single-sig P2SH-P2WPKH exposes the witness program
            std::string script_type = aj.value("script","");
            if (!script_type.empty() && script_type != "pubkeyhash") {
                redeem_exposed++;
            }

            if (utxos_checked >= 10) break;
        }

        std::string m = "checked=" + std::to_string(utxos_checked) +
            " redeem_exposed=" + std::to_string(redeem_exposed) +
            " witness_exposed=" + std::to_string(witness_exposed) +
            " pubkeys_leaked=" + std::to_string(pubkeys_leaked) +
            " multisig=" + std::to_string(multisig_detected);
        trace.raw_data = m;
        trace.confidence = (redeem_exposed > 0 || witness_exposed > 0) ? 0.97 : 0.0;
        trace.confirmations = s89_triple([&]{ return utxos_checked > 0; }) ? 3 : 0;

        EnhancedStructuredLogger::instance()->log(LogLevel::INFO, "sec94",
            ver + ": 94.01 meas: " + m);

        if (multisig_detected > 0 && trace.confirmations == 3 && trace.confidence >= 0.95) {
            std::string details_str;
            for (auto& d : exposed_details) details_str += " [" + d + "]";
            trace.narrative = std::to_string(multisig_detected) + " multisig UTXOs expose "
                "their full redeemScript (including threshold and participant pubkeys) via "
                "getaddressinfo while locked. " + std::to_string(pubkeys_leaked) +
                " pubkeys leaked total. Attack: identify co-signers, determine threshold, "
                "target the weakest co-signer's key for compromise." + details_str;
            auto f = s89_emit(ver, "MK-REDEEMSCRIPT", "MK-REDEEM-MULTISIG-LEAK-"+ver,
                "CONFIRMED: " + std::to_string(multisig_detected) +
                " multisig redeemScripts exposed while locked. " + trace.narrative,
                7, trace.confidence, trace);
            res.insert(res.end(), f.begin(), f.end());
        } else if ((redeem_exposed > 0 || witness_exposed > 0) &&
                   trace.confirmations == 3 && trace.confidence >= 0.95) {
            trace.narrative = std::to_string(redeem_exposed + witness_exposed) +
                " UTXOs expose script structure while locked (" +
                std::to_string(pubkeys_leaked) + " pubkeys). Combined with ckey mapping, "
                "this reveals the exact locking conditions for each UTXO.";
            auto f = s89_emit(ver, "MK-REDEEMSCRIPT", "MK-REDEEM-SCRIPT-LEAK-"+ver,
                "CONFIRMED: script structure exposed for " +
                std::to_string(redeem_exposed + witness_exposed) + " UTXOs while locked. " +
                trace.narrative, 6, trace.confidence, trace);
            res.insert(res.end(), f.begin(), f.end());
        } else {
            res.push_back(make_finding(ver,"sec94_rs","MK-REDEEM-PASS-"+ver,
                "PASS: no significant redeemScript exposure. " + m,"",0));
        }
        return res;
    }

    // 94.02: MK-TX-HISTORY-PROFILE — Transaction history exposure while locked
    // listtransactions reveals full financial profile: amounts, timestamps,
    // counterparty addresses, fee patterns — enabling targeted social engineering
    std::vector<DynamicFinding> engine_mk_tx_history_profile(
        VersionInstance& inst, const ChainParams& params, const std::string& edir) {
        ScopedProfile prof("MK-TXHIST", "mk_txhist_" + inst.version_string);
        auto trace = s89_begin("MK-TX-HISTORY", inst.version_string);
        std::vector<DynamicFinding> res;
        std::string ver = inst.version_string;

        rpc(inst, "walletlock");

        // Phase 1: Query transaction history while locked
        auto lt = rpc(inst, "listtransactions", "\"*\" 100");
        if (lt.is_error()) {
            res.push_back(make_finding(ver,"sec94_tx","MK-TXHIST-SKIP-"+ver,
                "SKIP: listtransactions failed while locked","",0));
            return res;
        }
        auto tj = nlohmann_json_parse(lt.output);
        if (!tj.is_array()) {
            res.push_back(make_finding(ver,"sec94_tx","MK-TXHIST-SKIP-"+ver,
                "SKIP: invalid response from listtransactions","",0));
            return res;
        }

        int tx_count = tj.size();
        trace.samples++;

        if (tx_count == 0) {
            res.push_back(make_finding(ver,"sec94_tx","MK-TXHIST-EMPTY-"+ver,
                "INFO: no transaction history available while locked","",0));
            return res;
        }

        // Phase 2: Analyse what information is exposed
        double total_received = 0, total_sent = 0;
        int receive_count = 0, send_count = 0;
        std::set<std::string> counterparty_addrs;
        int64_t earliest_time = INT64_MAX, latest_time = 0;
        std::set<std::string> labels_exposed;
        double max_single_tx = 0;
        int fee_visible_count = 0;

        for (auto& tx : tj) {
            std::string category = tx.value("category","");
            double amount = std::abs(tx.value("amount",0.0));
            int64_t txtime = tx.value("time", (int64_t)0);
            std::string addr = tx.value("address","");
            std::string label = tx.value("label","");
            double fee = std::abs(tx.value("fee",0.0));

            if (category == "receive") {
                receive_count++;
                total_received += amount;
            } else if (category == "send") {
                send_count++;
                total_sent += amount;
            }

            if (!addr.empty()) counterparty_addrs.insert(addr);
            if (txtime > 0 && txtime < earliest_time) earliest_time = txtime;
            if (txtime > latest_time) latest_time = txtime;
            if (!label.empty()) labels_exposed.insert(label);
            if (amount > max_single_tx) max_single_tx = amount;
            if (fee > 0) fee_visible_count++;
            trace.samples++;
        }

        // Phase 3: Compute exposure severity
        // More information = more useful for targeted attacks
        int exposure_score = 0;
        if (tx_count >= 10) exposure_score += 2;
        if (counterparty_addrs.size() >= 5) exposure_score += 2;
        if (send_count > 0) exposure_score += 1; // Sends reveal spending patterns
        if (!labels_exposed.empty()) exposure_score += 2; // Labels often contain PII
        if (fee_visible_count > 0) exposure_score += 1;
        if (max_single_tx > 1.0) exposure_score += 1; // High-value txs
        if (latest_time - earliest_time > 86400 * 30) exposure_score += 1; // >30 days

        // Phase 4: Check listsinceblock (deeper history)
        int sinceblock_count = 0;
        auto lsb = rpc(inst, "listsinceblock");
        if (!lsb.is_error()) {
            auto sj = nlohmann_json_parse(lsb.output);
            if (sj.contains("transactions") && sj["transactions"].is_array()) {
                sinceblock_count = sj["transactions"].size();
                if (sinceblock_count > tx_count) exposure_score += 1;
            }
        }

        std::string m = "txs=" + std::to_string(tx_count) +
            " received=" + std::to_string(receive_count) +
            " sent=" + std::to_string(send_count) +
            " total_recv=" + std::to_string(total_received).substr(0,12) +
            " total_sent=" + std::to_string(total_sent).substr(0,12) +
            " counterparties=" + std::to_string(counterparty_addrs.size()) +
            " labels=" + std::to_string(labels_exposed.size()) +
            " fees_visible=" + std::to_string(fee_visible_count) +
            " sinceblock=" + std::to_string(sinceblock_count) +
            " exposure_score=" + std::to_string(exposure_score);
        trace.raw_data = m;
        trace.confidence = (exposure_score >= 5) ? 0.97 :
                          (exposure_score >= 3 ? 0.96 : 0.0);
        trace.confirmations = s89_triple([&]{ return tx_count > 0; }) ? 3 : 0;

        EnhancedStructuredLogger::instance()->log(LogLevel::INFO, "sec94",
            ver + ": 94.02 meas: " + m);

        if (exposure_score >= 5 && trace.confirmations == 3 && trace.confidence >= 0.95) {
            trace.narrative = "While locked, listtransactions exposes " +
                std::to_string(tx_count) + " transactions: " +
                std::to_string(receive_count) + " receives (" +
                std::to_string(total_received).substr(0,10) + " BTC), " +
                std::to_string(send_count) + " sends (" +
                std::to_string(total_sent).substr(0,10) + " BTC), " +
                std::to_string(counterparty_addrs.size()) + " counterparty addresses, " +
                std::to_string(labels_exposed.size()) + " labels" +
                (labels_exposed.size() > 0 ? " (labels often contain names/descriptions)" : "") +
                ". Attack: build a complete financial profile for social engineering, "
                "identify high-value counterparties, determine spending patterns, "
                "and time attacks to coincide with expected transactions.";
            auto f = s89_emit(ver, "MK-TX-HISTORY", "MK-TXHIST-PROFILE-"+ver,
                "CONFIRMED: comprehensive financial profile exposed while locked — " +
                std::to_string(tx_count) + " txs, " +
                std::to_string(counterparty_addrs.size()) + " counterparties, " +
                std::to_string(labels_exposed.size()) + " labels. " + trace.narrative,
                7, trace.confidence, trace);
            res.insert(res.end(), f.begin(), f.end());
        } else if (tx_count > 0 && trace.confirmations == 3) {
            res.push_back(make_finding(ver,"sec94_tx","MK-TXHIST-LIMITED-"+ver,
                "INFO: " + std::to_string(tx_count) + " transactions visible while locked "
                "but exposure is limited (score=" + std::to_string(exposure_score) + "/10). " + m,
                "", 3));
        } else {
            res.push_back(make_finding(ver,"sec94_tx","MK-TXHIST-PASS-"+ver,
                "PASS: transaction history not exposed while locked. " + m,"",0));
        }
        return res;
    }

